
/* source: style.css */
:root { color-scheme: dark; --bg:#080914; --panel:rgba(15,18,34,.86); --line:rgba(255,255,255,.1); --muted:#9ca3af; --purple:#7c3aed; --cyan:#06b6d4; }
.route-loading { display:grid; place-items:center; min-height:min(52dvh, 420px); }
.route-loading .panel { width:min(420px,100%); text-align:center; }
.route-loading h1 { font-size:clamp(22px,4vw,32px); margin:.5em 0; }
.route-loading p { color:var(--muted); }
.route-loading-dot { display:inline-block; width:12px; height:12px; border-radius:50%; background:#8debff; box-shadow:0 0 24px #22d3ee66; animation:loading-pulse 1s ease-in-out infinite alternate; }
@keyframes loading-pulse { to { opacity:.35; } }
@media (prefers-reduced-motion:reduce) { .route-loading-dot { animation:none; } }
* { box-sizing:border-box; }
body { margin:0; min-height:100vh; overflow-x:hidden; font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif; background:var(--bg); color:#fff; }
button,input,select,textarea { font:inherit; }
button { border:1px solid transparent; border-radius:14px; padding:11px 15px; background:#25283d; color:#fff; cursor:pointer; transition:transform .18s ease,background .18s ease,border-color .18s ease,box-shadow .18s ease,opacity .18s ease; }
button:hover { transform:translateY(-2px); background:#30354f; border-color:rgba(255,255,255,.1); }
button:active { transform:translateY(0) scale(.98); }
button:disabled { opacity:.45; cursor:not-allowed; transform:none; }
input,textarea,select { width:100%; border:1px solid rgba(148,163,184,.2); border-radius:14px; padding:13px 14px; background:linear-gradient(145deg,rgba(15,23,42,.92),rgba(17,20,37,.96)); color:#fff; outline:none; box-shadow:inset 0 1px 0 rgba(255,255,255,.045),0 10px 24px rgba(0,0,0,.1); transition:border-color .18s,box-shadow .18s,background .18s; }
select option,select optgroup{background:#12162a;color:#f8fafc}
select option:checked{background:#253052;color:#fff}
textarea{min-height:110px;resize:vertical;line-height:1.45}
input::placeholder,textarea::placeholder{color:rgba(203,213,225,.48)}
input:hover,textarea:hover,select:hover{border-color:rgba(103,232,249,.34)}
input:focus,textarea:focus,select:focus { border-color:#67e8f9; box-shadow:0 0 0 4px rgba(6,182,212,.14),inset 0 1px 0 rgba(255,255,255,.06); }
select{width:100%;margin-top:7px;padding:12px 38px 12px 13px;border:1px solid rgba(148,163,184,.2);border-radius:14px;background:linear-gradient(145deg,rgba(15,23,42,.94),rgba(17,20,37,.98));color:#fff;outline:none;box-shadow:inset 0 1px 0 rgba(255,255,255,.045),0 10px 24px rgba(0,0,0,.1);transition:border-color .18s,box-shadow .18s;appearance:none}
input[type="range"] { padding:0; accent-color:#8b5cf6; }
label { display:block; margin-top:14px; color:#cbd5e1; font-size:14px; }
h1 { margin:0 0 10px; font-size:clamp(32px,5vw,54px); line-height:1; }
h2 { margin:0 0 12px; } h3,p { margin-top:0; } .icon { flex:none; }
.app { min-height:100vh; position:relative; overflow:hidden; }
.bg-orb { position:fixed; width:340px; height:340px; border-radius:50%; filter:blur(70px); opacity:.28; pointer-events:none; }
.orb1 { top:-90px; left:-80px; background:#7c3aed; }.orb2 { right:-90px; bottom:-120px; background:#06b6d4; }
.muted { color:var(--muted); }.tiny { color:#a5b4fc; font-size:13px; line-height:1.5; }.eyebrow { margin:0 0 8px; color:#a78bfa; font-size:11px; font-weight:900; letter-spacing:.16em; }
.primary { display:inline-flex; justify-content:center; align-items:center; gap:8px; padding:11px 15px; border:1px solid rgba(103,232,249,.28); border-radius:14px; background:linear-gradient(135deg,var(--purple),var(--cyan)); color:#fff; font-weight:800; line-height:1.2; text-decoration:none; box-shadow:0 9px 24px rgba(6,182,212,.12); }
