@media (max-width: 520px) {
  html { min-width: 0; -webkit-text-size-adjust: 100%; text-size-adjust: 100%; }
  body { width: 100%; max-width: 100vw; min-width: 0; touch-action: manipulation; }
  button, input, select, textarea { min-height: 44px; font-size: 16px; }
  button { width: auto; padding: 10px 12px; border-radius: 13px; }
  h1 { font-size: clamp(25px, 8.4vw, 34px); line-height: 1.08; overflow-wrap: anywhere; }
  h2 { font-size: clamp(22px, 7vw, 30px); line-height: 1.12; overflow-wrap: anywhere; }
  p, b, strong, span, small, label { overflow-wrap: anywhere; }
  .app { width: 100%; max-width: 100vw; overflow-x: clip; }
  .page { width: 100%; padding: 14px 10px calc(72px + env(safe-area-inset-bottom)); }
  .topbar { position: sticky; display: grid; grid-template-columns: 1fr; gap:7px; padding: 8px 8px calc(8px + env(safe-area-inset-top)); overflow: hidden; }
  .brand-zone { min-width: 0; overflow: hidden; }
  .top-actions { display: flex; flex-wrap: wrap; justify-content: flex-start; gap: 5px; min-width: 0; width: 100%; overflow: hidden; }
  .top-actions .money { max-width: 78px; overflow: hidden; padding: 8px 9px; text-overflow: ellipsis; white-space: nowrap; }
  .level-progress-button, .account-button, .icon-btn { min-height: 42px; padding: 7px 8px; }
  .account-button .avatar { width: 30px; height: 30px; }
  .online-count-pill { min-height: 38px; padding: 7px 8px; }
  .site-version { bottom: max(6px, env(safe-area-inset-bottom)); font-size: 9px; opacity: .75; }
  .hero, .platform-hero, .panel, .warning, .phase-card { padding: 16px; border-radius: 20px; }
  .platform-hero { min-height: 0; margin: 10px 0 18px; }
  .platform-hero p:not(.eyebrow), .hero p:not(.eyebrow) { max-width: 100%; font-size: 16px; }
  .hero-actions, .modal-actions, .account-actions, .choice-row, .wyr-actions, .room-actions, .mode-hero-actions, .room-header-actions, .reaction-actions { display: grid; grid-template-columns: 1fr; width: 100%; gap: 8px; }
  .hero-actions button, .modal-actions button, .choice-row button, .wyr-actions button, .room-actions button, .mode-hero-actions button, .room-header-actions button, .reaction-actions button { width: 100%; }
  .modal-backdrop { align-items: end; padding: 10px; }
  .modal { width: 100%; max-height: calc(100dvh - 22px); overflow: auto; padding: 17px; border-radius: 20px; }
  .modal-title, .section-heading, .room-header, .game-top, .candy-topline { align-items: stretch; flex-direction: column; }
  .row, .platform-join, .lobby-layout, .admin-grid, .identity-side-grid, .identity-guess-form, .answer-form, .answering-layout, .impostor-layout, .wyr-grid, .progression-body { grid-template-columns: 1fr !important; }
  .games-grid, .shop-grid, .player-grid, .answer-board, .vote-grid, .result-player-grid, .identity-history-grid { grid-template-columns: 1fr !important; }
  .game-card, .shop-item { min-height: 0; border-radius: 20px; }
  .platform-join, .platform-join input, .platform-join button, .room-code, .panel, .game-card, .shop-item, .modal, .auth-card { max-width: 100%; min-width: 0; }
  .game-visual { height: 96px; }
  .game-visual span { font-size: 46px; }
  .game-card-content { min-height: 0; padding: 15px; }
  .game-card-footer, .room-card, .room-right { align-items: stretch; flex-direction: column; width: 100%; }
  .room-right button { width: 100%; margin-left: 0; }
  .room-card { padding: 15px; }
  .mode-hero { gap: 12px; }
  .game-symbol { width: 68px; height: 68px; border-radius: 20px; font-size: 32px; }
  .timer-box { width: 100%; min-width: 0; padding: 12px; }
  .timer-box b { font-size: 25px; }
  .impostor-players, .board-player-strip, .candy-players-ring, .score-chips { margin-right: -10px; margin-left: -10px; padding-right: 10px; padding-left: 10px; scroll-padding-left: 10px; -webkit-overflow-scrolling: touch; }
  .impostor-player, .board-player { min-width: 145px; }
  .impostor-chat { max-height: none; }
  .chat-messages { max-height: 260px; }
  .impostor-chat form { display: grid; grid-template-columns: 1fr; }
  .clue, .final-ranking article, .poll-result-row { grid-template-columns: 1fr; text-align: left; }
  .reaction-bubble { right: 8px; max-width: min(210px, calc(100vw - 48px)); white-space: normal; }
  .secret-strip { padding: 13px; }
  .wyr-card { min-height: 170px; padding: 18px; border-radius: 22px; }
  .wyr-card strong { font-size: clamp(20px, 7vw, 28px); }
  .wyr-results { width: 100%; }
  .identity-table, .prove-table, .question-table, .vote-table, .friendship-table, .poison-candy-stage { margin: 12px 0; padding: 12px; border-radius: 22px; }
  .identity-table:after { inset: 7px; border-radius: 18px; }
  .identity-board { grid-template-columns: repeat(2, minmax(0, 1fr)) !important; gap: 8px; }
  .identity-player-card { min-height: 172px; padding: 14px 8px 10px; }
  .own-identity-card .identity-card-word { font-size: 20px; letter-spacing: .08em; }
  .identity-notepad textarea { min-height: 150px; }
  .identity-voice-box, .identity-voice-controls { padding: 13px; }
  .candy-table { width: min(94vw, 430px); max-height: 72dvh; }
  .candy-token { width: 31px; height: 31px; }
  .candy-token>span { width: 25px; height: 16px; }
  .trophy-road, .progression-modal .trophy-road { grid-template-columns: 1fr !important; max-height: none; }
  .progression-modal { max-height: calc(100dvh - 22px); overflow: auto; }
  .progression-side { max-height: none; overflow: visible; }
  .stats-cards { grid-template-columns: 1fr; }
  .cosmetic-carousel { grid-template-columns: 30px minmax(0,1fr) 30px; }
  .cosmetic-rail>* { flex-basis: 132px; }
  .carousel-arrow { width: 30px; min-height: 54px; }
  .owned-cosmetics-panel, .wardrobe-sections, .platform-poll { overflow: hidden; }
  .poll-options button { font-size: 16px; }
}

@media (max-height: 620px) and (max-width: 720px) {
  .modal-backdrop { align-items: start; }
  .modal { max-height: calc(100dvh - 18px); }
  .platform-hero, .hero { padding: 14px; }
  .game-visual { height: 82px; }
  .identity-player-card { min-height: 150px; }
  .identity-avatar { width: 48px; height: 48px; }
  .identity-card-word { font-size: 13px; }
  .candy-table { max-height: 68dvh; }
}

/* Compact room creation: keep the important choices visible without a tall form. */
.room-create-modal {
  width: min(860px, 100%);
  max-height: min(760px, calc(100dvh - 40px));
  overflow-y: auto;
  scrollbar-width: none;
}
.room-create-modal::-webkit-scrollbar { display: none; }
.room-create-modal .modal-title { display: flex; align-items: flex-start; flex-direction: row; margin-bottom: 8px; }
.room-create-subtitle { margin: -3px 0 0; color: var(--muted); font-size: 13px; }
.room-create-layout { display: grid; grid-template-columns: minmax(0, 1.2fr) minmax(250px, .8fr); align-items: start; gap: 16px; }
.room-create-layout.is-single { grid-template-columns: minmax(0, 1fr); }
.room-create-main, .room-create-aside, .room-create-field-grid > div { min-width: 0; }
.room-create-field-grid { display: grid; grid-template-columns: minmax(0, 1fr) minmax(145px, .42fr); gap: 12px; }
.room-create-field-grid label, .room-create-field { margin-top: 10px; }
.room-create-field select { margin-top: 7px; }
.room-create-subtitle + * { min-width: 0; }
.room-preset-choice, .room-type-choice { margin: 14px 0 0; padding: 11px; }
.room-preset-choice, .room-type-choice { border: 1px solid rgba(148,163,184,.2); border-radius: 18px; background: linear-gradient(145deg, rgba(15,23,42,.58), rgba(30,41,59,.28)); }
.room-preset-choice legend, .room-type-choice legend { padding: 0 7px; }
.room-preset-choice legend, .room-type-choice legend { color: #c4b5fd; font-size: 10px; font-weight: 900; letter-spacing: .12em; }
.room-preset-grid, .room-type-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 8px; }
.room-preset-option, .room-type-option { display: grid; grid-template-columns: auto minmax(0, 1fr); align-items: center; min-width: 0; gap: 8px; margin: 0; padding: 10px; border: 1px solid rgba(148,163,184,.16); border-radius: 12px; background: rgba(255,255,255,.035); cursor: pointer; transition: border-color .18s, background .18s, transform .18s; }
.room-preset-option:hover, .room-type-option:hover { transform: translateY(-1px); border-color: rgba(103,232,249,.4); }
.room-preset-option.is-selected, .room-type-option.is-selected { border-color: rgba(97,230,210,.62); background: rgba(97,230,210,.1); box-shadow: 0 7px 18px rgba(6,182,212,.08); }
.room-preset-option input, .room-type-option input { width: 15px; height: 15px; margin: 0; flex: 0 0 auto; accent-color: #67e8f9; }
.room-preset-option > span:last-child, .room-type-option > span { display: grid; min-width: 0; gap: 3px; }
.room-preset-option b, .room-type-option b { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-size: 12px; }
.room-preset-option small, .room-type-option small { overflow: hidden; color: var(--muted); font-size: 10px; line-height: 1.25; text-overflow: ellipsis; white-space: nowrap; }
.room-preset-option small { min-height: 25px; text-overflow: clip; white-space: normal; }
.room-preset-icon { display: grid; width: 24px; height: 24px; place-items: center; grid-column: 1; grid-row: 1; border-radius: 8px; background: rgba(124,58,237,.22); font-size: 14px; }
.room-preset-option { grid-template-columns: 24px minmax(0, 1fr); }
.room-preset-option input { position: absolute; opacity: 0; pointer-events: none; }
.room-preset-help { margin: 8px 0 0; font-size: 11px; }
.room-type-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.room-type-option { align-items: start; }
.room-private-row { display: flex; align-items: center; gap: 9px; margin: 13px 0 0; padding: 9px 10px; border: 1px solid rgba(148,163,184,.14); border-radius: 11px; background: rgba(255,255,255,.025); }
.room-private-row input { width: 18px; height: 18px; margin: 0; flex: 0 0 auto; }
.room-create-modal #room-password { margin-top: 8px; }
.room-type-choice > #entry-fee-field { display: grid; grid-template-columns: 1fr 150px; align-items: center; gap: 10px; margin-top: 10px; }
.room-type-choice > #entry-fee-field.hidden { display: none; }
.room-type-choice > #entry-fee-field select { margin-top: 0; }
.room-create-aside .commerce-setup { margin-top: 10px; }
.commerce-setup { padding: 0; overflow: hidden; }
.commerce-setup-summary { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 14px; cursor: pointer; list-style: none; }
.commerce-setup-summary::-webkit-details-marker { display: none; }
.commerce-setup-summary::marker { display: none; }
.commerce-setup-summary:hover { background: rgba(255,255,255,.035); }
.commerce-setup-title { display: grid; min-width: 0; gap: 2px; }
.commerce-setup-title .eyebrow { margin: 0; font-size: 9px; }
.commerce-setup-title b { font-size: 14px; }
.commerce-setup-title small { color: var(--muted); font-size: 10px; line-height: 1.3; }
.commerce-setup-chevron { color: #67e8f9; font-size: 19px; font-weight: 900; transition: transform .18s; }
.commerce-setup[open] .commerce-setup-chevron { transform: rotate(180deg); }
.commerce-setup-content { display: grid; gap: 10px; padding: 0 14px 14px; }
.commerce-setup-content > .tiny { margin: 0; font-size: 11px; }
.commerce-setup-content .commerce-toggle { margin: 0; }
.commerce-setup-content .commerce-available-list { max-height: 68px; overflow: hidden; }
.room-create-modal .modal-actions { margin-top: 16px; }
.room-create-modal .modal-actions .primary { min-width: 145px; }
.light-theme .room-preset-option, .light-theme .room-type-option, .light-theme .room-private-row { background: #f8fafc; border-color: rgba(100,116,139,.24); }
.light-theme .room-preset-choice, .light-theme .room-type-choice { background: linear-gradient(145deg, #ffffff, #f1f5f9); border-color: rgba(100,116,139,.24); }
.light-theme .room-preset-option.is-selected, .light-theme .room-type-option.is-selected { background: #ecfeff; border-color: rgba(14,116,144,.5); }
.light-theme .commerce-setup-summary:hover { background: rgba(100,116,139,.08); }

@media (min-width: 721px) {
  .room-create-modal { position: relative; top: clamp(12px, 3vh, 28px); }
}

@media (max-width: 720px) {
  .room-create-modal { max-height: calc(100dvh - 20px); padding: 17px; }
  .room-create-layout { grid-template-columns: 1fr; gap: 12px; }
  .room-create-aside .commerce-setup { margin-top: 0; }
}
@media (max-width: 480px) {
  .room-create-field-grid, .room-type-grid { grid-template-columns: 1fr; gap: 0; }
  .room-preset-grid { grid-template-columns: 1fr; }
  .room-preset-option { min-height: 48px; }
  .room-type-choice > #entry-fee-field { grid-template-columns: 1fr; gap: 5px; }
  .room-type-choice > #entry-fee-field select { margin-top: 0; }
  .room-create-subtitle { font-size: 12px; }
}

