/* Phase transitions: applied once when the game changes phase/round, not on every sync repaint. */
.route-game.game-phase-transition .page > .panel,
.route-game.game-phase-transition .page > section,
.route-game.game-phase-transition .page > article,
.route-game.game-phase-transition .game-panel,
.route-game.game-phase-transition .phase-card,
.route-game.game-phase-transition .result-card,
.route-game.game-phase-transition .summary-card,
.route-game.game-phase-transition .game-summary,
.route-game.game-phase-transition .results-panel {
  animation: gamePhaseEnter .58s cubic-bezier(.2,.8,.2,1) both;
}
.route-game.game-phase-transition > main > *,
.route-game.game-phase-transition [class*="summary"],
.route-game.game-phase-transition [class*="results"] {
  animation: gamePhaseEnter .58s cubic-bezier(.2,.8,.2,1) both;
}
.route-game.game-phase-transition .page > *:nth-child(2),
.route-game.game-phase-transition .page > section:nth-child(2),
.route-game.game-phase-transition .page > article:nth-child(2) { animation-delay: .07s; }
.route-game.game-phase-transition .page > *:nth-child(3),
.route-game.game-phase-transition .page > section:nth-child(3),
.route-game.game-phase-transition .page > article:nth-child(3) { animation-delay: .14s; }
.route-game.game-phase-transition .ranking > *,
.route-game.game-phase-transition .ranking-list > *,
.route-game.game-phase-transition .result-list > *,
.route-game.game-phase-transition .final-ranking > * {
  animation: resultRowEnter .42s cubic-bezier(.2,.8,.2,1) both;
}
.route-game.game-phase-transition .ranking > *:nth-child(2),
.route-game.game-phase-transition .ranking-list > *:nth-child(2),
.route-game.game-phase-transition .result-list > *:nth-child(2),
.route-game.game-phase-transition .final-ranking > *:nth-child(2) { animation-delay: .08s; }
.route-game.game-phase-transition .ranking > *:nth-child(3),
.route-game.game-phase-transition .ranking-list > *:nth-child(3),
.route-game.game-phase-transition .result-list > *:nth-child(3),
.route-game.game-phase-transition .final-ranking > *:nth-child(3) { animation-delay: .16s; }
@keyframes gamePhaseEnter { from { opacity: 0; transform: translateY(16px) scale(.985); filter: blur(2px); } to { opacity: 1; transform: none; filter: none; } }
@keyframes resultRowEnter { from { opacity: 0; transform: translateX(-10px); } to { opacity: 1; transform: none; } }
@media (prefers-reduced-motion: reduce) {
  .route-game.game-phase-transition .page > *,
  .route-game.game-phase-transition .ranking > *,
  .route-game.game-phase-transition .ranking-list > *,
  .route-game.game-phase-transition .result-list > *,
  .route-game.game-phase-transition .final-ranking > * { animation: none !important; }
}

