/* Smooth shell motion: only a fresh route animates. Soft synchronisation renders stay still. */
.route-view.initial-route > .page,
.route-view.initial-route > main,
.route-view.initial-route > section { animation: routeSoftReveal .18s ease-out both; }
.route-view.soft-route > .page,
.route-view.soft-route > main,
.route-view.soft-route > section { animation: none !important; }
.topbar .brand,
.topbar .top-actions > *,
.topbar .account-button { transition: transform .2s cubic-bezier(.16,1,.3,1), border-color .2s ease, background-color .2s ease, box-shadow .2s ease; }
.topbar .brand:hover,
.topbar .top-actions > button:hover,
.topbar .account-button:hover { transform: translateY(-1px); }
.topbar .top-actions > button:active,
.topbar .account-button:active { transform: translateY(1px) scale(.98); }
.route-shop.initial-route .shop-page > .room-header { animation: shopHeaderDrop .5s cubic-bezier(.16,1,.3,1) both; }
.route-shop.initial-route .shop-page > .shop-grid { animation: shopCardDeal .55s .08s cubic-bezier(.16,1,.3,1) both; }
.route-shop.initial-route .shop-page > .owned-cosmetics-panel { animation: wardrobeSlideUp .48s .16s cubic-bezier(.16,1,.3,1) both; }
.route-shop .shop-item { backface-visibility: hidden; contain: layout paint; }
.route-shop .wardrobe-category,
.route-shop .cosmetic-catalog .wardrobe-category { content-visibility: auto; contain-intrinsic-size: 180px; }
.route-shop .shop-page { will-change: transform, opacity; }
.equipment-modal.enter { animation: wardrobeOpen .46s cubic-bezier(.16,1,.3,1) both; }
.shop-page .shop-item:hover { transform: translateY(-5px) scale(1.008); }
@keyframes wardrobeOpen {
  0% { opacity: 0; transform: translateY(-26px) rotateX(-4deg) scale(.96); filter: blur(5px); }
  62% { opacity: 1; transform: translateY(3px) rotateX(1deg) scale(1.005); filter: blur(0); }
  100% { opacity: 1; transform: none; }
}
@media (prefers-reduced-motion: reduce) {
  .route-view.initial-route > .page,
  .route-view.initial-route > main,
  .route-view.initial-route > section,
  .route-shop.initial-route .shop-page > .room-header,
  .route-shop.initial-route .shop-page > .shop-grid,
  .route-shop.initial-route .shop-page > .owned-cosmetics-panel,
  .equipment-modal.enter { animation: none !important; }
  .topbar .brand,
  .topbar .top-actions > *,
  .topbar .account-button { transition: none !important; }
}
