@keyframes boardFloat{0%,100%{transform:translateY(0) rotate(0)}50%{transform:translateY(-7px) rotate(2deg)}}@keyframes boardPop{from{opacity:.2;transform:scale(.7)}70%{transform:scale(1.08)}to{opacity:1;transform:scale(1)}}@keyframes boardCellIn{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}@keyframes boardTimerPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.07)}}@keyframes boardWin{from{opacity:0;transform:scale(.55) rotate(-10deg)}65%{transform:scale(1.1) rotate(4deg)}to{opacity:1;transform:scale(1) rotate(0)}}
