.board-rules{position:relative;z-index:2;margin:0 0 16px;border:1px solid rgba(167,139,250,.2);border-radius:16px;background:rgba(124,58,237,.07);overflow:hidden}.board-rules summary{padding:11px 14px;cursor:pointer;color:#ddd6fe;font-size:13px;font-weight:900;list-style:none}.board-rules summary::-webkit-details-marker{display:none}.board-rules summary:after{float:right;color:#67e8f9;content:"＋";font-size:17px;line-height:13px}.board-rules[open] summary{border-bottom:1px solid rgba(167,139,250,.16)}.board-rules[open] summary:after{content:"−"}.board-rules>div{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;padding:11px 14px}.board-rules p{display:flex;margin:0;align-items:flex-start;gap:8px;color:#cbd5e1;font-size:12px;line-height:1.4}.board-rules p b{display:grid;width:20px;height:20px;flex:none;place-items:center;border-radius:50%;background:rgba(103,232,249,.13);color:#a5f3fc;font-size:10px}.ludo-token-button{padding:0;cursor:pointer;appearance:none}.ludo-token-button:hover{z-index:2;transform:scale(1.12)!important;filter:brightness(1.16)}.board-action-button.is-pending{cursor:wait;opacity:.62;filter:saturate(.55)}.word-rack span{cursor:help}.domino-hand article:has(.board-action-button:not([disabled])){border-color:rgba(103,232,249,.18);background:rgba(6,182,212,.06)}
