/* Cosmetic FX polish: every animation uses the same stage and only the result
   matching its outcome is revealed. This keeps win and lose effects from
   colliding in rankings while preserving the existing cosmetic classes. */
.mini-player{isolation:isolate}
.mini-player>.cosmetic-fx-group{position:absolute;inset:0;z-index:0;display:none;opacity:0;overflow:visible;pointer-events:none}
.cosmetic-animation-preview>.cosmetic-fx-group{display:block;opacity:1}
.final-ranking article:first-child .mini-player>.cosmetic-fx-group.cosmetic-fx-win,
.result-player-grid .winner-card .mini-player>.cosmetic-fx-group.cosmetic-fx-win,
.final-ranking article:not(:first-child) .mini-player>.cosmetic-fx-group.cosmetic-fx-lose,
.result-player-grid article:not(.winner-card) .mini-player>.cosmetic-fx-group.cosmetic-fx-lose{display:block;opacity:1}
.catalog-animations-off .cosmetic-animation-preview>.cosmetic-fx-group{display:none!important;opacity:0!important}

/* Kometa triumfu: the meteor lands below the avatar instead of disappearing
   behind it, with a brighter trail, landing glow and a readable final pose. */
.winMeteor>.cosmetic-fx-group.cosmetic-fx-win{z-index:0}
.winMeteor>.avatar{position:relative;z-index:8}
.winMeteor>.nick{position:relative;z-index:10}
.winMeteor .fx-win-dodge-meteor{z-index:3;width:76px;height:46px;top:-45%;border-radius:50% 46% 42% 56%;background:radial-gradient(circle at 31% 25%,#fff7ed 0 9%,#fed7aa 11% 22%,#fb923c 34%,#c2410c 56%,#431407 78%);box-shadow:inset:-9px -7px 0 rgba(67,20,7,.34),inset 8px 6px 0 rgba(255,247,237,.18),0 0 18px #fb923c,0 10px 20px rgba(124,45,18,.42);animation:cosmeticMeteorLand 3.2s cubic-bezier(.18,.82,.22,1) infinite!important}
.winMeteor .fx-win-dodge-meteor:before{position:absolute;right:53px;top:13px;width:68px;height:16px;border-radius:999px;background:linear-gradient(90deg,transparent,rgba(251,146,60,.18) 30%,rgba(254,215,170,.7));filter:blur(3px);transform:rotate(-14deg);content:""}
