/* Dokończ tekst: krótki odsłuch, animowane odkrywanie i czytelne ujawnienie wyniku. */
.lyrics-page{width:min(calc(100% - 2rem),1120px);margin-inline:auto;padding-bottom:28px}
.lyrics-panel{width:min(100%,1080px);margin-inline:auto;padding:clamp(18px,3vw,32px);overflow:hidden;background:radial-gradient(circle at 8% 0,rgba(124,58,237,.15),transparent 32%),radial-gradient(circle at 92% 20%,rgba(6,182,212,.12),transparent 28%),var(--panel,#0f172a)}
.lyrics-panel>h1{margin:4px 0 18px;font-size:clamp(30px,5vw,54px);line-height:1.05}
.lyrics-category-banner{display:flex;align-items:center;gap:13px;margin:0 auto 20px;padding:13px 15px;border:1px solid rgba(103,232,249,.28);border-radius:18px;background:linear-gradient(135deg,rgba(8,145,178,.13),rgba(124,58,237,.14));text-align:left}
.lyrics-category-banner>span{display:grid;width:46px;height:46px;flex:none;place-items:center;border-radius:14px;background:linear-gradient(135deg,#7c3aed,#06b6d4);font-size:24px;box-shadow:0 8px 20px rgba(6,182,212,.18)}
.lyrics-category-banner>div{display:grid;gap:3px;min-width:0}.lyrics-category-banner small{color:#a78bfa;font-size:9px;font-weight:900;letter-spacing:.12em}.lyrics-category-banner strong{color:#67e8f9;font-size:20px;overflow-wrap:anywhere}
.lyrics-challenge{max-width:850px;margin:0 auto;padding:clamp(16px,2.5vw,25px);border:1px solid rgba(148,163,184,.22);border-radius:24px;background:linear-gradient(145deg,rgba(15,23,42,.92),rgba(30,27,75,.58));text-align:left;box-shadow:0 18px 46px rgba(2,6,23,.18)}
.lyrics-track{display:flex;align-items:center;gap:13px;min-width:0;padding-bottom:17px;border-bottom:1px solid rgba(148,163,184,.16)}
.lyrics-track-cover{display:grid;width:66px;height:66px;flex:none;place-items:center;overflow:hidden;border:1px solid rgba(103,232,249,.25);border-radius:16px;background:linear-gradient(135deg,#312e81,#0891b2);box-shadow:0 10px 24px rgba(6,182,212,.16)}
.lyrics-track-cover img{width:100%;height:100%;object-fit:cover}.lyrics-track-cover .music-cover-placeholder{width:100%;height:100%;border-radius:0}.lyrics-track>div:last-child{display:grid;gap:3px;min-width:0}.lyrics-track .eyebrow{margin:0;color:#67e8f9;font-size:9px}.lyrics-track h3,.lyrics-track p:last-child{margin:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lyrics-track h3{font-size:18px}.lyrics-track p:last-child{color:var(--muted);font-size:12px}
.lyrics-progress{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:18px 0 10px;color:#cbd5e1;font-size:12px}.lyrics-progress b{color:#67e8f9;font-size:20px;font-variant-numeric:tabular-nums}
.lyrics-text-stage{display:flex;align-items:center;min-height:112px;margin:10px 0 18px;padding:19px 17px;border:1px solid rgba(167,139,250,.22);border-radius:18px;background:radial-gradient(circle at 50% 0,rgba(124,58,237,.14),transparent 58%),rgba(2,6,23,.4);color:#f8fafc;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:clamp(19px,3vw,31px);font-weight:850;line-height:1.45;letter-spacing:.025em;word-break:break-word}
.lyrics-line{display:block;width:100%}.lyrics-letter{display:inline-block;min-width:.5em;text-align:center}.lyrics-letter-space{min-width:.38em}.lyrics-letter-hidden{color:rgba(167,139,250,.8);filter:drop-shadow(0 0 5px rgba(124,58,237,.45));animation:lyricsPulse 1.3s ease-in-out infinite}.lyrics-letter-visible{color:#67e8f9;animation:lyricsLetterIn .22s cubic-bezier(.16,1,.3,1) both}
.lyrics-audio-box{display:grid;grid-template-columns:auto minmax(0,1fr);align-items:center;gap:8px;padding:10px 12px;border:1px solid rgba(103,232,249,.18);border-radius:14px;background:rgba(6,182,212,.06)}
.lyrics-audio-box audio{position:absolute;width:1px;height:1px;opacity:0;pointer-events:none}.lyrics-audio-box button{min-height:36px;padding:8px 12px;white-space:nowrap}.lyrics-audio-box button:disabled{cursor:not-allowed;opacity:.62}.lyrics-audio-box span{color:var(--muted);font-size:11px;line-height:1.35}.lyrics-hint{margin:11px 0 0;color:#a5b4fc;font-size:11px;line-height:1.4}
.lyrics-sync-warning{display:block;margin-top:5px;color:#fbbf24;font-size:10px;line-height:1.35}
.light-theme .lyrics-sync-warning{color:#92400e}
.lyrics-answer-form{display:grid;gap:8px}.lyrics-answer-form label{color:#c4b5fd;font-size:13px;font-weight:900}.lyrics-answer-form>div{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:8px}.lyrics-answer-form input{min-width:0;border-color:rgba(103,232,249,.45);font-size:15px}.lyrics-answer-form button{min-width:110px}.lyrics-answer-form>small{color:var(--muted);font-size:11px}.lyrics-answer-saved{display:flex;align-items:center;gap:10px;padding:13px;border:1px solid rgba(52,211,153,.32);border-radius:14px;background:rgba(16,185,129,.08)}.lyrics-answer-saved>span{display:grid;width:32px;height:32px;place-items:center;border-radius:50%;background:#059669;color:#fff;font-size:18px;font-weight:1000}.lyrics-answer-saved>div{display:grid;gap:2px}.lyrics-answer-saved small{color:var(--muted);font-size:11px}
.lyrics-full-text{margin:12px 0;padding:16px;border:1px solid rgba(52,211,153,.28);border-radius:15px;background:rgba(16,185,129,.08);color:#a7f3d0;font-family:ui-monospace,SFMono-Regular,Consolas,monospace;font-size:clamp(17px,2.8vw,26px);font-weight:850;line-height:1.45;white-space:pre-line;animation:lyricsReveal .5s cubic-bezier(.16,1,.3,1) both}.lyrics-answer-note,.lyrics-score-note{color:var(--muted);font-size:11px;line-height:1.4}.lyrics-answer-note b{color:#fef08a}.lyrics-result-list,.lyrics-ranking-list{display:grid;gap:7px;margin:16px 0}.lyrics-result-row,.lyrics-ranking-row{display:grid;grid-template-columns:minmax(0,1fr) auto auto;align-items:center;gap:12px;padding:11px 13px;border:1px solid var(--line);border-radius:13px;background:rgba(255,255,255,.035)}.lyrics-result-row>span{display:grid;gap:3px;min-width:0}.lyrics-result-row b,.lyrics-result-row small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.lyrics-result-row small{color:var(--muted);font-size:10px}.lyrics-result-row strong,.lyrics-ranking-row b{color:#67e8f9;white-space:nowrap}.lyrics-result-row em{color:#a78bfa;font-size:11px;font-style:normal;font-weight:900}.lyrics-winner{margin:14px 0;color:#fbbf24;font-size:16px;font-weight:900}.lyrics-challenge.result .big,.lyrics-final .big{display:block;margin:16px auto 0}.lyrics-final{max-width:680px;margin:0 auto;padding:clamp(20px,4vw,42px);border:1px solid rgba(167,139,250,.3);border-radius:25px;background:linear-gradient(145deg,rgba(49,46,129,.4),rgba(8,47,73,.38));text-align:center}.lyrics-final>span{display:block;font-size:55px;filter:drop-shadow(0 0 18px rgba(103,232,249,.4));animation:lyricsTrophyIn .55s cubic-bezier(.16,1,.3,1) both}.lyrics-final h2{margin:5px 0 7px;font-size:clamp(24px,4vw,36px)}.lyrics-final>p:not(.eyebrow){color:var(--muted)}.lyrics-ranking-list{text-align:left}.lyrics-settings-note{display:grid;gap:3px;margin-top:5px;padding:11px 12px;border:1px solid rgba(103,232,249,.18);border-radius:12px;background:rgba(6,182,212,.05)}.lyrics-settings-note b{color:#67e8f9;font-size:12px}.lyrics-settings-note small{color:var(--muted);font-size:10px;line-height:1.4}
.light-theme .lyrics-panel{background:radial-gradient(circle at 8% 0,rgba(124,58,237,.08),transparent 32%),#f8fafc}.light-theme .lyrics-challenge,.light-theme .lyrics-final{background:linear-gradient(145deg,#f8fafc,#eef2ff)}.light-theme .lyrics-text-stage{background:linear-gradient(135deg,#eef2ff,#ecfeff);color:#172554}.light-theme .lyrics-letter-hidden{color:#7c3aed}.light-theme .lyrics-full-text{color:#047857}.light-theme .lyrics-audio-box{background:#ecfeff}.light-theme .lyrics-result-row,.light-theme .lyrics-ranking-row{background:#fff;border-color:rgba(100,116,139,.22)}
@keyframes lyricsLetterIn{from{opacity:0;transform:translateY(7px) scale(.82)}to{opacity:1;transform:none}}@keyframes lyricsPulse{0%,100%{opacity:.55}50%{opacity:1}}@keyframes lyricsReveal{from{opacity:0;transform:translateY(10px) scale(.98);filter:blur(5px)}to{opacity:1;transform:none;filter:none}}@keyframes lyricsTrophyIn{from{opacity:0;transform:translateY(-12px) scale(.65) rotate(-8deg)}to{opacity:1;transform:none}}
@media(max-width:620px){.lyrics-page{width:100%;padding-inline:10px}.lyrics-panel{padding:16px 12px;border-radius:20px}.lyrics-panel>h1{font-size:clamp(28px,9vw,40px)}.lyrics-category-banner{align-items:flex-start}.lyrics-track-cover{width:54px;height:54px}.lyrics-track h3{font-size:15px}.lyrics-text-stage{min-height:100px;padding:14px 10px;font-size:clamp(17px,5.2vw,24px)}.lyrics-audio-box{grid-template-columns:1fr}.lyrics-audio-box button{width:100%}.lyrics-answer-form>div{grid-template-columns:1fr}.lyrics-answer-form button{width:100%}.lyrics-result-row{grid-template-columns:minmax(0,1fr) auto}.lyrics-result-row em{grid-column:2;grid-row:1}.lyrics-result-row strong{grid-column:2;grid-row:2}.lyrics-result-row>span{grid-column:1;grid-row:1 / span 2}.lyrics-ranking-row{padding-inline:10px}}
@media(prefers-reduced-motion:reduce){.lyrics-letter-hidden,.lyrics-letter-visible,.lyrics-full-text,.lyrics-final>span{animation:none}}

/* Dokończ tekst solo: ten sam rytm ekranu co Kto ma więcej?, z osobnym rekordem. */
.lyrics-page.lyrics-solo-page{width:min(calc(100% - 2rem),1800px);max-width:1800px}
.lyrics-solo-layout{position:relative;display:block;max-width:1800px;margin-inline:auto}
.lyrics-solo-main{width:min(100%,1120px);margin-inline:auto!important}
.lyrics-solo-layout>.lyrics-solo-leaderboard{position:absolute;top:0;left:calc(50% + 600px);width:280px;max-width:280px}
.lyrics-solo-title-row{display:flex;align-items:flex-start;justify-content:space-between;gap:18px;margin-bottom:24px}.lyrics-solo-title-row h1{margin:4px 0 8px;font-size:clamp(34px,5vw,58px);line-height:1}.lyrics-solo-title-row p{max-width:680px;margin:0;font-size:16px}.lyrics-solo-streak{display:grid;min-width:112px;padding:12px 18px;border:1px solid rgba(167,139,250,.44);border-radius:18px;background:linear-gradient(135deg,rgba(124,58,237,.2),rgba(6,182,212,.12));text-align:center;box-shadow:0 0 22px rgba(103,232,249,.08)}.lyrics-solo-streak small{color:#c4b5fd;font-size:10px;font-weight:1000;letter-spacing:.12em}.lyrics-solo-streak b{color:#67e8f9;font-size:27px;line-height:1.1}.lyrics-solo-start{max-width:850px;margin:10px auto 0;padding:clamp(24px,4vw,44px);border:1px solid rgba(103,232,249,.3);border-radius:26px;background:radial-gradient(circle at 85% 5%,rgba(124,58,237,.22),transparent 35%),linear-gradient(145deg,rgba(8,47,73,.5),rgba(30,27,75,.5));text-align:center;box-shadow:0 20px 55px rgba(2,6,23,.18)}.lyrics-solo-icon{display:grid;width:68px;height:68px;margin:0 auto 15px;place-items:center;border-radius:21px;background:linear-gradient(135deg,#7c3aed,#06b6d4);font-size:31px;box-shadow:0 0 30px rgba(34,211,238,.2);animation:lyricsSoloIconIn .55s cubic-bezier(.16,1,.3,1) both}.lyrics-solo-start h2{margin:4px 0 8px;font-size:clamp(24px,4vw,36px)}.lyrics-solo-start>p:not(.eyebrow){max-width:680px;margin:0 auto;color:var(--muted);line-height:1.5}.lyrics-solo-best{display:flex;align-items:center;justify-content:center;gap:11px;max-width:500px;margin:24px auto;padding:12px 16px;border:1px solid rgba(250,204,21,.3);border-radius:15px;background:rgba(120,53,15,.14);text-align:left}.lyrics-solo-best>span{font-size:25px}.lyrics-solo-best div{display:grid;gap:2px}.lyrics-solo-best small{color:#fbbf24;font-size:9px;font-weight:1000;letter-spacing:.12em}.lyrics-solo-best b{font-size:16px}.lyrics-solo-start .big{margin-top:2px}.lyrics-solo-challenge{max-width:900px}.lyrics-karaoke-line{display:block;width:100%;min-height:1.45em}.lyrics-karaoke-current{color:#fff;text-shadow:0 0 12px rgba(103,232,249,.65);animation:lyricsKaraokePulse .7s ease-in-out infinite alternate}.lyrics-karaoke-cut{display:inline-block;margin-left:10px;color:#fbbf24;font-family:inherit;font-size:.42em;font-weight:900;letter-spacing:.02em;vertical-align:middle;white-space:nowrap;animation:lyricsCutIn .35s ease both}.lyrics-karaoke-missing{display:inline-block;margin-left:9px;color:#a78bfa;font-family:inherit;font-size:.72em;letter-spacing:.04em;white-space:nowrap;animation:lyricsPulse 1.3s ease-in-out infinite}.lyrics-continuation-note{margin:0 0 14px;padding:10px 12px;border:1px solid rgba(250,204,21,.22);border-radius:12px;background:rgba(120,53,15,.1);color:var(--muted);font-size:11px;line-height:1.4}.lyrics-continuation-note b{color:#fde68a}.lyrics-solo-result{max-width:900px;margin:10px auto 0;padding:clamp(20px,3vw,34px);border:1px solid rgba(52,211,153,.42);border-radius:25px;background:radial-gradient(circle at 50% 0,rgba(16,185,129,.14),transparent 32%),linear-gradient(145deg,rgba(8,47,73,.56),rgba(15,23,42,.76));text-align:center;animation:lyricsReveal .45s cubic-bezier(.16,1,.3,1) both}.lyrics-solo-result.is-wrong{border-color:rgba(244,63,94,.4);background:radial-gradient(circle at 50% 0,rgba(190,24,93,.15),transparent 32%),linear-gradient(145deg,rgba(49,46,129,.44),rgba(15,23,42,.8))}.lyrics-solo-result-icon{display:grid;width:58px;height:58px;margin:0 auto 10px;place-items:center;border-radius:50%;background:linear-gradient(135deg,#059669,#06b6d4);color:#fff;font-size:30px;font-weight:1000;box-shadow:0 0 26px rgba(52,211,153,.22);animation:lyricsSoloIconIn .45s cubic-bezier(.16,1,.3,1) both}.lyrics-solo-result.is-wrong .lyrics-solo-result-icon{background:linear-gradient(135deg,#be123c,#7c3aed);box-shadow:0 0 26px rgba(244,63,94,.2)}.lyrics-solo-result h2{margin:3px 0 8px;font-size:clamp(26px,4vw,38px)}.lyrics-solo-result>p:not(.eyebrow){margin:0;color:var(--muted)}.lyrics-solo-result>p b{color:#67e8f9}.lyrics-solo-reveal-track{max-width:720px;margin:18px auto 0;text-align:left}.lyrics-solo-reveal-track .lyrics-track{border:1px solid rgba(103,232,249,.18);border-radius:15px;padding:10px 12px;background:rgba(2,6,23,.25)}.lyrics-solo-result .lyrics-full-text{max-width:720px;margin:10px auto}.lyrics-solo-result .lyrics-answer-note{max-width:720px;margin-inline:auto;text-align:left}.lyrics-solo-result-actions{display:flex;align-items:center;justify-content:center;gap:10px;margin-top:16px}.lyrics-solo-result-actions .big{margin:0}.light-theme .lyrics-solo-start,.light-theme .lyrics-solo-result{background:linear-gradient(145deg,#ecfeff,#eef2ff)}.light-theme .lyrics-karaoke-current{color:#0f172a;text-shadow:0 0 10px rgba(14,116,144,.3)}.light-theme .lyrics-karaoke-cut{color:#b45309}.light-theme .lyrics-karaoke-missing{color:#6d28d9}.light-theme .lyrics-continuation-note{background:#fff7ed;border-color:rgba(180,83,9,.2)}.light-theme .lyrics-continuation-note b{color:#92400e}
@keyframes lyricsSoloIconIn{from{opacity:0;transform:translateY(9px) scale(.7) rotate(-8deg)}to{opacity:1;transform:none}}@keyframes lyricsKaraokePulse{from{opacity:.72;transform:translateY(1px)}to{opacity:1;transform:translateY(-1px)}}@keyframes lyricsCutIn{from{opacity:0;transform:translateX(-5px)}to{opacity:1;transform:none}}
@media(max-width:1779px) and (min-width:1001px){.lyrics-solo-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(240px,280px);gap:16px;max-width:1400px}.lyrics-solo-main{width:100%;max-width:none!important;margin:0!important}.lyrics-solo-layout>.lyrics-solo-leaderboard{position:sticky;top:16px;left:auto;width:100%;max-width:none}}
@media(max-width:1000px){.lyrics-solo-layout{display:grid;grid-template-columns:1fr;gap:12px;max-width:1120px}.lyrics-solo-main{width:100%;max-width:none!important;margin:0!important}.lyrics-solo-layout>.lyrics-solo-leaderboard{position:static;order:2;width:100%;max-width:none}.lyrics-solo-leaderboard .popularity-leaderboard-list{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:620px){.lyrics-solo-page{width:100%!important;padding-inline:10px}.lyrics-solo-title-row{gap:10px}.lyrics-solo-title-row h1{font-size:clamp(30px,9vw,43px)}.lyrics-solo-title-row p{font-size:13px}.lyrics-solo-streak{min-width:77px;padding:9px 10px}.lyrics-solo-streak b{font-size:22px}.lyrics-solo-start{padding:22px 14px;border-radius:21px}.lyrics-solo-result-actions{align-items:stretch;flex-direction:column}.lyrics-solo-result-actions .big{width:100%}.lyrics-karaoke-cut{display:block;margin:7px 0 0;font-size:10px}.lyrics-karaoke-missing{font-size:.66em}.lyrics-solo-leaderboard .popularity-leaderboard-list{grid-template-columns:1fr}}
@media(max-width:620px){.lyrics-karaoke-blank-lines{gap:4px}.lyrics-karaoke-blank-lines .lyrics-karaoke-blank{width:clamp(1.45rem,6vw,2.2rem)}}
@media(prefers-reduced-motion:reduce){.lyrics-solo-icon,.lyrics-solo-result,.lyrics-solo-result-icon,.lyrics-karaoke-current,.lyrics-karaoke-cut,.lyrics-karaoke-missing{animation:none}}

/* Karaoke: po zatrzymaniu zostaje ostatnia widoczna linia i osobne puste miejsce na kontynuację. */
.lyrics-karaoke-lines{display:grid;width:100%;gap:8px;min-height:2.9em;align-content:center}
.lyrics-karaoke-lines.is-paused{gap:4px}
.lyrics-karaoke-previous,.lyrics-karaoke-blank{display:block;width:100%;min-height:1.45em}
.lyrics-karaoke-previous{color:#f8fafc;animation:lyricsReveal .28s cubic-bezier(.16,1,.3,1) both}
.lyrics-karaoke-blank{border-bottom:1px dashed rgba(167,139,250,.48);opacity:.42}
.light-theme .lyrics-karaoke-previous{color:#172554}
.light-theme .lyrics-karaoke-blank{border-color:rgba(109,40,217,.42)}

/* Karaoke pokazuje słowa w rytmie audio, a brakujące słowa jako neutralne blanki. */
.lyrics-karaoke-lines{display:block;min-height:2.9em;align-content:center}
.lyrics-karaoke-line{display:block;width:100%;line-height:1.9;word-spacing:.08em}
.lyrics-karaoke-word{display:inline-block;vertical-align:middle;transition:color .18s ease,opacity .18s ease,transform .18s ease}
.lyrics-word-visible{color:#f8fafc;animation:lyricsKaraokeWordIn .3s cubic-bezier(.16,1,.3,1) both}
.lyrics-word-blank{width:clamp(30px,7vw,76px);height:.62em;margin:0 .18em;border-radius:999px;background:linear-gradient(90deg,rgba(148,163,184,.58),rgba(226,232,240,.76),rgba(148,163,184,.58));box-shadow:0 0 12px rgba(148,163,184,.12);opacity:.58}
.lyrics-karaoke-lines.is-paused .lyrics-word-visible{color:#f8fafc;animation:none}
.lyrics-karaoke-lines.is-paused .lyrics-word-blank{opacity:.52}
.light-theme .lyrics-word-visible{color:#172554}
.light-theme .lyrics-word-blank{background:linear-gradient(90deg,rgba(100,116,139,.38),rgba(71,85,105,.58),rgba(100,116,139,.38))}
@keyframes lyricsKaraokeWordIn{from{opacity:.1;transform:translateY(3px)}to{opacity:1;transform:none}}

/* Po zatrzymaniu pokazujemy pełny ostatni zaśpiewany wers. Kontynuacja ma
   osobne, jednakowe blanki — jeden blank oznacza jedno słowo i nie zdradza
   jego długości literowej. */
.lyrics-karaoke-lines{display:grid;gap:10px;min-height:4.2em;align-content:center}
.lyrics-karaoke-context{display:grid;gap:3px;width:100%}
.lyrics-karaoke-context-line{display:block;width:100%;color:rgba(226,232,240,.56);font-family:inherit;font-size:.72em;font-weight:700;line-height:1.35;white-space:normal}
.lyrics-karaoke-previous{display:block;width:100%;min-height:1.45em;color:#f8fafc;line-height:1.55}
.lyrics-karaoke-previous .lyrics-karaoke-word{display:inline-block;vertical-align:middle}
.lyrics-karaoke-blank-lines{display:flex;flex-wrap:wrap;align-items:center;gap:8px;width:100%;min-height:1.45em}
.lyrics-karaoke-blank-lines .lyrics-karaoke-blank{display:inline-block;flex:0 0 auto;width:clamp(2rem,3vw,3.5rem);min-width:0;height:.72em;min-height:0;margin:0;border-radius:999px;background:linear-gradient(90deg,rgba(148,163,184,.46),rgba(226,232,240,.7),rgba(148,163,184,.46));box-shadow:0 0 12px rgba(148,163,184,.1);opacity:.52}
.light-theme .lyrics-karaoke-previous{color:#172554}
.light-theme .lyrics-karaoke-context-line{color:rgba(30,41,59,.58)}
.light-theme .lyrics-karaoke-lines.is-paused .lyrics-word-visible{color:#172554}
.light-theme .lyrics-karaoke-blank-lines .lyrics-karaoke-blank{background:linear-gradient(90deg,rgba(100,116,139,.3),rgba(71,85,105,.52),rgba(100,116,139,.3))}

/* Solo z rankingiem: zachowaj centralny panel, ale zostaw więcej oddechu przy prawej krawędzi. */
@media(min-width:1780px){
  .popularity-page.popularity-solo-page{width:min(calc(100% - 2rem),1700px);max-width:1700px}
  .popularity-solo-main{width:min(100%,1040px)}
  .popularity-solo-layout>.popularity-leaderboard{left:calc(50% + 550px);width:250px;max-width:250px}
}
