/* Songspot: stable cards, clear stage progression and compact mobile layout. */
html:has(.songspot-page),html:has(.songspot-group-page),body:has(.songspot-page),body:has(.songspot-group-page){scrollbar-width:none}
html:has(.songspot-page)::-webkit-scrollbar,html:has(.songspot-group-page)::-webkit-scrollbar,body:has(.songspot-page)::-webkit-scrollbar,body:has(.songspot-group-page)::-webkit-scrollbar{width:0;height:0}
.songspot-page,.songspot-group-page{isolation:isolate}
.songspot-panel,.songspot-group-panel{position:relative;overflow:hidden;box-shadow:0 24px 70px rgba(2,6,23,.28),inset 0 1px 0 rgba(255,255,255,.035)}
.songspot-panel:before,.songspot-group-panel:before{position:absolute;inset:0;z-index:0;background-image:linear-gradient(115deg,rgba(103,232,249,.055),transparent 34%,rgba(167,139,250,.055)),repeating-linear-gradient(135deg,transparent 0 25px,rgba(255,255,255,.018) 26px 27px);content:"";pointer-events:none;opacity:.72}
.songspot-panel>*,.songspot-group-panel>*{position:relative;z-index:1}
.songspot-start,.songspot-round,.songspot-result,.songspot-group-round,.songspot-group-result,.songspot-group-summary{width:100%;box-sizing:border-box;animation:songspotStageIn .36s cubic-bezier(.16,1,.3,1) both}
.songspot-title-row h1,.songspot-game-title-row h1{max-width:100%;text-wrap:balance}
.songspot-title-row .lyrics-solo-streak{flex:none;animation:songspotBadgeIn .42s cubic-bezier(.16,1,.3,1) .08s both}
.songspot-stage-list{position:relative;gap:9px;margin-top:22px;padding:13px 14px;background:linear-gradient(135deg,rgba(6,182,212,.12),rgba(124,58,237,.12));box-shadow:inset 0 0 0 1px rgba(255,255,255,.025)}
.songspot-stage-rail{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px;align-items:stretch}
.songspot-stage-step{position:relative;display:grid;min-width:0;min-height:35px;place-items:center;padding:8px 4px;border:1px solid rgba(148,163,184,.2);border-radius:10px;background:rgba(15,23,42,.32);color:#cbd5e1;animation:songspotStepIn .38s cubic-bezier(.16,1,.3,1) var(--stage-delay) both}
.songspot-stage-step b{color:#a5f3fc;font-size:11px;letter-spacing:0;font-variant-numeric:tabular-nums}
.songspot-stage-step i{position:absolute;right:-10px;top:50%;z-index:2;color:#67e8f9;font-size:12px;font-style:normal;transform:translateY(-50%);text-shadow:0 0 12px rgba(103,232,249,.7)}
.songspot-stage-list>small{color:var(--muted);font-size:10px;text-align:center}
.songspot-round{border-color:rgba(103,232,249,.36);background:linear-gradient(145deg,rgba(8,47,73,.68),rgba(30,27,75,.62))}
.songspot-round.is-ready{border-color:rgba(52,211,153,.48);box-shadow:0 24px 70px rgba(2,6,23,.28),0 0 35px rgba(52,211,153,.08)}
.songspot-mystery-cover{transition:filter .25s,box-shadow .25s}
.songspot-mystery-cover.is-playing{animation:songspotCoverPlaying .9s ease-in-out infinite;filter:saturate(1.18);box-shadow:0 0 0 5px rgba(103,232,249,.07),0 0 55px rgba(34,197,94,.32)}
.songspot-round:not(.is-played) .songspot-play-button,.songspot-group-round .songspot-play-button:not(:disabled){animation:songspotPlayBreath 2.4s ease-in-out infinite}
