/* Fresh visual language shared by the new party modes and the rest of the site. */
:root{--motion-fast:160ms;--motion-normal:260ms;--ease-out:cubic-bezier(.2,.8,.2,1)}
.game-card,.panel,.modal,.primary,.secondary,.game-card button,.top-actions .icon-btn{transition:transform var(--motion-normal) var(--ease-out),box-shadow var(--motion-normal) var(--ease-out),border-color var(--motion-fast) ease,background-color var(--motion-fast) ease}
.game-card:hover{transform:translateY(-4px);box-shadow:0 18px 44px rgba(3,8,28,.3)}
