.charades-stage{position:relative;display:grid;min-height:180px;place-items:center;align-content:center;gap:8px;overflow:hidden;border:1px solid rgba(34,211,238,.16);border-radius:24px;background:linear-gradient(135deg,rgba(124,58,237,.11),rgba(8,145,178,.1))}.charades-stage>span{position:relative;font-size:clamp(3rem,8vw,5.4rem);filter:drop-shadow(0 12px 24px rgba(167,139,250,.35));animation:charadesFloat 3s ease-in-out infinite}.charades-spotlight{position:absolute;inset:auto 15% -65%;height:160%;border-radius:50%;background:radial-gradient(ellipse,rgba(167,139,250,.13),transparent 65%);animation:spotlightBreathe 4s ease-in-out infinite}
.charades-score-strip,.hangman-score-strip{display:flex;flex-wrap:wrap;justify-content:center;gap:9px}.charades-score-strip>span,.hangman-score-strip>span{display:flex;align-items:center;gap:8px;padding:9px 13px;border:1px solid rgba(148,163,184,.15);border-radius:999px;background:rgba(255,255,255,.045);color:#dbeafe;font-size:.88rem}.charades-score-strip>span.is-actor{border-color:rgba(251,191,36,.42);color:#fde68a}.charades-score-strip b,.hangman-score-strip b{color:#67e8f9}
.charades-guess-form{display:flex;gap:10px;max-width:720px;margin:0 auto;width:100%}.charades-guess-form input{flex:1;min-width:0;border-radius:15px}.charades-guess-form button{min-width:150px}.charades-actor-note,.charades-wait{margin:0;text-align:center;color:var(--muted)}.charades-guess-list{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:8px;max-height:180px;overflow:auto}.charades-guess{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:9px 11px;border:1px solid rgba(148,163,184,.14);border-radius:13px;background:rgba(255,255,255,.04);animation:guessIn .25s var(--ease-out) both}.charades-guess span{color:var(--muted);font-size:.8rem}.charades-guess b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.86rem}.charades-guess.is-correct{border-color:rgba(52,211,153,.4);background:rgba(16,185,129,.1)}
.charades-reveal,.hangman-reveal,.charades-final,.hangman-final{justify-items:center;text-align:center}.charades-reveal h1,.hangman-reveal h1{margin:0;font-size:clamp(2.4rem,8vw,5rem);color:#f8fafc;letter-spacing:-.04em}.charades-reveal-burst,.hangman-trophy{font-size:3.5rem;animation:revealPop .55s var(--ease-out) both}.charades-ranking,.hangman-ranking{display:grid;gap:9px;width:min(100%,620px);margin:8px auto}.charades-ranking article,.hangman-ranking article{display:flex;justify-content:space-between;gap:14px;padding:13px 16px;border:1px solid rgba(167,139,250,.2);border-radius:15px;background:rgba(255,255,255,.045);animation:guessIn .35s var(--ease-out) both}.charades-ranking b,.hangman-ranking b{color:#67e8f9}
.hangman-layout{display:grid;grid-template-columns:minmax(180px,.8fr) minmax(0,1.5fr);align-items:center;gap:clamp(14px,4vw,36px);padding:10px 4px}.hangman-drawing{display:block;width:min(100%,260px);margin:auto;overflow:visible}.hangman-stand{fill:none;stroke:rgba(203,213,225,.42);stroke-width:5;stroke-linecap:round;stroke-linejoin:round}.hangman-part{fill:none;stroke:#a78bfa;stroke-width:5;stroke-linecap:round;stroke-linejoin:round;animation:hangmanDraw .45s var(--ease-out) both;filter:drop-shadow(0 0 8px rgba(167,139,250,.3))}.hangman-face{stroke:#fb7185}.hangman-word{display:flex;flex-wrap:wrap;justify-content:center;gap:clamp(5px,1.5vw,13px)}.hangman-word span{display:grid;place-items:center;width:clamp(30px,7vw,62px);height:clamp(42px,9vw,72px);border-bottom:3px solid rgba(103,232,249,.65);color:#f8fafc;font-size:clamp(1.5rem,5vw,3rem);font-weight:950;animation:letterRise .28s var(--ease-out) both}.hangman-word span.is-revealed{color:#67e8f9}
.hangman-lives{display:flex;justify-content:center;align-items:center;gap:7px;color:#fda4af}.hangman-lives i{font-size:1.2rem;font-style:normal;color:#fb7185;transition:transform .2s ease,color .2s ease}.hangman-lives i.is-lost{color:rgba(148,163,184,.25);transform:scale(.7)}.hangman-lives span{margin-left:8px;color:var(--muted);font-size:.85rem}.hangman-keyboard{display:grid;grid-template-columns:repeat(10,minmax(0,1fr));gap:8px;max-width:760px;margin:0 auto;width:100%}.hangman-key{min-width:0;min-height:48px;border:1px solid rgba(167,139,250,.25);border-radius:13px;background:linear-gradient(145deg,rgba(124,58,237,.16),rgba(8,145,178,.1));color:#f8fafc;font-weight:900;cursor:pointer;transition:transform .18s ease,border-color .18s ease,background .18s ease}.hangman-key:hover:not(:disabled){transform:translateY(-3px);border-color:#67e8f9;box-shadow:0 8px 22px rgba(34,211,238,.12)}.hangman-key.is-used{opacity:.3;text-decoration:line-through}.hangman-key:disabled{cursor:default}
.charades-settings,.hangman-settings{display:grid;gap:11px}.charades-settings label,.hangman-settings label{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 12px;border:1px solid var(--line);border-radius:13px;background:rgba(255,255,255,.025)}.charades-settings select,.hangman-settings select{width:min(180px,50%);margin:0}
.light-theme .charades-panel,.light-theme .hangman-panel{background:radial-gradient(ellipse at 10% 0%,rgba(124,58,237,.1),transparent 42%),radial-gradient(ellipse at 100% 100%,rgba(34,211,238,.1),transparent 38%),linear-gradient(145deg,#fff,#f3f6ff);box-shadow:0 18px 56px rgba(51,65,85,.12)}.light-theme .charades-heading h1,.light-theme .hangman-heading h1,.light-theme .charades-reveal h1,.light-theme .hangman-reveal h1{color:#172554}.light-theme .charades-score-strip>span,.light-theme .hangman-score-strip>span{color:#334155;background:rgba(255,255,255,.75)}.light-theme .charades-guess,.light-theme .charades-ranking article,.light-theme .hangman-ranking article{color:#334155;background:rgba(255,255,255,.72)}.light-theme .hangman-word span{color:#172554}
.game-visual-charades{background:radial-gradient(circle at 50% 85%,rgba(251,191,36,.3),transparent 35%),linear-gradient(135deg,#4c1d95,#7c3aed 48%,#0891b2)}.game-visual-hangman{background:radial-gradient(circle at 70% 25%,rgba(34,211,238,.24),transparent 32%),linear-gradient(135deg,#172554,#4338ca 52%,#7c3aed)}.game-visual-charades span,.game-visual-hangman span{font-size:70px;filter:drop-shadow(0 10px 20px rgba(0,0,0,.35));animation:charadesFloat 3.5s ease-in-out infinite}
@keyframes partyPanelIn{from{opacity:0;transform:translateY(14px) scale(.99)}to{opacity:1;transform:none}}@keyframes secretReveal{from{opacity:0;transform:scale(.96);filter:blur(4px)}to{opacity:1;transform:none;filter:none}}@keyframes charadesFloat{0%,100%{transform:translateY(0) rotate(-4deg)}50%{transform:translateY(-9px) rotate(4deg)}}@keyframes spotlightBreathe{0%,100%{opacity:.55;transform:scale(.95)}50%{opacity:1;transform:scale(1.04)}}@keyframes guessIn{from{opacity:0;transform:translateY(7px)}to{opacity:1;transform:none}}@keyframes revealPop{0%{opacity:0;transform:scale(.45) rotate(-14deg)}70%{transform:scale(1.13) rotate(5deg)}100%{opacity:1;transform:none}}@keyframes hangmanDraw{from{stroke-dasharray:140;stroke-dashoffset:140;opacity:.2}to{stroke-dashoffset:0;opacity:1}}@keyframes letterRise{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:none}}
@media(max-width:620px){.charades-page,.hangman-page{padding:10px}.charades-panel,.hangman-panel{gap:17px;padding:18px;border-radius:22px}.charades-heading,.hangman-heading{align-items:flex-start}.charades-clock,.hangman-clock{flex-basis:58px;width:58px;height:58px;border-radius:17px}.charades-guess-form{flex-direction:column}.charades-guess-form button{width:100%}.hangman-layout{grid-template-columns:1fr;gap:8px}.hangman-drawing{width:190px}.hangman-keyboard{grid-template-columns:repeat(7,minmax(0,1fr));gap:6px}.hangman-key{min-height:43px;border-radius:10px}.charades-settings label,.hangman-settings label{align-items:flex-start;flex-direction:column}.charades-settings select,.hangman-settings select{width:100%}}
@media(prefers-reduced-motion:reduce){.charades-panel,.hangman-panel,.charades-stage>span,.charades-spotlight,.charades-secret,.charades-reveal-burst,.hangman-trophy,.hangman-part,.hangman-word span,.charades-guess,.charades-ranking article,.hangman-ranking article{animation:none!important}.game-card,.panel,.modal,.primary,.secondary,.hangman-key{transition:none!important}}

/* Team Auction */
.auction-stage { text-align: left; align-items: start; }
.auction-main,.auction-turn { display: grid; gap: 12px; min-width: 0; }
.auction-header { display: flex; align-items: center; justify-content: space-between; gap: 10px; }
.auction-header h1 { font-size: clamp(22px, 4vw, 40px); margin: 0; }
.auction-header .eyebrow { margin: 0 0 4px; }
.auction-header .pokemon-timer { margin: 0; min-width: 56px; }
.auction-spotlight {
  overflow: hidden;
  border-radius: 22px;
  border: 1px solid rgba(99, 231, 211, .23);
  background: radial-gradient(ellipse at 50% 32%, #255452, #131926 68%);
}
.auction-spotlight .pokemon-card {
  display: grid;
  justify-items: center;
  justify-content: center;
  text-align: center;
  gap: 3px;
  min-height: 190px;
  padding: 12px;
  margin: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}
.auction-spotlight .pokemon-card img { width: clamp(96px, 18vw, 158px); height: auto; aspect-ratio: 1; object-fit: contain; filter: drop-shadow(0 14px 12px #091a24); }
.auction-spotlight .pokemon-card b { font-size: clamp(19px, 3vw, 26px); text-transform: capitalize; }
.auction-spotlight .pokemon-card strong { color: #fff0b0; }
.auction-spotlight .pokemon-card strong[aria-hidden] { visibility: hidden; }
.auction-price, .auction-outcome {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-height: 53px;
  padding: 10px 14px;
  border: 1px solid rgba(133, 179, 235, .23);
  border-radius: 14px;
  background: rgba(11, 21, 37, .7);
  color: #dce9fc;
}
.auction-price strong, .auction-outcome span { color: #80efe1; font-size: 23px; font-weight: 850; }
.auction-price.is-leading { border-color: #6bdcc6; }
.auction-price.auction-raised strong { animation: auction-price-pop .36s cubic-bezier(.2,.8,.35,1.35); }
.auction-price.auction-outbid { border-color: #ffb382; background: #392734; }
.auction-outcome { min-height: 108px; flex-wrap: wrap; color: #f5ebff; animation: auction-card-in .35s ease-out both; }
.auction-outcome small { flex-basis: 100%; letter-spacing: .11em; font-weight: 850; color: #c6a8fa; }
.auction-outcome.is-mine { border-color: #f5cc70; background: radial-gradient(ellipse at 36% 0%, #574321, #1b2334 80%); }
.auction-outcome.is-mine small, .auction-outcome.is-mine span { color: #ffe298; }
.auction-wallet {
  display:flex; justify-content:space-between; align-items:center; gap:10px;
  padding:9px 14px; border-radius:14px; border:1px solid #d4ac5869;
  background:linear-gradient(120deg,#362a1c,#222333); color:#fff0c9;
}
.auction-wallet span { display:inline-flex; align-items:center; gap:7px; font-weight:750; }
.auction-wallet-coin {
  display:inline-grid; place-items:center; flex:none; width:18px; height:18px;
  border:1px solid #ffdd8b; border-radius:50%;
  background:linear-gradient(145deg,#ffe9a4,#d89a38); color:#533413;
  font-size:12px; font-style:normal; font-weight:900; line-height:1;
}
.auction-wallet strong { color:#ffe38f; font-size:clamp(23px,5vw,30px); font-variant-numeric:tabular-nums; }
.auction-controls { display: grid; grid-template-columns: minmax(0, 1fr) minmax(70px, .4fr); gap: 8px; margin: 0; }
.auction-controls button { min-height: 44px; }
.auction-note { margin: 0; min-height: 1.3em; color: #b5c3db; font-size: 12px; }
.auction-roster { min-width: 0; }
.auction-sidebar { display:grid; gap:10px; min-width:0; }
.auction-opponents { min-width:0; }
.auction-opponents h2 { margin:0 0 5px; font-size:12px; }
.auction-opponent-list { display:grid; gap:5px; list-style:none; margin:0; padding:0; }
.auction-opponent {
  min-width:0; padding:6px 8px; border:1px solid var(--line,#29334a);
  border-radius:9px; background:rgba(255,255,255,.035);
}
.auction-opponent-head { display:flex; align-items:center; justify-content:space-between; gap:5px; font-size:12px; }
.auction-opponent-head b { min-width:0; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; }
.auction-opponent-head strong { color:#ffe38f; font-variant-numeric:tabular-nums; }
.light-theme .auction-opponent-head strong { color:#795006; }
.auction-opponent-team { display:flex; align-items:center; flex-wrap:wrap; gap:3px; margin-top:2px; }
.auction-opponent-team img { display:block; width:25px; height:25px; object-fit:contain; }
.auction-opponent-team small { color:var(--muted,#a7b4ca); font-size:10px; }
.auction-slots { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 6px; }
.auction-slot { display: grid; justify-items: center; align-content: center; gap: 2px; min-height: 65px; min-width: 0; border-radius: 10px; background: #1d2d41; text-align: center; }
.auction-slot img, .auction-ranking-team img { width: 36px; height: 36px; object-fit: contain; }
.auction-slot b { font-size: 10px; overflow-wrap: anywhere; }
.auction-slot small { color: #9ce7d8; font-size: 10px; }
.auction-slot.is-empty { background: transparent; color: #9eacc2; border: 1px dashed #48546d; }
.auction-final { text-align: center; background-image: radial-gradient(ellipse at 50% 0, #3a304b, transparent 66%); }
.auction-ranking { display: grid; gap: 10px; max-width: 660px; margin: 22px auto; text-align: left; }
.auction-ranking-row { display: grid; gap: 6px; border: 1px solid #48546d; border-radius: 16px; background: #1a2236; padding: 10px 14px; animation: auction-card-in .35s ease-out both; animation-delay: calc(var(--auction-rank) * 45ms); }
.auction-ranking-row > div:first-child { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.auction-ranking-row.is-winner { border-color: #e6c16b; box-shadow: 0 0 24px #e6c16b22; }
.auction-ranking-row.is-winner strong { color: #ffe298; }
.auction-ranking-team { display: flex; flex-wrap: wrap; gap: 5px; }
.auction-ranking-team > span { display: grid; justify-items: center; font-size: 10px; }
@keyframes auction-price-pop { 0% { transform: scale(.86); } 55% { transform: scale(1.17); } }
@keyframes auction-card-in { from { opacity: 0; transform: translateY(7px); } }
@media (max-width: 700px) {
  .auction-stage { grid-template-columns: minmax(0, 1fr); gap: 12px; }
  .auction-turn { min-height: 151px; align-content: start; }
  .auction-spotlight .pokemon-card { min-height: 142px; }
  .auction-slots { grid-template-columns: repeat(auto-fit, minmax(50px, 1fr)); }
  .auction-roster { padding: 10px; }
  .auction-opponent-list { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .auction-opponent:only-child { grid-column:1/-1; }
}
@media (prefers-reduced-motion: reduce) {
  .auction-price.auction-raised strong, .auction-outcome, .auction-ranking-row { animation: none; }
}

/* Warcaby */
.board-checkers-stage .board-stage-title h1 { margin: 0; }
.checkers-turn { margin: 4px 0 0; color: #a4dfd5; font-size: .9rem; }
.board-checkers-stage .checkers-layout { grid-template-columns: minmax(0, 520px) minmax(155px, 1fr); align-items: start; }
.board-checkers-stage .checkers-board {
  width: 100%; margin: 0; gap: 0; padding: 7px;
  background: #362b39; border-color: #857083; border-radius: 13px;
}
.board-checkers-stage .checkers-cell { border: 0; border-radius: 0; box-shadow: none; }
.board-checkers-stage .checkers-cell.light { background: #debf9d; }
.board-checkers-stage .checkers-cell.dark { background: #6c4852; }
.board-checkers-stage .checkers-cell.is-last { box-shadow: inset 0 0 0 2px #dfb66baa; }
.board-checkers-stage .checkers-cell.is-source { cursor: pointer; }
.board-checkers-stage .checkers-cell.is-source .checkers-piece { outline: 2px solid #9df7de; outline-offset: 2px; }
.board-checkers-stage .checkers-cell.is-selected { background: #346f6b; }
.board-checkers-stage .checkers-cell.is-target { background: #526e69; }
.checkers-cell.is-target > span { width: 26%; aspect-ratio: 1; border-radius: 50%; background: #adf9dc; }
.board-checkers-stage .checkers-piece {
  width: 71%; height: 71%; border-width: 2px; animation: none;
  box-shadow: inset 0 0 0 3px #231c2a24, 0 3px 0 #231c2a70;
}
.board-checkers-stage .piece-a { background: #f8e5bb; border-color: #fff2d0; color: #68503a; }
.board-checkers-stage .piece-b { background: #993c62; border-color: #e18aaa; color: #fff2d0; }
.board-checkers-stage .checkers-piece.is-king { border-color: #ffd87d; }
.checkers-sidebar, .checkers-players { display: grid; gap: 8px; min-width: 0; }
.checkers-player, .checkers-history { padding: 8px 10px; border: 1px solid #fff2; border-radius: 9px; background: #101727; }
.checkers-player { display: grid; grid-template-columns: auto minmax(0,1fr) auto; gap: 7px; align-items: center; }
.checkers-player.is-current { border-color: #9df7de; }
.checkers-player span { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.checkers-color { width: 11px; height: 11px; border: 1px solid; border-radius: 50%; }
.checkers-history h2 { margin: 0 0 6px; font-size: .85rem; }
.checkers-history ol { list-style: none; padding: 0; margin: 0; display: grid; gap: 3px; }
.checkers-history li { display: grid; grid-template-columns: auto minmax(0,1fr) auto; align-items: center; gap: 6px; font-size: .82rem; }
.checkers-history p { margin: 0; color: #acb9cc; }
@media (max-width:700px) {
  .board-checkers-stage .board-stage-title { flex-direction: row; align-items: center; }
  .board-checkers-stage .checkers-layout { grid-template-columns: minmax(0,1fr); gap: 10px; }
  .checkers-players { grid-template-columns: repeat(2,minmax(0,1fr)); }
  .checkers-history ol { grid-template-columns: repeat(2,minmax(0,1fr)); }
}
.impostor-pair-feedback {
  margin: 0 auto 12px;
  max-width: 440px;
}
.impostor-pair-feedback summary {
  width: fit-content;
  margin: auto;
  padding: 8px 10px;
  cursor: pointer;
  color: #a5f3fc;
  font-weight: 700;
}
.light-theme .impostor-pair-feedback summary { color: #155e75; }
.impostor-pair-words {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px 12px;
  margin: 4px 0 9px;
}
.impostor-pair-feedback .choice-row { justify-content: center; flex-wrap: wrap; }
.impostor-pair-feedback .choice-row[hidden], .impostor-pair-feedback [role="status"]:empty { display: none; }

.impostor-layout.impostor-layout-solo { grid-template-columns: minmax(0,1fr); }
.poison-candy-page {
  max-width: 1200px;
  padding-top: clamp(10px, 2vh, 18px);
}
.candy-game-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px 12px;
  margin-bottom: 10px;
}
.candy-game-header .eyebrow { margin: 0 0 3px; }
.candy-game-header h1 { margin: 0; font-size: clamp(1.25rem, 3vw, 2rem); }
.candy-game-header .leave-game { flex: none; padding-inline: 10px; }
.poison-candy-page .candy-table-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, .51fr);
  align-items: start;
  gap: clamp(10px, 2vw, 22px);
  min-height: 0;
  margin: 0;
  padding: clamp(10px, 1.5vw, 18px);
  border-radius: 24px;
}
.candy-table-layout .candy-table {
  justify-self: center;
  align-self: center;
  width: min(100%, 670px, max(340px, calc(100dvh - 210px)));
  max-height: none;
  margin: 0;
  container-type: inline-size;
}
.candy-table-layout .candy-token {
  width: clamp(22px, 7.5cqi, 42px);
  height: clamp(22px, 7.5cqi, 42px);
  min-height: 0;
}
.candy-table-layout .is-dense .candy-token {
  width: clamp(17px, 6cqi, 34px);
  height: clamp(17px, 6cqi, 34px);
}
.candy-table-layout .candy-token > span {
  width: min(33px, 72%);
  height: min(22px, 48%);
}
.candy-side { display: grid; gap: 9px; min-width: 0; }
.candy-controls { margin: 0; padding: 11px 12px; min-width: 0; }
.candy-controls h2 { margin: 0; font-size: clamp(1rem, 2vw, 1.3rem); overflow-wrap: anywhere; }
.candy-controls p { margin: 5px 0 0; font-size: .82rem; line-height: 1.35; }
.candy-controls small { display: block; margin-top: 5px; }
.candy-controls [data-candy-shield] { margin-top: 8px; }
.candy-control-heading, .candy-poison-actions { display: flex; align-items: center; justify-content: space-between; gap: 6px 10px; }
.candy-poison-actions { flex-wrap: wrap; margin-top: 7px; }
.candy-selection-count { font-size: .8rem; white-space: nowrap; }
.candy-clock {
  display: inline-flex;
  flex: none;
  align-items: center;
  gap: 5px;
  padding: 5px 8px;
  border: 1px solid currentColor;
  border-radius: 9px;
  color: #c4b5fd;
  font-variant-numeric: tabular-nums;
}
.candy-clock b { min-width: 3ch; text-align: center; white-space: nowrap; }
.candy-clock.is-urgent { color: #fda4af; }
.light-theme .candy-clock { color: #5b21b6; }
.light-theme .candy-clock.is-urgent { color: #9f1239; }
.candy-roster h3 {
  display: flex;
  justify-content: space-between;
  gap: 8px;
  margin: 0 0 5px;
