body:has(.impostor-round-header.is-timed) { overflow-x: clip; }
.impostor-page {
  --impostor-header-bg: #131827;
  --impostor-clock-urgent: #fda4af;
  padding-top: clamp(10px, 2vw, 22px);
}
.light-theme .impostor-page {
  --impostor-header-bg: #f7f9ff;
  --impostor-clock-urgent: #9f1239;
}
.impostor-round-header {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: clamp(5px, 1.5vw, 14px);
  margin-bottom: 12px;
  padding: 5px clamp(6px, 1.2vw, 12px);
  border: 1px solid color-mix(in srgb, var(--impostor-accent) 22%, transparent);
  border-radius: 16px;
  background: color-mix(in srgb, var(--impostor-accent) 6%, var(--impostor-header-bg));
}
.impostor-round-header.is-timed {
  position: sticky;
  top: var(--impostor-header-offset, 0px);
  z-index: 4;
}
.impostor-page .impostor-round-header .impostor-players {
  min-width: 0;
  gap: 6px;
