  padding: 5px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  scrollbar-width: thin;
}
.impostor-round-header .impostor-player {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
  min-height: 39px;
  flex: none;
  padding: 4px 8px;
  border-radius: 10px;
}
.impostor-round-header .impostor-player small {
  position: static;
  color: inherit;
  opacity: .7;
}
.impostor-round-header .mini-player { gap: 5px; }
.impostor-round-header .avatar { width: 28px; height: 28px; flex: none; }
.impostor-round-header .nick {
  max-width: clamp(70px, 12vw, 120px);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: .86rem;
}
.impostor-round-header .reaction-bubble {
  top: auto;
  bottom: 0;
  right: 2px;
  padding: 3px 5px;
  line-height: 1;
  pointer-events: none;
}
.impostor-clock {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  padding: 6px 9px;
  border: 1px solid color-mix(in srgb, currentColor 40%, transparent);
  border-radius: 11px;
  color: var(--impostor-accent);
  background: var(--impostor-header-bg);
  font-variant-numeric: tabular-nums;
  white-space: nowrap;
}
.impostor-clock.is-urgent { color: var(--impostor-clock-urgent); }
.impostor-clock b { min-width: 3ch; text-align: center; font-size: 1rem; }
.impostor-clock-face {
  position: relative;
  width: 24px;
  height: 24px;
  border: 2px solid currentColor;
  border-radius: 50%;
  background:
    linear-gradient(currentColor, currentColor) center / 2px 2px no-repeat,
    linear-gradient(currentColor, currentColor) center 2px / 1px 2px no-repeat,
    linear-gradient(currentColor, currentColor) center calc(100% - 2px) / 1px 2px no-repeat,
    linear-gradient(currentColor, currentColor) 2px center / 2px 1px no-repeat,
    linear-gradient(currentColor, currentColor) calc(100% - 2px) center / 2px 1px no-repeat;
}
.impostor-clock-face::before {
  position: absolute;
  left: calc(50% - 1px);
  bottom: 50%;
  width: 2px;
  height: 7px;
  border-radius: 2px;
  background: currentColor;
  transform: rotate(var(--impostor-hand-angle, 0deg));
  transform-origin: bottom center;
  content: "";
}
.impostor-page .role-card {
  margin: clamp(10px, 2.4vh, 24px) auto 12px;
  padding: clamp(14px, 3vh, 26px);
}
.impostor-page .role-card .role-owner { margin-bottom: 8px; }
.impostor-page .role-card .avatar { width: 40px; height: 40px; }
.impostor-page .role-card h1 { font-size: clamp(1.9rem, 5vw, 2.9rem); }
.impostor-page .role-card > p { margin-block: 5px; line-height: 1.4; }
.impostor-page .role-card strong {
  margin: 8px 0;
  font-size: clamp(1.55rem, 4.5vw, 2.35rem);
  overflow-wrap: anywhere;
}
.impostor-page .role-card button { margin-top: 8px; }
.impostor-page .role-purchase-panel { margin: 0 auto 12px; padding: clamp(9px, 2vw, 16px); }
.impostor-page .role-purchase-panel p { margin: 5px 0; }
.impostor-page .role-purchase-panel .choice-row { display: flex; gap: 6px; }
.impostor-page .role-purchase-panel .choice-row button { width: auto; padding-inline: 10px; }
.impostor-role-footer {
  display: flex;
  align-items: center;
  justify-content: center;
  flex-wrap: wrap;
  gap: 7px 12px;
  font-size: .85rem;
}
.impostor-role-footer p { margin: 0; }
.impostor-stage-heading h2 { overflow-wrap: anywhere; }
.impostor-page .secret-strip {
  flex-direction: row;
  gap: 5px 12px;
  margin-bottom: 12px;
  padding: 9px 14px;
  font-size: .9rem;
}
@media (prefers-reduced-motion: no-preference) {
  .impostor-clock-face::before { transition: transform .22s ease-out; }
}
@media (prefers-reduced-motion: no-preference) {
  .impostor-page .impostor-cue {
    animation: impostor-card-cue 440ms var(--impostor-cue-delay,0ms) ease-out;
  }
}
@keyframes impostor-card-cue {
  from { transform: translateY(3px); box-shadow: 0 0 0 2px color-mix(in srgb,var(--impostor-accent) 30%,transparent); }
  to { transform: translateY(0); }
}

