.family-wheel-wrap {
  position: relative;
  width: min(100%, 390px);
  aspect-ratio: 1;
  margin: 12px auto 0;
}
.family-player-wheel {
  position: relative;
  width: 100%;
  aspect-ratio: 1;
  border: 5px solid #f4c86d;
  border-radius: 50%;
  box-shadow: 0 0 28px #fbbf2429;
}
.family-player-wheel::after {
  content: "";
  position: absolute;
  inset: 44%;
  border: 2px solid #f4c86d;
  border-radius: 50%;
  background: #152039;
  box-shadow: 0 2px 10px #11182777;
}
.family-wheel-pointer {
  position: absolute;
  z-index: 1;
  top: -9px;
  left: 50%;
  transform: translateX(-50%);
  width: 24px;
  height: 24px;
  clip-path: polygon(0 0,100% 0,50% 100%);
  background: #ffe39d;
}
.family-wheel-seat {
  position: absolute;
  top: var(--y);
  left: var(--x);
  transform: translate(-50%, -50%);
}
.family-wheel-profile {
  display: grid;
  gap: 3px;
  justify-items: center;
  width: clamp(44px, 17vw, 72px);
