/* source: songSpotMobile.css */
/* Desktop keeps its three-column sidebars. Mobile starts with the game. */
.songspot-mobile-panel,.songspot-mobile-panel-body{display:contents}
.songspot-mobile-toggle{display:none}
.songspot-layout .songspot-filters{order:0}
