m:translateY(-4px) scale(1.08)}72%{opacity:1;transform:translateY(-4px) scale(1)}100%{opacity:0;transform:translateY(-28px) scale(.94)}}@media(max-width:720px){.quick-reactions-bar{right:8px;bottom:8px;left:8px;justify-content:center;gap:3px;padding:7px 5px}.quick-reactions-label{display:none}.quick-reaction-button{min-width:31px;height:31px;font-size:16px}.quick-reaction-bubble-layer{right:14px;bottom:70px;max-width:calc(100vw - 28px);gap:5px}.quick-reaction-bubble{padding:6px 8px}.quick-reaction-bubble small{max-width:84px}}

.quick-reactions-side {
  --reaction-edge: max(8px, env(safe-area-inset-right));
  --reaction-bottom: calc(68px + env(safe-area-inset-bottom));
  position: fixed;
  right: var(--reaction-edge);
  bottom: var(--reaction-bottom);
  z-index: 20;
}
.quick-reactions-side summary {
