.minecraft-timer{flex-direction:column;align-items:stretch;gap:6px;min-width:118px}.minecraft-timer-label{display:flex;justify-content:center;align-items:center;gap:7px}.minecraft-timer-track{display:block;height:5px;overflow:hidden;border-radius:99px;background:rgba(255,255,255,.14)}.minecraft-timer-track i{display:block;height:100%;border-radius:inherit;background:linear-gradient(90deg,#65e47b,#facc15);transition:width .22s linear}.minecraft-timer.is-urgent{border-color:rgba(248,113,113,.7);color:#fecaca;animation:mcTimerPulse .8s ease-in-out infinite}.minecraft-turn-badge{display:inline-flex;align-items:center;gap:6px;margin-top:17px;padding:7px 11px;border:1px solid rgba(255,255,255,.14);border-radius:999px;background:rgba(255,255,255,.06);color:#cbd5e1;font-size:12px;font-weight:950;letter-spacing:.04em}.minecraft-turn-badge.is-mine{border-color:rgba(101,228,123,.55);background:rgba(101,228,123,.1);color:#bbf7c8;box-shadow:0 0 20px rgba(101,228,123,.12)}.minecraft-turn-badge.is-all{border-color:rgba(96,205,255,.4);background:rgba(96,205,255,.09);color:#b8edff}.minecraft-turn-badge small{opacity:.75;font-size:11px}.minecraft-head-meta{display:flex;align-items:center;gap:9px;flex-wrap:wrap;margin-top:10px}.minecraft-difficulty-chip{padding:5px 9px;border:1px solid rgba(101,228,123,.35);border-radius:999px;background:rgba(101,228,123,.1);color:#bbf7c8;font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.06em}.minecraft-head-caption{color:#9fb9bd;font-size:12px;font-weight:700}.minecraft-round-ranking{display:grid;gap:7px;margin:24px auto 0;max-width:520px;text-align:left}.minecraft-round-ranking .eyebrow{margin:0 0 2px}.minecraft-round-ranking-row{display:grid;grid-template-columns:max-content minmax(0,1fr) max-content;align-items:center;gap:8px;padding:8px 10px;border:1px solid rgba(255,255,255,.1);border-radius:11px;background:rgba(255,255,255,.045);animation:mcSlideIn .3s ease both}.minecraft-round-ranking-row>span{color:#fef08a;font-weight:900}.minecraft-round-ranking-row strong{color:#bbf7c8}.minecraft-earned{font-style:normal;color:#fef08a;font-size:12px;font-weight:900}.minecraft-result-actions{display:flex;justify-content:center;gap:10px;flex-wrap:wrap;margin-top:22px}.minecraft-result-actions button{min-width:176px}.minecraft-result-note{display:block;margin-top:9px;color:#9fb9bd}.minecraft-reveal-icon{display:block;width:74px;height:74px;margin:12px auto 15px;image-rendering:pixelated;object-fit:contain;filter:drop-shadow(0 8px 15px rgba(101,228,123,.24));animation:mcIconPop .45s cubic-bezier(.16,1,.3,1) both}@keyframes mcTimerPulse{0%,100%{box-shadow:0 0 0 rgba(248,113,113,0)}50%{box-shadow:0 0 18px rgba(248,113,113,.22)}}
