.minecraft-commerce-actions{display:flex;align-items:center;justify-content:center;gap:9px;flex-wrap:wrap;margin:12px auto 0;padding:10px 12px;border:1px solid rgba(101,228,123,.24);border-radius:16px;background:linear-gradient(135deg,rgba(101,228,123,.08),rgba(14,116,144,.12));animation:mcSlideIn .32s ease both}.minecraft-commerce-label{color:#bbf7c8;font-size:12px;font-weight:900;letter-spacing:.04em}.minecraft-commerce-button{padding:8px 11px;font-size:12px}.minecraft-commerce-button.is-pending{opacity:.62;pointer-events:none}
@media(max-width:720px){.minecraft-commerce-actions{align-items:stretch;flex-direction:column}.minecraft-commerce-button{width:100%}}

/* Desktop: przycisk powrotu jest paskiem nad hero, a nie osobnym wierszem
   ściskającym tytuł i grafikę. */
@media(min-width:721px){
  .minecraft-selection-hero{grid-template-rows:auto minmax(205px,1fr)}
  .minecraft-selection-hero>#back-to-games{grid-column:1/-1;grid-row:1;justify-self:start;width:auto;margin:-8px 0 0}
  .minecraft-selection-copy{grid-column:1;grid-row:2;align-self:center}
  .minecraft-selection-art{grid-column:2;grid-row:2;align-self:stretch}
}
@media(max-width:720px){
  .minecraft-selection-hero>#back-to-games{grid-column:1;width:auto;justify-self:start}
  .minecraft-selection-copy{grid-column:1}
  .minecraft-selection-art{grid-column:1}
}

.minecraft-question-icon.minecraft-mob-portrait,
.minecraft-reveal-icon.minecraft-mob-portrait {
  padding: 10px;
  border: 1px solid rgba(159, 221, 186, .28);
  border-radius: 14px;
  background: radial-gradient(ellipse at 50% 35%, #94aa9e, #566e65);
  filter: drop-shadow(0 6px 12px rgba(0, 0, 0, .24));
}

.minecraft-question-icon.minecraft-mob-portrait {
  display: grid;
  grid-template: minmax(0, 1fr) / minmax(0, 1fr);
  background: radial-gradient(ellipse at 50% 35%, #4d6058, #293a36);
}

.minecraft-mob-silhouette {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: contain;
  filter: brightness(0) blur(3px);
}

@media (max-width: 600px) {
  .minecraft-question-icon.minecraft-mob-portrait { padding: 6px; border-radius: 10px; }
}

.minecraft-game-page :is(.minecraft-round-ranking-row,.minecraft-leaderboard-row) > .mini-player {
  min-width: 0;
  gap: 7px;
}
.minecraft-game-page :is(.minecraft-round-ranking-row,.minecraft-leaderboard-row) > .mini-player > :is(.avatar,.level-badge) {
  flex-shrink: 0;
}
.minecraft-game-page :is(.minecraft-round-ranking-row,.minecraft-leaderboard-row) > .mini-player > .nick {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.minecraft-ranking-score {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 6px;
  white-space: nowrap;
}
.minecraft-ranking-score .minecraft-earned {
  border-radius: 999px;
  padding: 2px 6px;
  background: #a9f97d24;
  color: #d6ffc9;
}
.minecraft-game-page .minecraft-reveal-card.is-correct .minecraft-answer-reveal { color: #d6ffc9; }
@media (max-width: 450px) {
  .minecraft-game-page .minecraft-reveal-card { padding: 16px 12px; }
  .minecraft-game-page :is(.minecraft-round-ranking-row,.minecraft-leaderboard-row) { gap: 6px; padding-inline: 8px; }
  .minecraft-game-page :is(.minecraft-round-ranking-row,.minecraft-leaderboard-row) > .mini-player { gap: 5px; }
  .minecraft-game-page :is(.minecraft-round-ranking-row,.minecraft-leaderboard-row) > .mini-player > .avatar { width: 30px; height: 30px; min-width: 30px; }
  .minecraft-ranking-score { gap: 4px; }
}


