 right:0;bottom:11px;width:100%;height:57px;clip-path:polygon(0 73%,16% 73%,16% 56%,32% 56%,32% 36%,47% 36%,47% 55%,63% 55%,63% 70%,82% 70%,82% 48%,100% 48%,100% 100%,0 100%);
