 filter:drop-shadow(0 3px 6px #0a171b);
}
[data-journey-chapter="2"] .journey-chapter-detail::before,[data-journey-chapter="3"] .journey-chapter-detail::before{content:none}
[data-journey-chapter="3"] .journey-chapter-light{right:6%;width:17px;height:17px;background:#e6ac7f;box-shadow:0 0 22px #ed987da0}
[data-journey-chapter="3"] .journey-chapter-landmark{
