@keyframes journey-chapter-glow{50%{opacity:.68}}
@keyframes journey-chapter-flight{50%{transform:translate(-8px,-4px)}}
.rescue-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(170px,255px);gap:16px;align-items:start}
.rescue-quest{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin:0 0 12px}
