.siege-page {
 --siege-gold: #f6d99a;
 --siege-line: #f4d6a644;
 --siege-paper: #f1d9ab;
 --siege-ink: #40291d;
}
.siege-layout { display:grid; grid-template-columns:minmax(0,1fr) minmax(175px,232px); gap:16px; align-items:start; }
.siege-play { padding:clamp(12px,2.2vw,24px); min-width:0; }
.siege-quest { display:flex; justify-content:space-between; gap:12px; margin-bottom:14px; }
.siege-quest h2 { font-size:clamp(22px,3.2vw,36px); line-height:1.08; margin:3px 0 8px; color:#fff1d6; }
.siege-quest p { margin:0; line-height:1.45; color:#d7d5cb; }
.siege-quest .eyebrow { color:#e1ba79; font-size:10px; }
.siege-camera { position:relative; aspect-ratio:16/9; isolation:isolate; overflow:clip; border:3px solid #c29b6366; border-radius:12px; background:#151b23; }
.siege-track { position:relative; display:flex; width:1000%; height:100%; transform:translateX(calc(var(--scene) * -10%)); transition:transform .75s cubic-bezier(.38,0,.24,1); }
.siege-scene { position:relative; flex:0 0 10%; height:100%; overflow:hidden; isolation:isolate; background:linear-gradient(175deg,#141923,#322e3b 70%,#282730); }
.siege-home,.siege-sunset { background:linear-gradient(#5b475f,#d09180 59%,#624d5e); }
.siege-house-night,.siege-tower,.siege-freeze { background:linear-gradient(158deg,#141425,#524361 59%,#152333); }
.siege-forge { background:radial-gradient(ellipse at 61% 63%,#a65e3f 4%,#593b36 26%,transparent 65%),linear-gradient(145deg,#211922,#3a2e3b); }
.siege-woods { background:radial-gradient(ellipse at 76% 58%,#8b6357,#192c30 65%); }
.siege-yard { background:radial-gradient(ellipse at 68% 45%,#624651,#293347 60%,#151e2b); }
.siege-gallery { background:radial-gradient(ellipse at 82% 25%,#7d5341,#242736 60%); }
.siege-store { background:radial-gradient(ellipse at 68% 35%,#57464a,#191c2b 66%); }
.siege-cell { background:radial-gradient(ellipse at 80% 56%,#67534b 4%,#282637 41%,#141a25 83%); }
.siege-tile,.siege-prop,.siege-actor,.siege-node,.siege-hero { position:absolute; }
