.siege-prop,.siege-actor { display:grid; place-items:center; pointer-events:none; }
.siege-prop img,.siege-prop>svg,.siege-actor>svg,.siege-node img,.siege-node>svg,.siege-hero>svg,.siege-pack svg { width:100%; height:100%; object-fit:contain; image-rendering:pixelated; }
.siege-prop img,.siege-prop>svg,.siege-actor>svg,.siege-hero>svg { filter:drop-shadow(2px 5px 3px #0008); }
.siege-node {
