 min-height:0; min-width:0; background:#090e1536; border:1px solid #f0cb8660; border-radius:10%;
 box-shadow:0 3px 5px #07071755,inset 0 0 8px #d8b26112; transition:left .5s,background .18s,border .18s; touch-action:manipulation;
