.siege-mark { position:absolute; top:-30%; right:-6%; display:grid; place-items:center; width:50%; aspect-ratio:1; border:1px solid #c99c65; border-radius:30%; background:#272334; color:#ffe4a2; font-size:clamp(9px,1.5vw,20px); }
.siege-hero { z-index:5; top:41.667%; left:calc(var(--hero) * 100% / 160); width:1%; height:25%; pointer-events:none; transition:left .56s cubic-bezier(.34,.6,.42,1); }
.siege-hero-block>svg:last-child { position:absolute; inset:30% auto auto 55%; width:60%; height:65%; animation:siege-flash .35s ease-out; }
.siege-patrol { z-index:2; transition:left .48s ease; }
.siege-blocked-guard { opacity:.55; transform:translateX(20%); transition:transform .4s ease, opacity .4s; }
.siege-lookout { opacity:.82; }
.siege-flight { position:absolute; width:50%; left:32%; top:45%; color:#ffe1a4; font-size:clamp(18px,4vw,46px); animation:siege-arrow .56s ease-out both; pointer-events:none; z-index:8; }
.siege-impact { position:absolute; inset:28% 39% 31% 48%; background:radial-gradient(ellipse,#fff3cbb0,transparent 80%); pointer-events:none; animation:siege-flash .48s ease-out both; }
.siege-window-glow { position:absolute; background:linear-gradient(140deg,#f8e5bf,#9d92c4 62%,#533c62); box-shadow:0 0 34px #edcda299; }
.siege-status { display:flex; align-items:center; justify-content:space-between; gap:8px; min-height:57px; margin-top:8px; }
.siege-status p,.siege-item-name { margin:0; color:#e6ddcc; font-size:13px; }
.siege-status button { flex:none; }
.siege-pack h3 { margin:0 0 8px; }
.siege-pack .journey-inventory { grid-template-columns:repeat(4,minmax(0,1fr)); }
.siege-item-name { min-height:30px; margin:9px 0; }
.siege-bench { display:grid; gap:10px; padding-top:12px; border-top:1px solid var(--siege-line); }
.siege-bench .journey-craft-grid { width:100%; max-width:190px; }
.siege-bench .journey-slot { aspect-ratio:1; }

.siege-storyboard { max-width:1040px; margin:auto; background:#171724; padding:clamp(7px,1.5vw,16px); border:1px solid var(--siege-line); border-radius:20px; box-shadow:0 18px 60px #05051399; }
.siege-comic-frame { overflow:hidden; position:relative; background:#271f2c; border:2px solid #ecdaae80; border-radius:9px; }
.siege-comic-art { position:relative; overflow:hidden; isolation:isolate; aspect-ratio:2.08; min-height:225px; }
.siege-comic-art::after { content:""; position:absolute; inset:0; pointer-events:none; z-index:9; box-shadow:inset 0 0 75px #22121875; }
.siege-camera-pan,.siege-window-rush,.siege-letter-background { position:absolute; inset:0; }
.siege-camera-pan { animation:siege-pan 3s ease-out both; }
.siege-room-zoom { transform-origin:76% 54%; animation:siege-room 2.9s ease-out both; }
.siege-letter-background { transform:scale(1.65); transform-origin:72% 57%; filter:brightness(.38) blur(1px); }
.siege-walk-in { animation:siege-walk-in 2.75s ease-out both; z-index:6; }
.siege-groceries { animation:siege-walk-in 2.75s ease-out both; z-index:7; }
.siege-startled { animation:siege-startled .45s .35s ease-out both; z-index:6; }
.siege-drop { animation:siege-drop .65s .42s cubic-bezier(.3,.4,.6,1.3) both; z-index:7; }
.siege-overturned { transform:rotate(-20deg); }
.siege-letter-glint { z-index:7; filter:drop-shadow(0 0 10px #fdb951); animation:siege-letter-glint 1s .85s ease-out both; }
.siege-caption { position:absolute; z-index:10; left:4%; right:4%; bottom:5%; max-width:max-content; margin:0; padding:8px 13px; background:#f0dbb7; color:#2a1d24; font-family:Georgia,serif; font-weight:700; border:2px solid #281e27; border-radius:3px; font-size:clamp(12px,2.1vw,21px); box-shadow:4px 4px #0b0a1299; }
.siege-letter {
 position:absolute; inset:5% max(8%,(100% - 690px)/2); z-index:10; display:grid; place-items:center; padding:clamp(8px,2vw,24px);
 color:var(--siege-ink); background:radial-gradient(ellipse at 35% 44%,#faebcb,var(--siege-paper) 60%,#c69c67);
 box-shadow:0 12px 46px #140c13c7,inset 0 0 25px #9d673e77; border:1px solid #a97e53; transform:rotate(-1.2deg);
 animation:siege-letter-in .8s cubic-bezier(.22,1,.36,1) both;
}
.siege-letter>div { display:flex; flex-direction:column; align-items:center; justify-content:center; text-align:center; gap:clamp(4px,1vw,13px); width:100%; height:100%; border:3px double #94673c99; padding:clamp(6px,2vw,24px); }
.siege-letter-ornament { line-height:1; font-size:clamp(12px,2.2vw,26px); color:#96693c; letter-spacing:.18em; }
.siege-letter h2,.siege-letter footer { font-family:"Journey Quill",Georgia,serif; font-weight:400; line-height:1.05; margin:0; }
.siege-letter h2 { font-size:clamp(35px,7vw,85px); color:#543224; }
.siege-letter p { margin:0; font:italic clamp(12px,2.3vw,22px)/1.25 Georgia,serif; }
.siege-letter footer { display:flex; align-items:center; gap:8px; font-size:clamp(18px,3.2vw,43px); }
.siege-wax { display:grid; place-items:center; width:1.35em; height:1.35em; border-radius:46%; background:radial-gradient(circle at 38% 28%,#b84f49,#691829); color:#efab80; box-shadow:1px 3px 4px #723d4270; font-size:.75em; transform:rotate(15deg); font-family:Georgia,serif; }
.siege-run { animation:siege-run 2.15s linear both; z-index:6; }
.siege-chase { animation:siege-run 2.15s .12s linear both; }
.siege-window-rush { transform-origin:86% 43%; animation:siege-window 2.15s ease-in-out both; }
.siege-jump { animation:siege-jump 2s ease-out both; z-index:8; }
.siege-freeze { background:radial-gradient(ellipse at 75% 24%,#91809b,#4e3c65 33%,#25213e 79%); }
.siege-freeze .siege-actor { z-index:6; }
.siege-freeze-tower { position:absolute; inset:0; filter:brightness(.71) sepia(.12); z-index:3; }
.siege-moon { position:absolute; inset:8% 9% auto auto; border-radius:9%; width:11%; aspect-ratio:1; background:#f6dfbf; box-shadow:0 0 60px #f9cec6; z-index:1; }
.siege-moat { position:absolute; z-index:4; bottom:0; width:100%; height:14%; background:linear-gradient(#49617b,#132b42); clip-path:polygon(0 28%,27% 24%,42% 37%,58% 30%,83% 8%,100% 26%,100% 100%,0 100%); }
.siege-speedlines { position:absolute; z-index:2; inset:8% 0 14%; background:repeating-linear-gradient(-7deg,transparent 0 13px,#f8ddf539 14px 16px,transparent 17px 27px); clip-path:polygon(17% 20%,52% 12%,30% 36%,91% 13%,49% 69%,80% 78%,47% 80%,20% 97%,30% 63%,0 55%); }
.siege-freeze .freeze-steve { transform:rotate(23deg); }
.siege-freeze .freeze-alex { transform:rotate(34deg); }
.siege-comic-footer { display:flex; justify-content:space-between; align-items:center; gap:10px; padding:10px 2px 0; }
.siege-frame-dots { display:flex; gap:5px; padding-left:4px; }
.siege-frame-dots i { width:7px; height:7px; border:1px solid #d4b9a0; border-radius:50%; }
.siege-frame-dots .active { background:#f6d99a; box-shadow:0 0 10px #f6d99a55; }
.siege-summary { text-align:center; border:1px solid var(--siege-line); border-radius:18px; background:radial-gradient(ellipse at 50% 0%,#584267,#202230 65%); padding:clamp(20px,5vw,50px); }
.siege-summary h2 { margin:6px 0; color:var(--siege-gold); font-size:clamp(25px,5vw,42px); }
.siege-summary dl { display:flex; justify-content:center; gap:clamp(12px,5vw,42px); margin:28px 0; }
.siege-summary dl div { display:flex; flex-direction:column-reverse; gap:5px; }
.siege-summary dd { margin:0; font-weight:800; font-size:25px; }
.siege-summary dt { color:#ddd3e6; font-size:12px; }
.siege-summary button { margin:4px; }

@keyframes siege-pan { from { transform:scale(1.04) translateX(-1%); } to { transform:scale(1.14) translateX(1%); } }
@keyframes siege-room { from { transform:scale(1.28); } to { transform:scale(1.78); } }
@keyframes siege-walk-in { 0% { translate:-120% 0; } 25% { translate:-80% -2%; } 50% { translate:-40% 0; } 75% { translate:0 -2%; } 100% { translate:40% 0; } }
@keyframes siege-startled { 35% { transform:translate(-12%,-8%) rotate(-7deg); } 80% { transform:translate(0,1%) rotate(2deg); } }
@keyframes siege-drop { from { transform:translate(-36%,-80%) rotate(-36deg); } to { transform:translate(12%,0) rotate(30deg); } }
@keyframes siege-letter-glint { from { opacity:.35; } to { opacity:1; } }
@keyframes siege-letter-in { from { opacity:0; transform:translateY(15%) scale(.66) rotate(-7deg); } }
@keyframes siege-run { from { translate:-40% 0; } to { translate:32% -4%; } }
@keyframes siege-window { from { transform:scale(1.15); } to { transform:scale(1.75); } }
@keyframes siege-jump { from { translate:-30% 15%; } 70% { translate:34% -14%; } to { translate:115% 8%; } }
@keyframes siege-flash { from { opacity:1; transform:scale(.88); } to { opacity:.22; transform:scale(1.18); } }
@keyframes siege-arrow { from { opacity:1; transform:translate(-6%,10%) rotate(-21deg); } to { opacity:0; transform:translate(78%,-45%) rotate(-21deg); } }

@media (max-width:760px) {
 .siege-layout { grid-template-columns:1fr; gap:10px; }
 .siege-play { padding:10px; }
 .siege-status { flex-wrap:wrap; }
 .siege-status p { font-size:12px; }
 .siege-pack { padding:10px; }
 .siege-pack .journey-inventory { grid-template-columns:repeat(6,minmax(0,1fr)); }
 .siege-bench { grid-template-columns:1fr minmax(112px,auto); align-items:center; }
 .siege-bench h3 { grid-column:1/-1; }
 .siege-storyboard { padding:7px; }
 .siege-comic-art { aspect-ratio:1.42; }
 .siege-letter { inset:5% 6%; }
}
@media (prefers-reduced-motion:reduce) {
 .siege-page *,.siege-page *::after { animation-duration:0s!important; transition-duration:0s!important; }
}

.siege-plaque {
 position:absolute; top:15%; left:50%; z-index:3; transform:translateX(-50%);
 border:1px solid #d1a87390; border-radius:4px; padding:4px 10px; white-space:nowrap;
 color:#ffdf9a; background:#212133eb; font:bold clamp(10px,1.85vw,24px)/1.2 Georgia,serif;
 box-shadow:2px 3px #13131355; pointer-events:none;
}
.siege-plaque i { color:#b09683; font-style:normal; padding:0 .14em; }

.siege-reduced *,.siege-reduced *::after { animation-duration:0s!important; transition-duration:0s!important; }

.siege-freeze-window { position:absolute; background:radial-gradient(ellipse at 25% 82%,#7b463f,#272436 76%); border:clamp(3px,.7vw,9px) solid #3e3236; border-right:0; box-shadow:inset 0 8px 18px #0d101cba,0 3px 13px #16162580; }
.siege-shards { position:absolute; inset:22% 47% 31% 33%; z-index:5; pointer-events:none; }
.siege-shards i { position:absolute; width:12%; aspect-ratio:1; background:#b5d7e0a0; clip-path:polygon(0 20%,95% 0,65% 78%,15% 100%); transform:rotate(18deg); left:24%; top:16%; }
.siege-shards i:nth-child(2) { left:68%; top:6%; width:8%; transform:rotate(-18deg); }
.siege-shards i:nth-child(3) { left:51%; top:69%; width:15%; transform:rotate(-42deg); }
.siege-shards i:nth-child(4) { left:16%; top:90%; width:7%; transform:rotate(51deg); }

.alex-comic-page .siege-storyboard { max-width:1000px; }
.alex-comic-stage,.alex-comic-backdrop,.alex-kidnap-group { position:absolute; inset:0; }
.alex-comic-backdrop { pointer-events:none; }
.alex-comic-actor { z-index:6; }
.alex-comic-actor>svg { position:absolute; inset:0; width:100%; height:100%; }
.alex-comic-reunion .alex-shot-0 { animation:alex-wide 2.05s ease-out both; }
.alex-comic-reunion .alex-shot-1 { transform-origin:69% 54%; animation:alex-approach 2.1s ease-out both; }
.alex-comic-reunion .alex-shot-2 { transform-origin:74% 52%; animation:alex-close 1.6s ease-out both; }
.alex-comic-reunion .alex-shot-2::after {
 content:""; position:absolute; inset:21% 9% 12% 45%;
 background:radial-gradient(ellipse, #ffcd8738,transparent 67%); z-index:4; pointer-events:none;
}
.alex-notices { animation:alex-hop .65s .42s ease-out both; }
.alex-run-steve { animation:alex-rush-steve 1.8s cubic-bezier(.28,.92,.43,1) both; }
.alex-run-alex { animation:alex-rush-alex 1.7s .08s cubic-bezier(.28,.92,.43,1) both; }
.alex-hug-steve { transform:rotate(5deg); transform-origin:50% 83%; }
.alex-hug-alex { transform:rotate(-6deg); transform-origin:50% 83%; }
.alex-comic-hearts { position:absolute; z-index:8; pointer-events:none; }
.alex-comic-hearts i {
 position:absolute; top:51%; left:var(--heart-x); font-style:normal; color:#fd87ad;
 font-size:clamp(9px,1.65vw,23px); text-shadow:0 0 12px #f873acaf;
 animation:alex-heart 2.1s var(--heart-delay) ease-out infinite;
}
.alex-comic-raid .siege-comic-art { background:linear-gradient(#3d405e,#795b68 65%,#24293a); }
.alex-comic-raid .alex-comic-backdrop { filter:brightness(.68) saturate(.7); }
.alex-comic-raid .alex-shot-0 { transform-origin:74% 52%; animation:alex-dusk 2.05s ease-out both; }
.alex-comic-raid .alex-shot-1 { transform-origin:70% 51%; animation:alex-impact 2.2s ease both; }
.alex-comic-raid .alex-shot-2 { transform-origin:84% 50%; animation:alex-chase-pan 1.8s ease-out both; }
.alex-comic-raid .alex-shot-2 .alex-comic-backdrop { filter:brightness(.52) saturate(.78); }
.alex-startled { animation:alex-hop .46s .24s ease-in-out both; }
.alex-zombie-left { --raid-delay:0ms; animation:alex-zombie-left 1.85s var(--raid-delay) ease-out both; }
.alex-zombie-delay { --raid-delay:90ms; }
.alex-zombie-right { animation:alex-zombie-right 1.65s .14s ease-out both; }
.alex-door {
 position:absolute; z-index:3; background-image:var(--door); background-size:100% 60%; image-rendering:pixelated;
 transform-origin:40% 88%; animation:alex-door 1.1s .2s ease-out both;
}
.alex-comic-bang { left:auto; right:12%; bottom:15%; transform:rotate(-9deg); font-style:italic; }
.alex-kidnap-group { z-index:7; translate:48% 0; animation:alex-abduct 1.75s .12s cubic-bezier(.43,.08,.66,.92) both; }
.alex-comic-page.siege-reduced .alex-kidnap-group { animation:none; }
.alex-captive { transform:rotate(-13deg); transform-origin:62% 73%; }
.alex-left-behind { transform-origin:50% 94%; animation:alex-regain-balance .64s ease-out both; }
.alex-escort { z-index:5; animation:alex-escort-step .28s ease-in-out 6 alternate both; }
.alex-escort:nth-child(2) { animation-delay:.12s; }
.alex-lost-trail { position:absolute; z-index:4; image-rendering:pixelated; filter:drop-shadow(0 0 5px #e7bf93); }

@keyframes alex-wide { from { transform:scale(1.01); } to { transform:scale(1.1) translateX(-1%); } }
@keyframes alex-approach { from { transform:scale(1.08); } to { transform:scale(1.28); } }
@keyframes alex-close { from { transform:scale(1.38); } to { transform:scale(2); } }
@keyframes alex-hop { 45% { transform:translateY(-12%) rotate(-5deg); } }
@keyframes alex-rush-steve { 0% { translate:-230% 0; } 37% { translate:-125% -5%; } 68% { translate:-45% -4%; } 100% { translate:0; } }
@keyframes alex-rush-alex { 0% { translate:56% 0; } 48% { translate:22% -8%; } 100% { translate:0; } }
@keyframes alex-heart { 0% { opacity:.45; transform:translateY(35%) scale(.7); } 28% { opacity:1; } 100% { opacity:.45; transform:translateY(-65%); } }
@keyframes alex-dusk { from { transform:scale(2); filter:brightness(1.4); } to { transform:scale(1.52); filter:brightness(1); } }
@keyframes alex-impact { 0% { transform:scale(1.35); } 13% { transform:scale(1.33) translate(-.9%,.8%); } 24% { transform:scale(1.31) translate(.7%,-.3%); } 100% { transform:scale(1.1); } }
@keyframes alex-zombie-left { from { translate:-340% 0; } to { translate:50% 0; } }
@keyframes alex-zombie-right { from { translate:190% 0; } to { translate:-59% 0; } }
@keyframes alex-door { 0% { transform:rotate(0); } 80%,100% { transform:rotate(-75deg) translate(-16%,30%); } }
@keyframes alex-chase-pan { from { transform:scale(1.1); } to { transform:scale(1.43) translateX(-2%); } }
@keyframes alex-abduct { from { translate:0 0; } to { translate:48% 0; } }
@keyframes alex-regain-balance { from { transform:rotate(-8deg); } to { transform:rotate(0); } }
@keyframes alex-escort-step { from { transform:translateY(0) rotate(-2deg); } to { transform:translateY(-4%) rotate(3deg); } }
@media (max-width:760px) {
 .alex-comic-page .siege-comic-art { aspect-ratio:1.36; }
 .alex-comic-reunion .alex-shot-2,.alex-comic-raid .alex-shot-0 { transform-origin:76% 52%; }
}
.alex-speedrun { margin:12px 0; padding:12px 14px; border:1px solid #bcec982b; border-radius:14px; background:#101b24; }
.alex-rank-toolbar { display:flex; align-items:center; justify-content:space-between; gap:8px 16px; flex-wrap:wrap; }
.alex-rank-toolbar strong { color:#dcfcb8; font-size:.95rem; }
.alex-rank-toolbar small { display:block; margin-top:2px; color:#b5c4bb; }
.alex-rank-toolbar time,.alex-rank-rows b { font-variant-numeric:tabular-nums; }
.alex-rank-actions,.alex-rank-tabs { display:flex; flex-wrap:wrap; gap:6px; }
.alex-rank-actions button,.alex-rank-tabs button { min-height:40px; }
.alex-rank-feedback { margin:6px 0; color:#ffe0ac; }
.alex-rank-feedback:empty { margin:0; }
.alex-rank-board { margin-top:8px; padding-top:8px; border-top:1px solid #bcec982b; }
.alex-rank-board summary { cursor:pointer; width:fit-content; color:#dcfcb8; }
.alex-rank-tabs { margin:10px 0 8px; }
.alex-rank-tabs [aria-pressed="true"] { border-color:#bcec98; color:#dcfcb8; background:#bcec981a; }
.alex-rank-rows { color:#dbe6e0; max-width:560px; }
