.alex-rank-rows li { border-bottom:1px solid #bcec982b; padding:5px 6px; min-width:0; }
.alex-rank-rows li span { overflow-wrap:anywhere; }
.alex-rank-rows li b { float:inline-end; padding-inline-start:8px; color:#dcfcb8; }
