.game-presentation>.journey-page:has(>:is(.journey-layout,.rescue-layout,.siege-layout)):not(.is-finished)>:not(.journey-heading,.journey-layout,.rescue-layout,.siege-layout),
.game-presentation>.journey-page:has(>:is(.journey-layout,.rescue-layout,.siege-layout)):not(.is-finished) .journey-heading>:first-child,
.game-presentation>.journey-page:has(>:is(.journey-layout,.rescue-layout,.siege-layout)):not(.is-finished) .game-view-tools>button:not([data-game-fullscreen]){
