 .game-presentation .journey-page:not(.is-finished) .journey-play>.minecraft-hints{bottom:calc(max(var(--journey-inset),env(safe-area-inset-bottom)) + 92px)}
}


/* source: pokemonAuctionBattle.css */
.auction-battle-panel {
  text-align:left;
  background:radial-gradient(ellipse at 50% 0,#17334a 0,transparent 54%),#131b2a;
}
.battle-heading,.battle-prep-info,.battle-footer,.battle-move-row {
  display:flex;align-items:center;justify-content:space-between;gap:10px;
}
.battle-heading h1 { margin:0; }
.battle-prep-info { margin-block:12px 4px;flex-wrap:wrap;color:#bfe9e3;font-size:13px; }
.battle-footer { margin-top:14px;flex-wrap:wrap; }
.battle-arena { display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:12px; }
.battle-team { min-width:0;border:1px solid #53648466;border-radius:14px;padding:10px;background:#111927; }
.battle-team.is-active { border-color:#75deca; }
.battle-team h2 { margin:0 0 7px;font-size:15px; }
.battle-team h2 small { color:#feb3b3;font-size:11px; }
.battle-party,.battle-prep-team { display:grid;gap:7px;grid-template-columns:repeat(auto-fill,minmax(min(100%,84px),1fr)); }
.battle-prep-team { grid-template-columns:repeat(auto-fill,minmax(min(100%,148px),1fr)); }
.battle-unit {
  min-width:0;display:grid;grid-template-columns:minmax(0,1fr);align-content:start;justify-items:center;gap:4px;
  padding:6px;border:1px solid #586784;border-radius:10px;background:#1b2940;color:#f3f7ff;text-align:center;
}
.battle-unit b { font-size:12px;overflow-wrap:anywhere; }
.battle-unit small { font-size:10px;color:#c2d1e2; }
.battle-unit[aria-pressed="true"] { outline:2px solid #84eddd;outline-offset:1px;background:#254558; }
.battle-unit.is-mega { border-color:#c6a0ff; }
.battle-unit.is-form { border-color:#efcb82; }
.battle-unit:disabled:not(.is-out) { opacity:1; }
.battle-unit.is-out { opacity:.45; }
.battle-unit[data-battle-matchup="effective"] { --matchup-color:#8beeb5; }
.battle-unit[data-battle-matchup="super"] { --matchup-color:#ffcf78; }
.battle-unit[data-battle-matchup] { border-color:var(--matchup-color);box-shadow:inset 0 0 13px color-mix(in srgb,var(--matchup-color) 23%,transparent); }
.battle-unit .battle-matchup-label { color:var(--matchup-color);font-weight:800; }
.auction-battle-panel :is(.battle-unit,.duel-moves button)[data-battle-matchup="quad"] {
  --matchup-color:#dda0ff;--matchup-glow:#ab42ff;
  border-color:var(--matchup-color);
  box-shadow:inset 0 0 15px #ab42ff40,0 0 10px #ab42ff80;
  animation:battleQuadPulse 1.25s ease-in-out infinite alternate;
}
.auction-battle-panel [data-battle-matchup="quad"] .battle-matchup-label { color:var(--matchup-color);font-weight:900; }
@keyframes battleQuadPulse {
  from { box-shadow:inset 0 0 11px color-mix(in srgb,var(--matchup-glow) 23%,transparent),0 0 4px color-mix(in srgb,var(--matchup-glow) 44%,transparent); }
  to { box-shadow:inset 0 0 20px color-mix(in srgb,var(--matchup-glow) 48%,transparent),0 0 14px color-mix(in srgb,var(--matchup-glow) 78%,transparent); }
}
.battle-unit-art { position:relative;width:62px;height:57px; }
.battle-sprite { width:100%;height:100%;position:relative;z-index:1;object-fit:contain;image-rendering:pixelated; }
.battle-evolution-old,.battle-evolution-flash { position:absolute;inset:0;pointer-events:none; }
.battle-evolution-flash { z-index:2;border-radius:50%;background:radial-gradient(circle,#f6fffad9,#69edda55 45%,transparent 70%);opacity:0; }
.battle-evolution-flash.is-mega { background:radial-gradient(circle,#fff4ffe6,#bc6bff77 48%,transparent 72%); }
.battle-evolution-flash.is-form { background:radial-gradient(circle,#fff7d8,#ffc75f99 48%,transparent 72%); }
.battle-order { display:flex;align-items:center;justify-content:flex-end;gap:3px;width:100%; }
.battle-order span { margin-right:auto;color:#beebdc;font-size:10px; }
.battle-order button { min-width:26px;min-height:28px;padding:2px 4px;font-size:12px; }
.auction-opening { display:grid;justify-items:center;gap:7px;text-align:center; }
.auction-opening h1,.auction-opening .eyebrow { margin:0; }
.auction-opening h1 { font-size:clamp(21px,4vw,34px);overflow-wrap:anywhere; }
.auction-wheel-wrap {
  position:relative;width:min(100%,370px);aspect-ratio:1;margin:14px 0 8px;
  container-type:inline-size;
}
.auction-wheel {
  position:absolute;inset:0;box-sizing:border-box;overflow:hidden;border-radius:50%;
  border:5px solid #b4c8e8;background:var(--wheel-fill);
  box-shadow:inset 0 0 0 3px #ffffff36,inset 0 0 22px #080e26ae,0 11px 26px #080d2370;
}
.auction-wheel-seat { position:absolute;left:var(--x);top:var(--y);transform:translate(-50%,-50%); }
.auction-wheel-profile {
  display:grid;justify-items:center;gap:2px;width:clamp(50px,22cqi,81px);min-height:42px;
  padding:4px;border:1px solid #e7f4ff60;border-radius:9px;background:#0b142ddc;color:#fff;
  font-size:clamp(10px,3.6cqi,13px);font-weight:800;line-height:1.12;
}
.auction-wheel-profile > span { max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap; }
.auction-wheel-profile .auction-wheel-avatar {
  width:clamp(20px,9cqi,30px);height:clamp(20px,9cqi,30px);font-size:.72rem;
}
.auction-wheel-profile[data-wheel-winner="true"] { border-color:#ffda86;background:#372b19;box-shadow:0 0 13px #ffd57c87; }
.auction-wheel-pointer {
  position:absolute;z-index:2;left:50%;top:-8px;transform:translateX(-50%);width:24px;height:28px;
  background:linear-gradient(#fff0bd,#ffad4b);clip-path:polygon(0 0,100% 0,50% 100%);
}
.auction-wheel-hub {
  position:absolute;inset:50% auto auto 50%;transform:translate(-50%,-50%);width:12%;aspect-ratio:1;
  border:2px solid #b4c8e8;border-radius:50%;display:grid;place-items:center;background:#14223e;color:#ffdc8b;
}
.auction-wheel-hub svg { width:55%;height:55%; }
.light-theme .auction-wheel { border-color:#6a7fa3;box-shadow:inset 0 0 0 3px #ffffff58,inset 0 0 18px #16103163,0 9px 20px #2e456b32; }
.battle-types { display:flex;justify-content:center;gap:3px; }
.battle-types img { width:18px;height:18px; }
.battle-hp { width:100%;height:5px;overflow:hidden;border-radius:999px;background:#0f1420; }
.battle-hp i { height:100%;display:block;background:linear-gradient(90deg,#32bd83,#a2e290);transition:width .26s ease .28s; }
.battle-hp[data-health="medium"] i { background:linear-gradient(90deg,#d78b32,#ffc864); }
.battle-hp[data-health="low"] i { background:linear-gradient(90deg,#ac354a,#ff817e); }
.battle-hp-count { font-variant-numeric:tabular-nums; }
.battle-upgrades { display:grid;width:100%;gap:4px;margin-top:4px; }
.battle-upgrades button { min-height:33px;padding:5px;font-size:11px; }
.battle-event { min-height:1.4em;margin:8px 0;color:#a8e7dc;font-size:13px; }
.pokemon-auction-settings .auction-advanced-setting { justify-content:flex-start;gap:10px; }
.auction-advanced-setting span,.battle-ability-prep { display:grid;gap:3px;min-width:0; }
.auction-advanced-setting small { color:#c2d1e2;font-size:.8em; }
.battle-ability-prep { justify-items:center;width:100%;overflow-wrap:anywhere;font-size:11px; }
.battle-ability-prep select { width:100%;min-width:0;min-height:32px;padding:4px;font-size:11px; }
.battle-ability-prep a,.battle-ability-chip,.battle-ability-events,.battle-field { color:#f9d78b; }
.battle-unit .battle-ability-chip { color:#f9d78b;overflow-wrap:anywhere; }
.battle-field { margin:6px 0;font-size:12px; }
.battle-ability-events { display:block;margin-top:4px;font-size:11px; }
.duel-loadout { text-align:left; }
.duel-loadout label { display:grid;gap:3px;width:100%;min-width:0;color:#e2eef9; }
.duel-loadout strong { color:#ffd67e; }
.duel-stage {
  position:relative;isolation:isolate;display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,130px),1fr));
  gap:10px;padding:12px;margin:10px 0;border:1px solid #526486;border-radius:15px;
  --stage-light:#5489ba;--stage-wash:#203d5b;
  background:radial-gradient(ellipse at 50% 0,color-mix(in srgb,var(--stage-light) 48%,transparent),transparent 68%),
    linear-gradient(10deg,#101929 5%,var(--stage-wash) 49%,#16233e);
}
.duel-stage::before {
  content:"";position:absolute;inset:0;border-radius:inherit;z-index:-1;pointer-events:none;
  background:radial-gradient(ellipse at 50% 65%,transparent 56%,#0a10276e),
    repeating-linear-gradient(119deg,transparent 0 21px,#c0daf30d 22px 23px,transparent 24px 39px);
}
.duel-stage:is([data-weather="sun"],[data-weather="harshSun"]) { --stage-light:#e89a59;--stage-wash:#50313f; }
.duel-stage:is([data-weather="rain"],[data-weather="heavyRain"]) { --stage-light:#518bc7;--stage-wash:#182950; }
.duel-stage:is([data-weather="rain"],[data-weather="heavyRain"])::before {
  background:repeating-linear-gradient(113deg,transparent 0 20px,#a7dcf321 21px 22px,transparent 23px 39px);
}
.duel-stage[data-weather="sand"] { --stage-light:#caa16e;--stage-wash:#4b3b3a; }
.duel-stage[data-weather="snow"] { --stage-light:#a0e3ff;--stage-wash:#293d60; }
.duel-stage .duel-active {
  position:relative;gap:5px;z-index:1;padding:8px;overflow:visible;
  border:1px solid color-mix(in srgb,var(--accent) 42%,#26344e);
  background:radial-gradient(ellipse at 50% 47%,color-mix(in srgb,var(--accent) 17%,transparent),transparent 65%),#111c30b8;
  box-shadow:inset 0 1px #ffffff16,0 5px 12px #070f2028;
}
.duel-active .battle-unit-art {
  width:clamp(66px,14vw,112px);height:clamp(60px,12vw,98px);display:grid;place-items:center;
}
.duel-active .battle-unit-art::before {
  content:"";position:absolute;width:93%;height:23%;left:3.5%;bottom:2px;border-radius:50%;pointer-events:none;
  border:1px solid color-mix(in srgb,var(--accent) 48%,transparent);
  background:radial-gradient(ellipse,color-mix(in srgb,var(--accent) 26%,transparent),transparent 70%);
}
.duel-active .battle-sprite { filter:drop-shadow(0 4px 7px #071122a8); }
.duel-active b { font-size:clamp(14px,2.2vw,17px); }
.duel-active .battle-hp { width:min(100%,170px);height:7px; }
.duel-active .battle-hp i { transition-delay:0s; }
.duel-speed,.duel-item-chip { display:inline-flex;align-items:center;justify-content:center;gap:4px;min-width:0; }
.duel-speed { min-height:20px;padding:2px 6px;border-radius:7px;background:#263550;color:#d8e9fc;font-variant-numeric:tabular-nums; }
.duel-speed[data-fastest="true"] { background:#225446;color:#a1f8cd; }
.duel-speed b { font-size:inherit; }
.duel-stage .duel-active[data-duel-acting="true"] { outline:2px solid var(--accent);outline-offset:-2px; }
.duel-item-sprite { width:22px;height:22px;flex:0 0 22px;object-fit:contain;image-rendering:pixelated; }
.duel-loadout .duel-item-chip { justify-content:flex-start;min-height:22px; }
.duel-bench .duel-item-chip { padding:1px; }
.duel-bench .duel-item-chip span { display:none; }
.duel-bench .duel-item-sprite { width:18px;height:18px;flex-basis:18px; }
.duel-active .duel-slot {
  max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;
  border-radius:999px;background:#10182b9e;padding:3px 8px;color:var(--accent);font-weight:800;
}
.duel-benches { display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,212px),1fr));gap:7px; }
.duel-bench { min-width:0;padding:7px;border-radius:10px;border:1px solid #63759846;background:#111b2c; }
.duel-bench h2 { margin:0 0 5px;font-size:11px;color:#c7daec; }
.duel-bench .battle-party { grid-template-columns:repeat(auto-fill,minmax(min(100%,58px),1fr));gap:5px; }
.duel-bench .battle-unit { padding:3px;gap:2px; }
.duel-bench .battle-unit-art { width:36px;height:32px; }
.duel-bench .battle-types img { width:13px;height:13px; }
.duel-bench .battle-unit b,.duel-bench .battle-unit small { font-size:9px; }
.duel-bench .battle-unit:not(:disabled):hover { border-color:#84eddd;background:#274154; }
.duel-controls { display:grid;gap:10px;margin:12px 0; }
.duel-controls label { font-size:.82rem; }
.duel-controls > button { justify-self:start; }
.duel-moves { display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:7px; }
.duel-moves button {
  display:grid;align-content:center;gap:3px;min-width:0;text-align:left;overflow-wrap:anywhere;
  border-inline-start:3px solid color-mix(in srgb,var(--accent) 70%,#18233b);
}
.duel-moves strong { display:flex;align-items:center;gap:6px; }
.duel-move-kind { display:inline-flex;flex:0 0 auto;padding:2px;border-radius:4px;background:#e9f4ff1c;color:#d9ebff; }
.duel-move-type { width:17px;height:17px;flex:0 0 17px;object-fit:contain; }
.duel-moves button[aria-pressed="true"] { outline:2px solid #84eddd;background:#254558; }
.duel-moves small { color:#c7dbef;font-size:.72rem; }
.duel-events { max-height:155px;overflow:auto;margin:12px 0;padding:9px 9px 9px 30px;border:1px solid #7387a649;border-radius:10px;font-size:.8rem;color:#c8deeb; }
.duel-events li + li { margin-top:5px; }
.duel-events .duel-move-type { width:14px;height:14px;margin-inline-end:5px;vertical-align:middle; }
.duel-events small { display:block;color:#f9d78b; }
.battle-move-row { margin-top:12px;flex-wrap:wrap; }
.battle-move-row p { margin:0;font-size:12px; }
.battle-move-row>div { display:flex;flex-wrap:wrap;gap:7px; }
.battle-move-row button { display:grid;gap:3px;text-align:left;min-height:48px; }
.battle-move-row small { font-size:10px;opacity:.88; }
.battle-surrender { justify-self:end;color:#feb3b3;font-size:12px; }
.battle-fx { position:fixed;z-index:1200;pointer-events:none;margin:0;color:var(--fx-accent); }
.battle-fx-ring,.battle-fx-shield {
  width:42px;height:42px;margin:-21px 0 0 -21px;border:2px solid currentColor;border-radius:50%;
  box-shadow:0 0 13px currentColor,inset 0 0 8px currentColor;
}
.battle-fx-shield { border-radius:33%;background:radial-gradient(transparent 25%,#a8e9ff42); }
.battle-fx-orb,.battle-fx-spark { border-radius:50%;background:currentColor;box-shadow:0 0 11px currentColor; }
.battle-fx-orb { width:13px;height:13px;margin:-6px 0 0 -6px; }
.battle-fx-spark { width:5px;height:5px;margin:-2px 0 0 -2px; }
.battle-fx-label {
  translate:-50% -50%;border-radius:999px;background:#0d152ceb;padding:3px 9px;
  box-shadow:0 2px 7px #06081891;font-weight:900;font-size:13px;white-space:nowrap;
}

/* Light theme for the auction, preparation, battle and results. */
.light-theme .auction-header .pokemon-timer,
.light-theme .auction-battle-panel .pokemon-timer { color:#0f766e; }
.light-theme .auction-spotlight {
  border-color:#97cec6;
  background:radial-gradient(ellipse at 50% 30%,#bdece3,#f2faf9 76%);
  color:#132f37;
}
.light-theme .auction-spotlight .pokemon-card :is(b,strong) { color:#16353b; }
.light-theme .auction-spotlight .pokemon-card img { filter:drop-shadow(0 12px 12px #25514a42); }
.light-theme .auction-note,.light-theme .auction-spotlight .pokemon-card small { color:#45586d; }
.light-theme .auction-wallet,.light-theme .auction-outcome.is-mine {
  border-color:#d4b675;background:linear-gradient(120deg,#ffefc5,#fff9ea);
  color:#50350c;
}
.light-theme .auction-wallet strong,
.light-theme .auction-outcome.is-mine :is(small,span),
.light-theme .auction-ranking-row.is-winner strong { color:#754b08; }
.light-theme .auction-price,.light-theme .auction-outcome {
  border-color:#b0c1d7;background:#edf3fb;color:#22334e;
}
.light-theme .auction-price strong,.light-theme .auction-outcome span { color:#0f645c; }
.light-theme .auction-price.is-leading { background:#e6f8ef;border-color:#78b899; }
.light-theme .auction-price.auction-outbid { background:#fff0e9;border-color:#d6a791;color:#612f23; }
.light-theme .auction-price.auction-outbid strong { color:#8b3d21; }
.light-theme .auction-outcome small { color:#5e398e; }
.light-theme .auction-roster,.light-theme .auction-opponent { background:#f7f9fe; }
.light-theme .auction-slot { background:#e7eff9;color:#21334f; }
.light-theme .auction-slot small { color:#0f635a; }
.light-theme .auction-slot.is-empty { background:#f9fbff;border-color:#9baac0;color:#556780; }
.light-theme .route-game .auction-final { background-image:radial-gradient(ellipse at 50% 0,#ece2fa,transparent 66%) !important; }
.light-theme .auction-ranking-row { background:#f1f5fb;border-color:#b6c4d7;color:#20334e; }
.light-theme .auction-ranking-row.is-winner { background:#fff8e6;border-color:#c5a15c; }

.light-theme .route-game .auction-battle-panel {
  background-image:radial-gradient(ellipse at 50% 0,#e3f1fc 0,transparent 58%) !important;
}
.light-theme .auction-advanced-setting small { color:#465971; }
.light-theme .battle-prep-info,.light-theme .battle-event,
.light-theme .battle-order span { color:#235c53; }
.light-theme .battle-team,.light-theme .duel-bench {
  border-color:#bdcbdc;background:#f5f8fd;
}
.light-theme .battle-team.is-active { border-color:#448e82; }
.light-theme .auction-battle-panel .battle-unit { border-color:#b2c2d7;background:#edf3fa;color:#20344f; }
.light-theme .auction-battle-panel .battle-unit[aria-pressed="true"] {
  outline-color:#147e72;border-color:#438e81;background:#dff3ee;
}
.light-theme .auction-battle-panel .battle-unit.is-mega { border-color:#9979c8; }
.light-theme .auction-battle-panel .battle-unit.is-form { border-color:#b69a59; }
.light-theme .auction-battle-panel .battle-unit.is-out { background:#f4f5f8;opacity:1; }
.light-theme .battle-unit.is-out .battle-sprite { filter:grayscale(1);opacity:.48; }
.light-theme .battle-unit small,.light-theme .duel-bench h2,
.light-theme .duel-moves small,.light-theme .duel-loadout label { color:#405570; }
.light-theme .battle-unit .battle-ability-chip,.light-theme .battle-ability-events,
.light-theme .battle-field,.light-theme .duel-events small,.light-theme .duel-loadout strong { color:#785008; }
.light-theme .battle-ability-prep a { color:#593391; }
.light-theme .battle-hp { background:#c6d4e4; }
.light-theme .battle-types img,.light-theme .duel-move-type { filter:brightness(0);opacity:.76; }
.light-theme .battle-unit[data-battle-matchup="effective"] { --matchup-color:#1a7350; }
.light-theme .battle-unit[data-battle-matchup="super"] { --matchup-color:#8b4a0b; }
.light-theme .auction-battle-panel .battle-unit[data-battle-matchup] { border-color:var(--matchup-color); }
.light-theme .auction-battle-panel :is(.battle-unit,.duel-moves button)[data-battle-matchup="quad"] {
  --matchup-color:#7021bf;--matchup-glow:#962af3;
  border-color:var(--matchup-color);
}
.light-theme .auction-battle-panel .battle-surrender,.light-theme .battle-team h2 small { color:#993342; }
.light-theme .duel-stage {
  --stage-light:#73b1dd;--stage-wash:#dbeafa;
  border-color:#9cb6d2;
  background:radial-gradient(ellipse at 50% 0,color-mix(in srgb,var(--stage-light) 38%,transparent),transparent 74%),
    linear-gradient(10deg,#f0f6fc 4%,var(--stage-wash) 52%,#f5f8fd);
}
.light-theme .duel-stage::before {
  background:repeating-linear-gradient(119deg,transparent 0 21px,#334c6815 22px 23px,transparent 24px 39px);
}
.light-theme .duel-stage:is([data-weather="sun"],[data-weather="harshSun"]) { --stage-light:#f2bb60;--stage-wash:#fff0d6; }
.light-theme .duel-stage:is([data-weather="rain"],[data-weather="heavyRain"]) { --stage-light:#72a5dc;--stage-wash:#dce8fa; }
.light-theme .duel-stage[data-weather="sand"] { --stage-light:#dfb977;--stage-wash:#f6e9d7; }
.light-theme .duel-stage[data-weather="snow"] { --stage-light:#8dd7f0;--stage-wash:#e7f4fb; }
.light-theme .auction-battle-panel .duel-stage .duel-active {
  border-color:color-mix(in srgb,var(--accent) 28%,#8497b2);
  background:radial-gradient(ellipse at 50% 47%,color-mix(in srgb,var(--accent) 26%,transparent),transparent 70%),#fffffff0;
  box-shadow:0 4px 12px #23436b15;
}
.light-theme .duel-active .duel-slot { color:#20364f;background:color-mix(in srgb,var(--accent) 30%,#f1f6fb); }
.light-theme .duel-active .duel-speed { background:#e4edf9;color:#2a476e; }
.light-theme .duel-active .duel-speed[data-fastest="true"] { background:#d5f5e1;color:#135e39; }
.light-theme .duel-move-kind { background:#dfeafa;color:#25456c; }
.light-theme .duel-active .battle-sprite { filter:drop-shadow(0 4px 6px #263c5c42); }
.light-theme .duel-active.is-out .battle-sprite { filter:grayscale(1); }
.light-theme .duel-bench .battle-unit:not(:disabled):hover { background:#dff1ed;border-color:#438e81; }
.light-theme .auction-battle-panel .duel-moves button[aria-pressed="true"] { background:#daf2ec;outline-color:#147e72; }
.light-theme .duel-events { border-color:#b5c6da;background:#f5f8fd;color:#233953; }

@media(max-width:620px) {
  .battle-team { padding:7px; }
  .battle-party { grid-template-columns:repeat(auto-fill,minmax(min(100%,70px),1fr)); }
  .battle-unit-art { width:48px;height:44px; }
  .battle-move-row { position:sticky;bottom:0;z-index:3;padding:8px;background:#131b2a;border:1px solid #53648466;border-radius:10px; }
  .battle-move-row>div { width:100%; }
  .battle-move-row button { flex:1; }
  .duel-moves button { padding:7px; }
  .duel-controls > button { width:100%; }
  #auction-fight:has(.duel-stage) { gap:9px; }
  .duel-stage { grid-template-columns:repeat(2,minmax(0,1fr));gap:6px;padding:7px;margin:4px 0; }
  .duel-stage .duel-active { padding:5px; }
  .duel-benches { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .duel-controls { margin:3px 0; }
  .light-theme .battle-move-row { background:#f5f8fd;border-color:#bdcbdc; }
}
@media(prefers-reduced-motion:reduce) {
  .battle-hp i { transition:none; }
  .auction-battle-panel :is(.battle-unit,.duel-moves button)[data-battle-matchup="quad"] { animation:none; }
}
.auction-spotlight [data-auction-sprite]:not([data-auction-sprite-ready]) { visibility:hidden; }
.auction-shiny-art { position:relative; display:grid; }
.auction-shiny-stars { position:absolute; inset:0; pointer-events:none; }
.auction-shiny-stars i {
  position:absolute;
  inset-inline-start:var(--x);
  top:var(--y);
  width:clamp(9px,2vw,15px);
  aspect-ratio:1;
  opacity:0;
  filter:drop-shadow(0 0 5px #ffc963);
  animation:auctionShinyTwinkle 670ms var(--delay) ease-out both;
}
.auction-shiny-stars i::before {
  content:"";
  display:block;
  width:100%;
  height:100%;
  background:linear-gradient(140deg,#fffdf1 28%,#ffcf65 65%,#f09c35);
  clip-path:polygon(50% 0,62% 38%,100% 50%,62% 62%,50% 100%,38% 62%,0 50%,38% 38%);
}
.auction-shiny-stars i:nth-child(even) { width:clamp(7px,1.5vw,11px); }
@keyframes auctionShinyTwinkle {
  0% { opacity:0; transform:translate(-50%,-50%) scale(.25) rotate(-20deg); }
  32% { opacity:1; transform:translate(-50%,-50%) scale(1.1) rotate(8deg); }
  100% { opacity:0; transform:translate(calc(-50% + var(--dx)),calc(-50% + var(--dy))) scale(.4) rotate(32deg); }
}
@media (prefers-reduced-motion:reduce) {
  .auction-shiny-stars i { animation:none; opacity:1; transform:translate(-50%,-50%); }
}


/* source: guessPeople.css */
.gp-page {
  --gp-paper: #f8edda;
  --gp-ink: #24233a;
  --gp-edge: #b2a3f035;
  width: min(1360px, calc(100% - 24px));
  margin: 24px auto;
}
.gp-heading, .gp-toolbar, .gp-turn-top, .gp-actions {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.gp-heading { margin-bottom: 18px; }
.gp-heading .eyebrow { color: #9ce6dc; margin-bottom: 4px; }
.gp-heading h1, .gp-panel h2 { margin: 0; }
.gp-heading h1 { font-size: clamp(32px, 5vw, 58px); letter-spacing: -.045em; }
.gp-layout { display: grid; grid-template-columns: minmax(0, 1fr) 300px; gap: 16px; align-items: start; }
.gp-panel {
  background: #19182b;
  border: 1px solid var(--gp-edge);
  border-radius: 18px;
  padding: 16px;
  min-width: 0;
}
.gp-table {
  background: radial-gradient(ellipse at top left, #37405d, transparent 68%), linear-gradient(145deg,#262741,#1c2033);
  box-shadow: 0 14px 44px #07091455, inset 0 1px #ffffff12;
}
.gp-seats {
  display: grid;
  grid-template-columns: repeat(var(--seats), minmax(0,1fr));
  gap: 8px;
  padding: 0;
  margin: 0 0 14px;
  list-style: none;
}
.gp-seat {
  --seat: #8de1e6;
  display: flex;
  align-items: center;
  gap: 9px;
  min-width: 0;
  padding: 8px 10px;
  border: 1px solid #ffffff19;
  border-radius: 13px;
  background: #191a2c;
}
.gp-seat[data-seat="1"] { --seat: #f3bd93; }
.gp-seat[data-seat="2"] { --seat: #c4aff9; }
.gp-seat[data-seat="3"] { --seat: #b6e69d; }
.gp-seat.is-active { border-color: var(--seat); box-shadow: inset 0 0 24px color-mix(in srgb, var(--seat) 15%, transparent); }
.gp-seat.is-answering { border-color: #f0ca88; box-shadow: inset 0 0 24px #e9a84b22; }
.gp-seat-icon {
  display: grid;
  place-items: center;
  width: 29px;
  height: 29px;
  flex: none;
  border-radius: 9px;
  background: color-mix(in srgb, var(--seat) 15%, transparent);
  color: var(--seat);
  font-size: 12px;
  font-weight: 800;
}
.gp-seat-copy { display: grid; gap: 1px; min-width: 0; flex: 1; }
.gp-seat-copy strong { font-size: 13px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gp-seat-copy small { color: #acc8e4; font-size: 10px; }
.gp-seat-target { color: #c5c4dd; font-size: 11px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.gp-seat-status { font-size: 10px; font-weight: 700; color: var(--seat); max-width: 9ch; line-height: 1.2; }
.gp-seat.is-answering .gp-seat-status { color: #f0ca88; }
.gp-toolbar h2, .gp-side h2 { font-size: clamp(14px, 2vw, 20px); }
.gp-count, .gp-help, .gp-history p { color: #c8c5dc; font-size: 13px; }
.gp-count { margin-top: 5px; }
.gp-candidates, .gp-timer-meter { overflow: hidden; border-radius: 12px; background: #0d102a; height: 4px; }
.gp-candidates { width: min(150px, 100%); margin-top: 5px; }
.gp-timer-meter { margin: 9px 0 0; }
.gp-candidates i, .gp-timer-meter i { display: block; height: 100%; transform-origin: left; border-radius: inherit; background: linear-gradient(90deg,#63d8dc,#b3adff); }
.gp-candidates i { transition: transform .26s ease; }
.gp-timer-meter i { transition: transform .26s linear; }
.gp-time-low .gp-timer-meter i { background: #ff917e; }
.gp-time-low [data-board-timer] { color: #ffb1a1; }
.gp-toggle { display: flex; align-items: center; gap: 7px; font-size: 13px; font-weight: 700; }
.gp-toggle input { width: 18px; height: 18px; accent-color: #d5bdff; flex: none; }
.gp-grid { display: grid; grid-template-columns: repeat(6, minmax(0, 1fr)); gap: 8px; }
.gp-grid-large { grid-template-columns: repeat(8, minmax(0, 1fr)); }
.gp-card { position: relative; min-width: 0; perspective: 600px; }
.gp-face {
  position: relative;
  width: 100%;
  height: 100%;
  padding: 0;
  display: grid;
  color: var(--gp-ink);
  background: transparent;
  border: 0;
  border-radius: 9px;
  box-shadow: none;
  cursor: pointer;
  transform-style: preserve-3d;
  transition: transform .34s cubic-bezier(.24,.72,.27,1);
}
.gp-face:focus-visible, .gp-zoom:focus-visible, .gp-info:focus-visible { outline: 2px solid #b5f5ea; outline-offset: 2px; }
@media (hover:hover) {
  .gp-card:hover { z-index: 1; }
  .gp-face:hover { transform: translateY(-3px); }
  .gp-face.gp-flipped:hover { transform: translateY(-2px) rotateX(180deg); }
  .gp-card-front:hover { border-color: #fff6e9; }
}
.gp-card-front, .gp-card-back { grid-area: 1 / 1; border-radius: 9px; backface-visibility: hidden; }
.gp-card-front, .gp-card-back {
  display: flex;
  flex-direction: column;
  min-width: 0;
  overflow: hidden;
  border: 3px solid var(--gp-paper);
  background: var(--gp-paper);
  gap: 3px;
  box-shadow: 0 3px 0 #afa38f;
}
.gp-face img {
  width: 100%;
  aspect-ratio: 1.06;
  object-fit: contain;
  background: #363347;
  border-radius: 6px;
}
.gp-face strong { font-size: clamp(10px, 1.2vw, 15px); line-height: 1.16; overflow-wrap: anywhere; }
.gp-face small { font-size: 10px; color: #514861; margin: auto 0 1px; line-height: 1.1; }
.gp-card-back {
  transform: rotateX(180deg);
  background: #777681;
  border-color: #777681;
  color: #fff;
  box-shadow: 0 3px 0 #565561;
}
.gp-card-back img { filter: grayscale(1) brightness(.68); }
.gp-card-back small { color: #fff; }
.gp-face.gp-flipped { transform: rotateX(180deg); }
.gp-card:has(.gp-flipped) .gp-zoom { display: none; }
.gp-guessing .gp-face:not(.gp-flipped) { outline: 2px solid #ffe090; }
.gp-zoom, .gp-info {
  position: absolute;
  top: 4px;
  right: 4px;
  min-width: 25px;
  min-height: 25px;
  padding: 1px 4px;
  border-radius: 5px;
  background: #171426e8;
  color: #fff;
  font-size: 14px;
  border: 1px solid #fff5;
}
.gp-info {
  left: 4px;
  right: auto;
  border-radius: 50%;
  width: 25px;
  font: 700 14px/1 Georgia, serif;
  z-index: 2;
}
.gp-reveal article { position: relative; }
.gp-secret-card { display: flex; align-items: center; gap: 5px; flex-wrap: wrap; }
.gp-secret .gp-info { position: static; display: grid; place-items: center; padding: 0; }
.gp-side { display: grid; gap: 12px; }
.gp-turn-top strong { color: #ffe09a; font-variant-numeric: tabular-nums; }
.gp-turn-mine { border-color: #81dbd78a; box-shadow: inset 0 1px #81dbd729; }
.gp-turn .gp-question-pair { color: #a1dedc; margin: 10px 0 0; font-size: 12px; font-weight: 700; overflow-wrap: anywhere; }
.gp-event { margin-top: 10px; padding: 8px 10px; background: #30304d; border-radius: 9px; font-size: 12px; line-height: 1.5; overflow-wrap: anywhere; }
.gp-event-pair { color: #b8b9d5; font-size: 11px; margin-bottom: 3px; }
.gp-answer-chip { display: inline-block; padding: 1px 6px; border-radius: 5px; color: #ffe4b0; background: #5b473b; white-space: nowrap; }
.gp-answer-chip[data-answer="Tak"], [data-gp-answer="Tak"] { color: #aeefbf; }
.gp-answer-chip[data-answer="Nie"], [data-gp-answer="Nie"] { color: #ffb8b7; }
.gp-answer-chip[data-answer="Tak"] { background: #285241; }
.gp-answer-chip[data-answer="Nie"] { background: #623e4e; }
.gp-turn form { display: grid; gap: 9px; margin-top: 12px; }
.gp-turn textarea { width: 100%; min-height: 72px; resize: vertical; box-sizing: border-box; font-size: 16px; }
.gp-prompts, .gp-actions { display: flex; flex-wrap: wrap; justify-content: flex-start; gap: 6px; }
.gp-prompts button { padding: 6px 8px; min-height: 30px; font-size: 11px; line-height: 1.2; }
.gp-turn blockquote { margin: 12px 0; padding: 9px 12px; border-left: 3px solid #cbb1ff; overflow-wrap: anywhere; }
.gp-secret button { margin-top: 9px; display: flex; align-items: center; gap: 10px; text-align: left; }
.gp-secret img { width: 58px; height: 65px; object-fit: contain; background: #353148; border-radius: 6px; }
.gp-history { max-height: 280px; overflow: auto; }
.gp-history summary { cursor: pointer; font-weight: 700; }
.gp-history p { overflow-wrap: anywhere; }
.gp-history strong { color: #f3d799; }
.gp-dialog {
  color: #fcf6e9;
  background: #211c32;
  border: 1px solid #b4a3e4;
  border-radius: 18px;
  width: min(440px, calc(100% - 28px));
  max-height: calc(100dvh - 24px);
  text-align: center;
  overflow: auto;
}
.gp-dialog::backdrop { background: #080715c9; }
.gp-dialog[open], .gp-arrive { animation: gp-arrive .27s ease-out both; }
.gp-deal > article { animation: gp-deal .36s cubic-bezier(.22,.76,.27,1) both; animation-delay: calc(min(var(--i),16) * 18ms); }
@keyframes gp-arrive { from { opacity: .45; transform: translateY(6px); } to { opacity: 1; transform: none; } }
@keyframes gp-deal { from { opacity: .12; transform: translateY(12px) rotate(-2deg) scale(.95); } to { opacity: 1; transform: none; } }
.gp-dialog form { text-align: right; }
.gp-dialog img { display: block; width: 100%; max-height: 55dvh; object-fit: contain; margin-top: 9px; }
.gp-dialog p { font-size: 12px; }
.gp-dialog a { color: #e0caff; }
.gp-dialog-info .gp-bio { display: grid; grid-template-columns: 70px minmax(0, 1fr); gap: 13px; align-items: start; text-align: left; margin-top: 9px; }
.gp-dialog-info .gp-bio img { width: 70px; height: 90px; margin: 0; border-radius: 6px; background: #302a44; }
.gp-dialog-info .gp-bio h2 { margin: 0; font-size: 19px; }
.gp-dialog-info .gp-bio p { margin: 5px 0 0; font-size: 15px; line-height: 1.5; color: #ece4f4; }
.gp-dialog-info .gp-photo-credit { color: #c8bdd9; margin: 13px 0 0; }
.gp-result { text-align: center; }
.gp-trophy { font-size: 43px; color: #ffdf94; line-height: 1; text-shadow: 0 0 22px #f3c26570; }
.gp-reveal .gp-solved-card { outline: 2px solid #f2ce84; outline-offset: -2px; }
.gp-solved-card > b { color: #f6d38b; font-size: 12px; }
.gp-result .gp-actions { justify-content: center; margin-top: 18px; }
.gp-reveal { display: flex; flex-wrap: wrap; justify-content: center; gap: 12px; }
.gp-reveal article { display: grid; gap: 5px; width: min(165px, 43%); padding: 8px; background: #2a263c; border-radius: 10px; }
.gp-reveal img { width: 100%; height: 150px; object-fit: contain; background: #181626; border-radius: 6px; }
.gp-reveal span { color: #c8c5dc; font-size: 12px; }
.gp-reveal details { font-size: 11px; color: #d2c8ec; overflow-wrap: anywhere; }
.game-visual-board-guess-people { background: radial-gradient(circle at 25% 20%, #b28be9, transparent 65%), linear-gradient(135deg,#423065,#235969); }
@media (max-width: 900px) {
  .gp-layout { grid-template-columns: minmax(0, 1fr); }
  .gp-side { grid-row: 1; grid-template-columns: 1.4fr 1fr; align-items: start; }
  .gp-history { grid-column: 1 / -1; max-height: 140px; }
}
@media (max-width: 580px) {
  .gp-page { margin-top: 12px; }
  .gp-panel { padding: 10px; }
  .gp-grid, .gp-grid-large { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 5px; }
  .gp-face small { font-size: 8px; }
  .gp-card-front, .gp-card-back { border-width: 2px; }
  .gp-side { grid-template-columns: minmax(0, 1fr) 110px; gap: 6px; }
  .gp-secret button { display: grid; justify-items: center; padding: 5px; font-size: 11px; }
  .gp-toolbar { align-items: start; }
  .gp-toggle { font-size: 11px; }
  .gp-help { font-size: 11px; }
  .gp-seats { grid-template-columns: repeat(2, minmax(0,1fr)); gap: 5px; }
  .gp-seat { gap: 5px; padding: 5px; }
  .gp-seat-icon { width: 20px; height: 23px; border-radius: 6px; font-size: 10px; }
  .gp-seat-copy strong { font-size: 11px; }
  .gp-seat-target, .gp-seat-status { font-size: 9px; }
}
@media (prefers-reduced-motion: reduce) {
  .gp-page *, .gp-page *::before, .gp-page *::after { animation: none !important; transition: none !important; }
}


/* source: identityInfo.css */
.identity-card-word, .identity-history-word {
