/* source: homeMenu.css */
/* Keep the gradient tied to the viewport even when filtering changes page height. */
body:has(.home-menu-page,.route-three-fronts) {
  background-attachment:fixed;
  background-size:100% 100lvh;
  background-repeat:no-repeat;
}

.home-menu-page .game-discovery-tools {
  grid-template-columns:clamp(122px,19%,230px) minmax(0,1fr);
  align-items:center;
  gap:8px;
  margin:0 0 12px;
}
.home-menu-page .game-search {
  width:100%;
  min-width:0;
  min-height:40px;
  margin:0;
  padding:2px 8px;
  gap:6px;
  border-radius:12px;
}
.home-menu-page .game-search input { padding:6px 0; font-size:12px; }
.home-menu-page .game-filters {
  flex-wrap:nowrap;
  gap:5px;
  margin:0;
  padding:4px;
  border-radius:12px;
  overflow-x:auto;
  scrollbar-width:thin;
  scrollbar-color:#687a97 transparent;
}
.home-menu-page .filter-chip {
  flex:none;
  padding:6px 10px;
  min-height:32px;
  font-size:11px;
  white-space:nowrap;
}
.home-menu-page .game-filters .filter-chip:hover { transform:none; }
.home-menu-page .game-filters .filter-chip:focus-visible { outline-offset:-2px; }
.home-menu-page [data-library-layout] { grid-column:1 / -1; }
@media(min-width:721px) {
  .home-menu-page [data-library-layout] { display:none; }
}
@media(max-width:900px) {
  .home-menu-page .game-search input { font-size:16px; }
  .home-menu-page .game-search input::placeholder { font-size:12px; }
  .home-menu-page .filter-chip { min-height:36px; }
}

.home-join {
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  align-items:end;
  gap:18px;
  padding:16px 20px;
  margin-bottom:16px;
  border:1px solid var(--line);
  border-radius:18px;
  background:#111829;
}
.home-join h2 {
  display:flex;
  align-items:center;
  min-height:44px;
  margin:0;
  font-size:18px;
  line-height:1.2;
}
.home-join-form {
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr)) auto;
  align-items:end;
  gap:8px;
  min-width:0;
}
.home-join-form label {
  display:grid;
  gap:5px;
  min-width:0;
  margin:0;
  color:#dce5f6;
  font-size:13px;
  font-weight:650;
}
.home-join-form input,.home-join button {
  height:44px;
  min-height:44px;
  border-radius:11px;
}
.home-join-form input {
  width:100%;
  min-width:0;
  padding:0 11px;
  background:#0c1323;
  color:#f5f6fc;
  font-size:14px;
  font-weight:500;
}
.home-join-form input::placeholder { color:#9aabc3; }
.home-join :is(input,button):focus-visible { outline:2px solid #67e8f9; outline-offset:2px; }
.home-join button {
  display:inline-flex;
  justify-content:center;
  align-items:center;
  gap:6px;
  padding:0 12px;
  font-size:13px;
  white-space:nowrap;
}
.home-join-options {
  display:flex;
  gap:8px;
  padding-inline-start:16px;
  border-inline-start:1px solid var(--line);
}
.home-join-options .ghost { color:#dbe7fb; box-shadow:none; }
.light-theme .home-join { background:#f6f8ff; border-color:#cbd5e1; }
.light-theme .home-join-form label,.light-theme .home-join-options .ghost { color:#263752; }
.light-theme .home-join-form input { color:#16223b; background:#fff; }
.light-theme .home-join-form input::placeholder { color:#61718a; }
.light-theme .home-join :is(input,button):focus-visible { outline-color:#0369a1; }
@media(max-width:1000px) {
  .home-join { grid-template-columns:minmax(0,1fr); gap:12px; }
  .home-join h2 { min-height:0; }
  .home-join-options { padding:10px 0 0; border:0; border-top:1px solid var(--line); }
}
@media(max-width:540px) {
  .home-join { padding:14px; }
  .home-join-form { grid-template-columns:repeat(2,minmax(0,1fr)); }
  .home-join-form input { font-size:16px; }
  .home-join-form button { grid-column:1 / -1; }
  .home-join-options { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); }
  .home-join-options .ghost { white-space:normal; padding-inline:5px; line-height:1.15; }
}

@media(min-width:901px){
 .home-menu-page{display:flex;flex-direction:column;gap:24px;max-width:1320px;padding-top:28px}
 .home-join{margin-bottom:0}
 .home-menu-page>.games-section{margin:0;background:none;padding:12px 0;border:0;box-shadow:none;animation:none;scroll-margin-top:100px}.home-menu-page .section-intro h2{font-size:25px;letter-spacing:-.03em}.home-menu-page .section-intro .eyebrow{font-size:9px;color:#9b9eb8}
 .home-menu-page .games-grid{grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.home-menu-page .featured-game{grid-column:span 1}.home-menu-page .game-card{min-height:320px;border-radius:20px;background:#11182a;box-shadow:none}.home-menu-page .game-visual{height:110px}.home-menu-page .game-visual span{font-size:44px}.home-menu-page .game-card-content{padding:16px;min-height:240px}.home-menu-page .game-card h2{font-size:19px;letter-spacing:-.025em}.home-menu-page .game-card-content p{font-size:11px}.home-menu-page .game-card-footer{flex-wrap:wrap;gap:10px}.home-menu-page .players-count{font-size:10px}.home-menu-page .game-card-play-options{display:flex;gap:6px;flex-wrap:wrap}.home-menu-page .game-card-footer button{font-size:11px;min-height:40px;padding:9px 12px}
 .home-menu-page .platform-share-panel,.home-menu-page .weekly-unlock-announcement{margin:0}
}
@media(min-width:901px) and (max-width:1100px){.home-menu-page .games-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@keyframes home-rise{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:none}}
@keyframes home-spin{to{transform:rotate(360deg)}}
@keyframes home-float{50%{transform:translateY(-7px) rotate(-3deg)}}
@keyframes home-beat{50%{transform:scaleY(.3)}}
@media(max-width:900px){.home-menu-page .game-card{transition:transform .2s,border-color .2s}.home-menu-page .game-card:active{transform:scale(.985)}.home-menu-page .game-card button:active{transform:scale(.97)}.home-menu-page .game-card{animation:home-rise .35s ease both}}
@media(prefers-reduced-motion:reduce){.home-menu-page *, .home-menu-page *:before,.home-menu-page *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
.light-theme .home-menu-page .game-card{background:#f6f8ff;border-color:#d6ddec;color:#16223b}
.home-menu-page .weekly-release-highlight{border-color:#facc15}

.home-music-feature{position:relative;isolation:isolate;display:grid;grid-template-columns:1.1fr 1fr;min-height:282px;border:1px solid #b9a3ff40;border-radius:28px;overflow:hidden;background:radial-gradient(ellipse at 80% 80%,#4ab9c932,transparent 60%),linear-gradient(120deg,#27214c,#161e33);box-shadow:0 25px 65px #0002}
.home-music-feature:after{content:'';position:absolute;inset:0;z-index:-1;background:linear-gradient(125deg,transparent 40%,#fff04 41%,transparent 70%);pointer-events:none}
.home-feature-copy{padding:28px 0 28px 34px;align-self:center;position:relative;z-index:2}
.home-feature-copy h1{font-size:clamp(30px,3.5vw,48px);letter-spacing:-.05em;line-height:1.08;margin:0 0 16px}.home-feature-copy h1 span{color:#c4acff}
.home-feature-copy p{font-size:14px;line-height:1.55;color:#d0d6e9;max-width:32ch;margin:0 0 22px}
.home-feature-copy .primary{display:inline-flex;align-items:center;gap:26px;min-height:46px;padding:12px 20px;background:#bba2ff;color:#171229;border:0;box-shadow:0 6px 24px #a185ff25;font-weight:850;text-decoration:none;border-radius:13px;transition:transform .2s,background .2s}
.home-feature-copy .primary:hover{background:#d2c0ff;transform:translateY(-3px)}
.home-record-scene{position:relative;min-width:0;overflow:hidden;display:flex;align-items:center;justify-content:center}
.home-record{position:relative;width:248px;aspect-ratio:1;flex-shrink:0;border-radius:50%;background:repeating-radial-gradient(circle,#0c101b 0 3px,#222632 4px,#10131c 5px 7px);border:2px solid #ffffff18;box-shadow:0 25px 35px #0005;animation:home-spin 28s linear infinite;will-change:transform}
.home-record:before{content:'';position:absolute;inset:7px;border-radius:50%;background:conic-gradient(transparent 10%,#ffffff0e 20%,transparent 30% 60%,#ffffff0e 70%,transparent 80%)}
.home-record-label{position:absolute;inset:32%;border-radius:50%;background:linear-gradient(135deg,#b69bf4,#84e6cc);display:flex;align-items:center;justify-content:center;flex-direction:column;color:#21213c;font-size:30px;font-weight:950;letter-spacing:-.08em;box-shadow:0 0 0 10px #0c101b}
.home-record-label span{font-size:5px;letter-spacing:.12em;margin-top:5px}.home-record-label:after{content:'';position:absolute;bottom:12px;width:5px;height:5px;border-radius:50%;background:#141822}
.home-player-chip{position:absolute;bottom:24px;left:8%;right:12%;display:flex;align-items:center;gap:10px;background:#151b2ee8;border:1px solid #ffffff1a;border-radius:16px;padding:14px;box-shadow:0 10px 30px #0004;transform:rotate(-5deg);animation:home-float 7s ease-in-out infinite}
.home-player-chip>span{display:grid;place-items:center;flex-shrink:0;width:34px;height:34px;background:#b69af025;border-radius:10px;font-size:20px;color:#c6b0ff}
.home-player-chip b,.home-player-chip small{display:block}.home-player-chip b{font-size:11px}.home-player-chip small{font-size:9px;color:#909eb5;margin-top:4px}
.home-equalizer{display:flex;align-items:center;gap:3px;height:22px;margin-left:auto}.home-equalizer i{width:3px;height:18px;background:#89e8c7;border-radius:3px;animation:home-beat 1.4s ease-in-out infinite;animation-delay:calc(var(--beat)*-.17s);transform-origin:center}
.home-note{position:absolute;font-size:35px;color:#c4abff}.home-note-a{right:26px;top:30px;transform:rotate(15deg)}.home-note-b{left:16px;top:52px;color:#8ae9cd;transform:rotate(-15deg)}
.home-music-feature{margin-bottom:12px}
.home-feature-copy h1{color:#f5f6fc}
.home-feature-copy .primary:focus-visible{outline:2px solid #f5f6fc;outline-offset:3px}
@media(max-width:900px){
  .home-music-feature{min-height:208px;border-radius:22px}
  .home-feature-copy{padding:18px 0 18px 18px}
  .home-feature-copy h1{font-size:clamp(24px,4.7vw,38px);margin-bottom:10px}
  .home-feature-copy p{font-size:12px;margin-bottom:14px}
  .home-feature-copy .primary{gap:10px;padding:9px 12px;min-height:42px;font-size:12px}
  .home-record{width:clamp(106px,30vw,182px)}
  .home-record-label{font-size:clamp(14px,3vw,25px);box-shadow:0 0 0 5px #0c101b}
  .home-record-label span{margin-top:2px;font-size:4px}
  .home-record-label:after{bottom:4px;width:3px;height:3px}
  .home-player-chip{display:none}
  .home-note{font-size:22px}
  .home-note-a{right:12px;top:14px}.home-note-b{left:12px;top:auto;bottom:12px}
}
@media(max-width:360px){
  .home-music-feature{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr)}
  .home-feature-copy{padding-inline-start:12px}
}
@media(prefers-reduced-motion:reduce){.home-record{will-change:auto}}

.library-category-grid { display:grid; grid-template-columns:repeat(4,minmax(0,1fr)); gap:10px; }
.library-category-music { --library-accent:#d4adff; --library-dark:#261838; }
.library-category-tiktok { --library-accent:#77f6e5; --library-dark:#122e32; }
.library-category-minecraft { --library-accent:#b2ef8f; --library-dark:#1d3223; }
.library-category-board { --library-accent:#ffc891; --library-dark:#38281d; }
.library-category-pokemon { --library-accent:#ffe382; --library-dark:#34301b; }
.library-category-knowledge { --library-accent:#ffb1d2; --library-dark:#382039; }
.library-category-other { --library-accent:#b3cfff; --library-dark:#202945; }

.home-picks {
  display:grid; grid-template-columns:minmax(0,2fr) minmax(0,1fr); gap:14px;
  margin-bottom:12px; animation:home-rise .4s ease both;
}
.home-picks > section {
  min-width:0; padding:12px; border:1px solid #93aff626;
  border-radius:18px; background:#11192b;
}
.home-picks > .home-latest {
  border-color:#ecbf7166;
  background:linear-gradient(135deg,#edbd7418,transparent),#11192b;
}
.home-picks h2 { margin:0 0 8px; font-size:14px; color:#e5ebff; }
.home-latest h2 { color:#ffda90; }
.home-recommended-grid { display:grid; grid-template-columns:repeat(2,minmax(0,1fr)); gap:8px; }
.home-pick {
  width:100%; min-height:48px; padding:6px 9px; display:grid;
  grid-template-columns:32px minmax(0,1fr) auto; gap:8px; align-items:center;
  text-align:left; font-size:13px; font-weight:750; line-height:1.25;
  color:#f5f6fc; border:1px solid color-mix(in srgb,var(--library-accent) 34%,transparent);
  border-radius:12px; background:color-mix(in srgb,var(--library-dark) 82%,#11192b);
  transition:border-color .2s,transform .2s;
}
.home-pick:hover,.home-pick:focus-visible { border-color:var(--library-accent); }
.home-pick:active { transform:scale(.98); }
.home-pick-icon { display:grid; place-items:center; width:32px; height:32px; font-size:21px; }
.home-pick-icon img { width:100%; height:100%; object-fit:contain; image-rendering:pixelated; }
