  .home-menu-page .share-copy h2 { font-size: 1.1rem; }
  .home-menu-page .share-copy .share-actions { display: flex; gap: 6px; margin-top: 8px; }
  .home-menu-page .share-copy .share-actions button { width: auto; padding-inline: 9px; }
}

.light-theme body:has(.home-menu-page) {
  background-image: radial-gradient(ellipse at 0 0, #dfd1f3, transparent 48%),
    radial-gradient(ellipse at 100% 100%, #ccebe6, transparent 45%),
    linear-gradient(135deg, #eee8f9, #edf3fa 56%, #e3f4f0);
}
.light-theme body:has(.home-menu-page) .bg-orb { opacity: 0; }
.light-theme body:has(.home-menu-page) .topbar {
  background: #edf1f9f5;
  border-bottom-color: #c6d0e1;
  box-shadow: 0 5px 18px #4758761a;
}
.light-theme body:has(.home-menu-page) .brand svg { color: #087d76; }
.light-theme .home-music-feature {
  background: radial-gradient(ellipse at 80% 80%, #ade8e2b3, transparent 60%),
    linear-gradient(120deg, #e6d9fc, #e1edf7);
  border-color: #c3b6df;
  box-shadow: 0 16px 34px #5846821c;
}
.light-theme .home-feature-copy h1 { color: #232344; }
.light-theme .home-feature-copy h1 span { color: #573596; }
.light-theme .home-feature-copy p { color: #42455e; }
.light-theme .home-feature-copy .primary {
  background: #6846a9;
  color: #fff;
  box-shadow: 0 6px 18px #6846a934;
}
.light-theme .home-feature-copy .primary:hover { background: #55338f; }
.light-theme .home-feature-copy .primary:focus-visible { outline-color: #573596; }
.light-theme .home-record {
  background: repeating-radial-gradient(circle, #a69cc1 0 3px, #b8afd0 4px, #ada3c8 5px 7px);
  border-color: #968ab4;
  box-shadow: 0 14px 25px #41365e40;
}
.light-theme .home-record-label { box-shadow: 0 0 0 6px #9b91b7; }
.light-theme .home-note-a { color: #6744a4; }
.light-theme .home-note-b { color: #187264; }
.light-theme .home-player-chip {
  background: #f3f0fbf5;
  border-color: #baaed2;
  color: #292649;
  box-shadow: 0 8px 22px #41365e24;
}
.light-theme .home-player-chip > span { background: #e4d9f6; color: #593b91; }
.light-theme .home-player-chip small { color: #4f5670; }
.light-theme .home-equalizer i { background: #237767; }

.light-theme .home-menu-page .weekly-unlock-announcement:not(.is-live) {
  background: linear-gradient(110deg, #e9e4f8, #e6f1f6) !important;
  border-color: #c6badf !important;
  box-shadow: 0 8px 22px #47587617;
}
.light-theme .home-menu-page .weekly-unlock-announcement.is-live {
  background: linear-gradient(110deg, #f8edcf, #e3f3ed 62%, #e9e3f8) !important;
  border-color: #d9bd83 !important;
}
.light-theme .home-menu-page > .games-section {
  background: transparent !important;
  backdrop-filter: none;
  box-shadow: none;
}
.light-theme .home-menu-page .game-filters {
  background: #e2e9f5;
  border-color: #c2cde1;
  scrollbar-color: #8294b2 transparent;
}
.light-theme .home-menu-page .game-filters .filter-chip {
  background: #eff3fa;
  color: #36425a;
  border-color: #c7d1e2;
}
.light-theme .home-menu-page .game-filters .filter-chip:hover { background: #e1e7f6; }
.light-theme .home-menu-page .game-filters .filter-chip.active {
  background: #dcd0f7;
  color: #42257c;
  border-color: #997bc9;
  box-shadow: none;
}
.light-theme .home-menu-page .game-search {
  background: #edf5f8 !important;
  border-color: #adcad9 !important;
  color: #21647d;
  box-shadow: none;
}
.light-theme .home-menu-page .game-search > span:has(svg:empty) { display: none; }
.light-theme .home-menu-page .game-search:focus-within {
  border-color: #5085a3 !important;
  box-shadow: 0 0 0 2px #5085a344;
  transform: none;
}
.light-theme .home-menu-page .game-search input { box-shadow: none; }
.light-theme .home-menu-page .game-search input::placeholder { color: #526780 !important; }


/* source: fronts.css */
@font-face{font-family:Fronts Display;src:url('/assets/fronts/cinzel-decorative-latin.woff2') format('woff2');font-weight:700;font-display:swap;unicode-range:U+0000-00FF,U+2000-206F}
@font-face{font-family:Fronts Display;src:url('/assets/fronts/cinzel-decorative-latin-ext.woff2') format('woff2');font-weight:700;font-display:swap;unicode-range:U+0100-02FF,U+1E00-1EFF}
@font-face{font-family:Fronts Titles;src:url('/assets/fronts/cormorant-garamond-latin.woff2') format('woff2');font-weight:700;font-display:swap;unicode-range:U+0000-00FF,U+2000-206F}
@font-face{font-family:Fronts Titles;src:url('/assets/fronts/cormorant-garamond-latin-ext.woff2') format('woff2');font-weight:700;font-display:swap;unicode-range:U+0100-02FF,U+1E00-1EFF}
.fronts{--ink:#f8edd9;--gold:#ffcd75;--mint:#8ef0cf;--display:'Fronts Display',Georgia,serif;--titles:'Fronts Titles',Georgia,serif;color:var(--ink);padding:clamp(12px,2vw,24px) 0 24px}
.fronts :focus-visible{outline:3px solid var(--mint);outline-offset:3px}
.fronts button:disabled{cursor:default;opacity:.45}
.tf-top{display:flex;align-items:center;justify-content:space-between;gap:12px;max-width:1280px;margin:auto;padding:18px 28px;color:var(--muted);font-size:.8rem;font-weight:700}
.tf-lobby{isolation:isolate;position:relative;display:grid;align-items:center;min-height:min(690px,79svh);max-width:1224px;margin:auto;border:1px solid #9ab0946b;border-radius:30px;overflow:hidden;background:#14232d url('/assets/fronts/cover.webp') 62% 54%/cover}
.tf-lobby::before{content:"";position:absolute;z-index:-1;inset:0;background:linear-gradient(90deg,#081720f5 0%,#10222be0 24%,#0d1d2892 44%,transparent 78%)}
.tf-lobby-copy{padding:clamp(32px,6vw,93px);max-width:550px;position:relative;z-index:1}
.tf-lobby h1{margin:0;font:700 clamp(3.8rem,7.4vw,7.2rem)/.9 var(--display);letter-spacing:-.055em;text-shadow:0 5px #12252b,0 12px 28px #071119b5}
.tf-lobby h1 em{font-style:normal;color:var(--gold)}
.tf-crest{margin:0 0 19px;color:#ffdb8c;font-size:2rem;line-height:1;text-shadow:0 0 22px #ffbf69}
.tf-pitch{font-size:clamp(.94rem,2vw,1.18rem);line-height:1.45;max-width:310px;color:#d4e1da;margin:26px 0 21px}
.tf-lobby-actions{display:grid;gap:10px;max-width:360px}
.tf-filters select{min-width:0;padding:8px 12px;border:1px solid #819b8d74;background:#172729d9;border-radius:9px;color:var(--ink)}
.tf-primary,.tf-end,.tf-quiet{border:1px solid transparent;border-radius:11px;padding:10px 14px;font-weight:800;line-height:1.2}
.tf-primary,.tf-end{color:#211607;background:linear-gradient(#ffe8a6,#ffc363);border-color:#ffebae;box-shadow:0 3px 0 #986536,0 8px 25px #fba94325}
.tf-primary{display:flex;justify-content:space-between;padding:15px 18px;font-size:1.02rem}
.tf-primary:hover,.tf-end:not(:disabled):hover{background:#fff0b1}
.tf-quiet,.tf-clear{background:#172533db;border-color:#6d8b896b;color:var(--ink)}
.tf-quiet:not(:disabled):hover,.tf-clear:hover{background:#294152}
.tf-secondary{display:flex;gap:8px;flex-wrap:wrap}
.tf-secondary span{color:var(--gold);margin-left:4px}
.tf-lobby-footer{display:flex;align-items:center;gap:15px;max-width:1224px;margin:auto;padding:16px 3px;font-size:.8rem;color:var(--muted)}
.tf-lobby-footer button{margin-left:auto;background:none;border:0;color:var(--mint);padding:5px;font-weight:750}
.tf-lobby-fan{position:absolute;pointer-events:none;bottom:6%;right:5%;display:flex;align-items:flex-end}
.tf-lobby-fan .tf-card{width:clamp(70px,10vw,122px);flex:none;filter:drop-shadow(0 5px 10px #08151bb0);--tilt:-13deg;transform:rotate(var(--tilt));animation:tf-float 5s ease-in-out infinite}
.tf-lobby-fan .tf-card:nth-child(2){--tilt:2deg;z-index:1;margin:0 -15%;animation-delay:-1s;translate:0 -16px}
.tf-lobby-fan .tf-card:nth-child(3){--tilt:15deg;animation-delay:-2s}
.tf-searchbox{min-height:53px;display:flex;align-items:center;gap:10px;background:#1c302f;border:1px solid #7fbd9b;border-radius:12px;padding:8px 10px;font-size:.84rem}
.tf-searchbox button{margin-left:auto}
.tf-spinner{width:16px;height:16px;flex:none;border:2px solid #73c99755;border-top-color:var(--mint);border-radius:50%;animation:tf-spin 1s linear infinite}
.tf-error{color:#ffd0c2;font-size:.86rem;margin:0}
.tf-card{--foil:#a8b6ae;position:relative;display:flex;flex-direction:column;align-items:stretch;gap:4px;overflow:hidden;padding:5px;border:1px solid var(--foil);border-radius:10px;background:linear-gradient(145deg,#343f41,#141c27 62%);text-align:center;color:var(--ink);box-shadow:0 4px 12px #0810168c}
.tf-r1{--foil:#71e0b5}
.tf-r2{--foil:#ceb0ff;background:linear-gradient(145deg,#564466,#211b35 68%)}
.tf-r3{--foil:#ffcb6d;background:linear-gradient(145deg,#694825,#2a2530 68%)}
.tf-card-name{display:grid;place-items:center;min-height:2.25em;font:700 .91rem/1 var(--titles);text-wrap:balance;color:#fff6e2}
.tf-artwork{position:relative;isolation:isolate;display:block;width:100%;min-height:0;aspect-ratio:2/3;overflow:hidden;border-radius:5px;background:#1d2b35;border:1px solid color-mix(in srgb,var(--foil) 43%,transparent)}
.tf-artwork::before{content:"";position:absolute;z-index:-1;inset:-12px;background:var(--illustration) center/cover;filter:blur(10px) brightness(.55)}
.tf-card-image{display:block;width:100%;height:100%;object-fit:contain;object-position:center}
.tf-cost{position:absolute;top:3px;left:3px;display:grid;place-items:center;min-width:22px;height:22px;padding:2px;background:#1c2849;color:#ebf2ff;border:1px solid #afc8ff;border-radius:50%;font:800 .8rem/1 system-ui;box-shadow:0 2px 4px #090f22a8}
.tf-card-stats{display:flex;justify-content:space-around;align-items:center;color:#ffd18a;font-size:.82rem;line-height:1.2}
.tf-card-stats b+b{color:#ffa7a2}
.tf-tactic-stat{color:#d7c0fc;font-size:.71rem;font-weight:700}
.tf-card-text{font-size:.69rem;line-height:1.23;text-wrap:pretty;padding:2px;min-height:2.8em}
.tf-card-back{position:relative;display:grid;place-items:center;width:26px;height:38px;flex:none;border-radius:5px;border:1px solid #d3b47b;background:radial-gradient(circle,#374a59,#182536 75%);box-shadow:inset 0 0 0 2px #0e1722,0 2px 7px #101321}
.tf-card-back img{width:58%;border-radius:3px}
.tf-dialog{max-height:88svh;max-width:min(880px,94vw);width:max-content;color:var(--ink);background:#19252f;border:1px solid #7b8d86;border-radius:18px;padding:20px;box-shadow:0 25px 75px #000a}
.tf-dialog::backdrop{background:#02090dd4;backdrop-filter:blur(5px)}
.tf-dialog-header{display:flex;justify-content:space-between;align-items:center;gap:15px;margin-bottom:12px}
.tf-dialog-header h2,.tf-result h2{margin:0;font:700 clamp(1.35rem,3.45vw,2.2rem)/1.16 var(--display);color:var(--gold)}
.tf-dialog-header button{padding:5px 12px;font-size:1.25rem}
.tf-filters{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin:0 0 16px;font-size:.85rem}
.tf-filters label{display:flex;align-items:center;gap:5px}
.tf-filters b{margin-left:auto;color:var(--mint)}
.tf-catalog{display:grid;grid-template-columns:repeat(5,minmax(0,145px));gap:13px}
.tf-catalog-entry{display:grid;grid-template-rows:1fr auto;gap:5px;text-align:center;color:var(--muted);font-size:.68rem}
.tf-catalog-entry .tf-card-name{font-size:1.08rem}
.tf-catalog-entry .tf-card-text{font-size:.73rem}
.tf-rules{max-width:390px;margin:0 0 0 18px;padding:0 7px;line-height:1.55}
.tf-rules li+li{margin-top:8px}
.tf-wordmark{font:700 1.13rem var(--display);color:var(--ink)}
.tf-wordmark i{color:var(--gold);font-style:normal}
.tf-battle-top{padding-block:9px;max-width:1056px}
.tf-battle-top .tf-quiet{font-size:.76rem;padding:7px 10px}
.tf-arena{max-width:1100px;margin:auto;padding:0 14px 9px}
.tf-stage{position:relative;perspective:830px;perspective-origin:50% 38%;padding:0 clamp(9px,3vw,40px) 26px;margin:0 0 -6px}
.tf-stage::before{content:"";position:absolute;z-index:-1;inset:16% 4% 0;border-radius:44%;background:#000b;filter:blur(23px)}
.tf-arena-clearing{--table-angle:21deg;position:relative;isolation:isolate;border:16px solid transparent;border-radius:34px;transform:rotateX(var(--table-angle));transform-origin:50% 52%;background:
  radial-gradient(ellipse at 51% 35%,#365d50,#193c32 63%,#102a23) padding-box,
  repeating-linear-gradient(7deg,#bd926039 0 1px,#2e1a1c3a 2px 4px,transparent 6px 9px) border-box,
  linear-gradient(150deg,#aa7446,#634027 38%,#ac7645 70%,#57351f) border-box;
  box-shadow:0 0 0 1px #e8ae698a,0 5px 0 1px #603b25,0 13px 0 1px #4e2d21,0 18px 0 1px #291912,0 23px 24px #000c,inset 0 0 0 2px #e5b37399,inset 0 0 32px #061512c0}
.tf-arena-clearing::before{content:"";position:absolute;z-index:-1;inset:5px;pointer-events:none;border:1px solid #d4ab6845;border-radius:16px;background:repeating-linear-gradient(118deg,#ffffff0a 0 1px,transparent 1px 3px),repeating-linear-gradient(27deg,#0002 0 1px,transparent 1px 3px)}
.tf-arena-clearing::after{content:"";position:absolute;inset:0;pointer-events:none;border-radius:16px;box-shadow:inset 27px 0 45px -35px #ffd782bb,inset -26px 0 52px -36px #98beff88}
.tf-inlay{position:absolute;pointer-events:none;inset:0;display:grid;place-items:center;padding-right:10%;color:#e7c77a44}
.tf-inlay span{width:clamp(95px,20vw,210px);aspect-ratio:1;display:grid;place-items:center;border:4px double currentColor;border-radius:50%;outline:1px dashed currentColor;outline-offset:7px;font:800 clamp(43px,8vw,83px)/1 Georgia,serif;text-shadow:0 2px 0 #142b26}
.tf-table-cards,.tf-deck{position:relative;z-index:1}
.tf-rival,.tf-own{display:grid;align-items:center;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);gap:10px;min-height:59px;padding:6px 14px}
.tf-own .tf-castle{grid-column:2}
.fronts .tf-castle{display:flex;align-items:center;gap:9px;padding:4px 9px;border-radius:12px;justify-self:center;background:#0e2825bc;color:var(--ink);box-shadow:0 4px 10px #0003}
.fronts .tf-castle.tf-active{background:#173934;border-color:#85cea082}
.tf-castle-label{display:grid;min-width:2.5rem;line-height:1.12;max-width:14ch;text-align:left}
.tf-castle-label strong{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:.77rem}
.tf-fort{display:block;position:relative;width:29px;height:31px;flex:none;filter:drop-shadow(4px 3px 2px #0009);color:#f5cc80}
.tf-fort::before,.tf-fort::after,.tf-fort i{content:"";position:absolute}
.tf-fort::before{inset:5px 6px 3px 3px;background:linear-gradient(90deg,#b87949,currentColor 55%,#a9663d);clip-path:polygon(0 0,25% 0,25% 19%,40% 19%,40% 0,60% 0,60% 19%,76% 19%,76% 0,100% 0,100% 100%,0 100%)}
.tf-fort::after{width:7px;height:65%;right:1px;bottom:3px;background:#744c36;clip-path:polygon(0 0,100% 16%,100% 76%,0 100%)}
.tf-fort i{bottom:3px;left:10px;width:6px;height:10px;background:#503627;border-radius:8px 8px 0 0}
.tf-fort-damaged{color:#ff977e}
.tf-hp{color:#ffa9a2;font-weight:800;font-size:.88rem}
.tf-hp small{margin-left:2px;color:#d2b7af;font-size:.65rem}
.tf-hp-track{width:100%;height:3px;margin-top:3px;border-radius:3px;background:linear-gradient(90deg,#ec8e79 var(--health),#351f23 var(--health))}
.tf-energy{display:grid;grid-template-columns:repeat(3,7px);gap:3px}
.tf-energy i{width:6px;height:6px;rotate:45deg;border:1px solid #9bfcd047;border-radius:1px}
.tf-energy .spent{background:#33816b68}
.tf-energy .lit{background:var(--mint);box-shadow:0 0 6px #5bf2ad}
.tf-clock{font-size:.77rem;color:var(--gold);font-variant-numeric:tabular-nums;white-space:nowrap;min-width:3ch}
.tf-hidden-hand{display:flex;align-items:center;padding-left:5px;min-width:0}
.tf-hidden-hand .tf-card-back{margin-left:-8px;max-width:25%;rotate:-7deg}
.tf-hidden-hand .tf-card-back:nth-child(even){rotate:4deg;translate:0 2px}
.tf-field{position:relative;display:grid;grid-template-columns:minmax(0,1fr) clamp(55px,12vw,135px);align-items:center;gap:5px;padding:0 clamp(4px,2vw,16px)}
.tf-table-cards{min-width:0}
.tf-table-row{position:relative;display:flex;justify-content:center;align-items:center;gap:clamp(3px,1.5vw,18px);min-height:clamp(94px,17svh,154px);padding:5px}
.tf-table-rival{margin-bottom:7px}
.fronts .tf-slot{position:relative;flex:0 1 auto;width:clamp(73px,14vw,101px);min-width:0;aspect-ratio: .74;padding:0;background:none;border:0;border-radius:9px;transform:translateY(var(--lift,0px)) rotate(var(--tilt,0deg));box-shadow:0 7px 9px #0007}
.fronts .tf-slot:hover{transform:translateY(-5px) rotate(0deg);z-index:2}
.tf-slot .tf-card{width:100%;height:100%;box-shadow:none;padding:3px;gap:2px;min-height:0}
.tf-slot .tf-artwork{flex:1;min-height:0;aspect-ratio:auto}
.tf-slot .tf-card-name{min-height:1.1em;font-size:clamp(.68rem,1.45vw,.83rem)}
.tf-slot .tf-card-stats{font-size:.7rem}
.tf-slot .tf-cost{display:none}
.tf-ready{outline:2px solid #83d3ab;box-shadow:0 0 14px #80ffd04a}
.tf-selected{outline:2px solid var(--gold);outline-offset:1px}
.tf-target{outline:2px solid var(--mint);box-shadow:0 0 17px #51ffc68c;cursor:crosshair}
.fronts .tf-drop{position:absolute;inset:4px;z-index:3;border:1px dashed #affbd8;border-radius:12px;background:#102b26cf;color:#dcffeb;font-weight:750;letter-spacing:.015em}
.fronts .tf-drop:hover{transform:none;background:#1c4839e8}
.tf-table-markers{display:flex;justify-content:end;align-items:center;gap:5px;color:#ffe1a5}
.tf-own .tf-table-markers{justify-content:start}
.tf-table-markers i{font-style:normal}
.tf-trap-mark .tf-card-back{width:19px;height:29px;rotate:-8deg}
.tf-unit-conditions{position:absolute;left:2px;bottom:15px;pointer-events:none;display:flex;gap:2px}
.tf-unit-conditions i{font:750 .63rem/1 system-ui;color:#e4fff0;background:#112731f3;border:1px solid #5f948c;border-radius:4px;padding:2px 3px}
.fronts .tf-deck{justify-self:center;display:grid;justify-items:center;gap:10px;max-width:100%;padding:6px 0;border:0;background:transparent;color:var(--gold);font-size:.72rem;box-shadow:none}
.tf-deck-stack{position:relative;display:block;width:clamp(34px,6.9vw,73px);aspect-ratio:2/3;rotate:9deg;transition:rotate .22s,translate .22s;filter:drop-shadow(2px 9px 6px #0009)}
.tf-deck-stack .tf-card-back,.tf-card-flight .tf-card-back{width:100%;height:100%}
.tf-deck-stack .tf-card-back{position:absolute;inset:0}
.tf-deck-stack .tf-card-back:nth-child(1){transform:translate(3px,6px) rotate(-4deg)}
.tf-deck-stack .tf-card-back:nth-child(2){transform:translate(2px,3px) rotate(3deg)}
.tf-deck-stack .tf-card-back:nth-child(3){transform:translate(-1px,-1px)}
.tf-deck-empty .tf-deck-stack .tf-card-back{visibility:hidden}
.tf-deck-empty .tf-deck-stack{border:1px dashed #bda67a7a;border-radius:7px}
.tf-deck-count{white-space:nowrap}
.tf-end{justify-self:end;padding:8px 10px;font-size:.76rem}
.tf-command{display:flex;min-height:42px;align-items:center;gap:7px 12px;flex-wrap:wrap;padding:6px 10px;color:#dce7e7;font-size:.83rem;border-block:1px solid #a9c5bf24;background:#121a287d}
.tf-energy-text{color:#abfae5;white-space:nowrap}
.tf-confirm-card{margin-left:auto}
.tf-command .tf-quiet{padding:5px 8px;font-size:.73rem}
.tf-turn{color:var(--gold);white-space:nowrap;font-weight:800}
.tf-turn b{color:#98afac}
.tf-clear{margin-left:auto;padding:1px 8px;border-radius:7px;font-size:1rem}
.tf-hand{display:flex;justify-content:safe center;align-items:stretch;gap:0;padding:13px 12px 18px;overflow-x:auto;scrollbar-width:thin}
.tf-hand .tf-card{flex:0 0 clamp(87px,12vw,110px);min-height:0;opacity:.8;transform:translateY(var(--lift)) rotate(var(--tilt))}
.tf-hand .tf-card+.tf-card{margin-left:-10px}
.tf-hand .tf-card:is(:hover,:focus-visible,.tf-selected){z-index:2;transform:translateY(-7px) rotate(0deg)}
.tf-hand .tf-card:hover,.tf-hand .tf-affordable,.tf-hand .tf-selected{opacity:1}
.tf-hand .tf-affordable{box-shadow:0 0 0 1px #8cf0c9,0 0 13px #7cf8c94d,0 8px 15px #0008}
.tf-hand .tf-card-text{font-size:.62rem}
.tf-hand .tf-artwork{aspect-ratio:1/1.03}
.tf-result{display:grid;justify-items:center;gap:14px;text-align:center;padding:10px 16px}
.tf-result p{margin:0;color:#cfe3d8}
.tf-result .tf-crest{margin:0}
.tf-victory .tf-crest{animation:tf-victory .85s ease-out both}
.tf-result div{display:flex;gap:8px}
.tf-fx-layer{position:fixed;z-index:21;inset:0;pointer-events:none;overflow:hidden}
.tf-impact{position:fixed;display:grid;place-items:center;left:var(--x);top:var(--y);width:110px;height:110px;margin:-55px 0 0 -55px;border-radius:50%;color:var(--spell,#ffcb70);font:900 1.3rem system-ui;text-shadow:0 2px 4px #101420;animation:tf-pop .62s both;animation-delay:var(--delay,0ms)}
.tf-impact::before{content:"";position:absolute;inset:20%;border:2px solid currentColor;box-shadow:0 0 16px currentColor,inset 0 0 12px currentColor;border-radius:50%;opacity:.65}
.tf-fx-burst,.tf-fx-strike{position:fixed;color:var(--fx-color);pointer-events:none}
.tf-fx-burst{z-index:2;width:0;height:0}
.tf-fx-ring{position:absolute;inset:-29px;width:58px;height:58px;border:2px solid currentColor;border-radius:50%;box-shadow:0 0 12px currentColor,inset 0 0 8px currentColor;animation:tf-fx-ring .57s ease-out var(--fx-delay,0ms) both}
.tf-fx-burst[data-phase="draw"] .tf-fx-ring{display:none}
.tf-fx-burst:is([data-phase="attack"],[data-phase="spell"]) .tf-fx-ring{width:76px;height:76px;inset:-38px;border-width:3px}
.tf-fx-burst[data-phase="draw"] .tf-fx-spark{font-size:9px}
.tf-fx-spark{position:absolute;top:-.5em;left:-.5em;width:1em;text-align:center;font:800 16px/1 system-ui;text-shadow:0 0 8px currentColor;animation:tf-fx-spark .53s cubic-bezier(.17,.61,.26,1) both}
.tf-fx-burst:is([data-shape="slash"],[data-shape="claw"]) .tf-fx-ring{border-width:0 4px 3px 0;border-radius:12% 62% 12% 62%;rotate:-31deg}
.tf-fx-burst:is([data-shape="arrow"],[data-shape="rush"],[data-shape="comet"]) .tf-fx-ring{border-color:currentColor transparent;rotate:-19deg}
.tf-fx-burst:is([data-shape="spark"],[data-shape="crack"],[data-shape="shards"]) .tf-fx-ring{border-radius:7px;rotate:35deg}
.tf-fx-burst:is([data-shape="spark"],[data-shape="crack"]) .tf-fx-spark{font-size:21px}
.tf-fx-burst:is([data-shape="bloom"],[data-shape="ward"]) .tf-fx-ring{border-style:double;border-width:5px;animation-name:tf-fx-ward}
.tf-fx-burst:is([data-shape="spiral"],[data-shape="surge"]) .tf-fx-ring{border-style:dashed;animation-name:tf-fx-ward}
.tf-fx-burst:is([data-shape="haze"],[data-shape="bubble"]) .tf-fx-ring{background:radial-gradient(ellipse,transparent 40%,currentColor);opacity:.38;border:0}
.tf-fx-burst[data-shape="rain"] .tf-fx-spark{animation-name:tf-fx-rain}
.tf-fx-strike{z-index:1;margin:-17px 0 0 -21px;width:42px;height:34px;font:900 30px/1 system-ui;text-align:center;text-shadow:0 0 8px #fff,0 0 21px currentColor;animation:tf-fx-travel .31s ease-in both}
.tf-fx-strike::after{content:"";position:absolute;left:-30px;top:50%;width:40px;height:3px;background:linear-gradient(90deg,transparent,currentColor);box-shadow:0 0 8px currentColor}
.tf-fx-strike:is([data-shape="arrow"],[data-shape="rush"],[data-shape="comet"],[data-shape="spark"])::after{left:-55px;width:65px;height:5px}
.tf-fx-strike:is([data-shape="slash"],[data-shape="claw"])::after{width:33px;height:14px;border-top:2px solid currentColor;border-bottom:2px solid currentColor;border-radius:50%;background:none}
.tf-fx-strike:is([data-shape="bubble"],[data-shape="ward"],[data-shape="spiral"])::after{left:0;top:-4px;width:29px;height:29px;border:2px solid currentColor;background:none;border-radius:50%}
.tf-flying{position:fixed;margin:0;z-index:1;padding:0;border-radius:8px;width:47px;height:64px;left:var(--x);top:var(--y);translate:-50% -50%;object-fit:contain;background:#182733;border:1px solid #fff1b2;box-shadow:0 0 16px #ffd4898a;animation:tf-fly .42s cubic-bezier(.2,.6,.35,1) both}
.tf-spell-art{position:fixed;left:var(--x);top:var(--y);width:95px;height:95px;translate:-50% -50%;object-fit:cover;border:2px solid var(--spell);border-radius:50%;box-shadow:0 0 25px var(--spell);animation:tf-spell .68s both}
.tf-spell-art:is([data-spell="bolt"],[data-spell="meteor"],[data-spell="fire"]){border-radius:36% 64% 66% 34%;animation:tf-comet .62s ease-out both}
.tf-spell-art:is([data-spell="hail"],[data-spell="rain"],[data-spell="cleanse"]){animation:tf-weather .72s ease-out both}
.tf-spell-art:is([data-spell="gust"],[data-spell="portal"],[data-spell="wind"]){animation:tf-vortex .65s ease-out both}
.tf-in-flight{opacity:0!important}
.tf-card-flight{position:fixed;z-index:1;transform-origin:center;perspective:480px;will-change:transform}
.tf-flight-inner{position:relative;width:100%;height:100%;transform-style:preserve-3d}
.tf-flight-inner>*{position:absolute;inset:0;backface-visibility:hidden}
.tf-flight-face{transform:rotateY(180deg);display:grid;place-items:center;border:1px solid #ffc969;border-radius:7px;background:#172c2a;overflow:hidden}
.tf-flight-face img{width:100%;height:100%;object-fit:contain}
.tf-table-impact::after{animation:tf-table-impact .49s ease-out both}
.tf-banner-fx{position:fixed;z-index:4;left:var(--x);top:var(--y);translate:-50% -50%;display:flex;align-items:center;justify-content:center;gap:12px;min-width:min(42vw,270px);max-width:85vw;padding:10px 30px;border-block:1px solid var(--banner-color);background:linear-gradient(90deg,transparent,#071b1ded 19%,#102920f5 52%,#071b1ded 81%,transparent);color:var(--banner-color);text-align:center;font:700 clamp(1rem,3.2vw,1.8rem)/1.15 'Fronts Display',Georgia,serif;font-style:normal;text-shadow:0 2px 7px #000,0 0 20px var(--banner-color);animation:tf-banner-fade .78s ease-out both}
.tf-banner-legend{padding-block:8px;color:#ffefc8}
.tf-banner-legend img{width:45px;height:61px;object-fit:cover;border-radius:5px;border:1px solid var(--banner-color);box-shadow:0 0 13px var(--banner-color)}
.tf-lunge{animation:tf-lunge .46s ease-in-out}
@keyframes tf-lunge{20%{translate:calc(var(--lunge-x) * -.25) calc(var(--lunge-y) * -.25);scale:.96}52%{translate:var(--lunge-x) var(--lunge-y);scale:1.17}}
@keyframes tf-table-impact{0%,24%,100%{background:transparent}48%{background:radial-gradient(ellipse at center,transparent 16%,color-mix(in srgb,var(--strike-color) 28%,transparent));box-shadow:inset 0 0 30px var(--strike-color)}}
@keyframes tf-banner-fade{0%{opacity:0;transform:translateY(9px) scale(.87)}24%,75%{opacity:1;transform:none}100%{opacity:0;transform:translateY(-12px) scale(1.04)}}
@keyframes tf-fly{from{scale:.68;opacity:.8}75%{opacity:1}to{left:var(--to-x);top:var(--to-y);scale:1.13;opacity:0}}
@keyframes tf-spell{0%,100%{opacity:0;scale:.45}35%{opacity:.92;scale:1}}
@keyframes tf-comet{0%{opacity:0;transform:translate(40px,-70px) rotate(-23deg) scale(.55)}35%{opacity:1;scale:1.2}100%{opacity:0;scale:.85}}
@keyframes tf-weather{0%{opacity:0;transform:translateY(-42px) scale(.86)}40%{opacity:.95}100%{opacity:0;transform:translateY(35px) scale(1.03)}}
@keyframes tf-vortex{0%{opacity:0;rotate:-110deg;scale:.36}45%{opacity:1}100%{opacity:0;rotate:35deg;scale:1.3}}
@keyframes tf-victory{0%{opacity:0;transform:rotate(-55deg) scale(.45)}60%{opacity:1;transform:rotate(10deg) scale(1.35)}}
@keyframes tf-pop{0%{opacity:0;transform:scale(.3)}24%{opacity:1;transform:scale(1.12)}80%{opacity:1}100%{opacity:0;transform:translateY(-25px) scale(1.17)}}
@keyframes tf-fx-ring{0%{opacity:0;transform:scale(.25)}30%{opacity:.9}100%{opacity:0;transform:scale(1.62)}}
@keyframes tf-fx-ward{0%{opacity:0;transform:scale(.4) rotate(-60deg)}34%{opacity:1}100%{opacity:0;transform:scale(1.48) rotate(65deg)}}
@keyframes tf-fx-spark{0%{opacity:0;transform:scale(.35)}20%{opacity:1}100%{opacity:0;transform:translate(var(--dx),var(--dy)) rotate(var(--spin)) scale(.45)}}
@keyframes tf-fx-rain{0%{opacity:0;transform:translate(var(--dx),-44px)}27%{opacity:1}100%{opacity:0;transform:translate(var(--dx),calc(var(--dy) + 36px)) scale(.65)}}
@keyframes tf-fx-travel{0%{opacity:0;transform:rotate(var(--heading)) scale(.55)}20%{opacity:1}72%{opacity:1}100%{opacity:0;transform:translate(var(--dx),var(--dy)) rotate(var(--heading)) scale(1.14)}}
@keyframes tf-float{50%{transform:translateY(-8px) rotate(calc(var(--tilt) + 2deg))}}
@keyframes tf-spin{to{rotate:360deg}}
@media(max-width:1280px){.tf-lobby,.tf-lobby-footer{margin-inline:16px}}
@media(max-width:650px){
  .tf-top{padding:10px 12px}
  .tf-lobby{min-height:540px;margin-inline:9px;background-position:62% top;background-size:auto 135%;align-items:end;border-radius:18px}
  .tf-lobby::before{background:linear-gradient(0deg,#081720 0%,#0b1a25f5 24%,#12232b8c 61%,#10212b12 92%)}
  .tf-lobby-copy{padding:21px 16px 22px}
  .tf-lobby h1{font-size:clamp(3rem,13.6vw,5.4rem)}
  .tf-crest{margin-bottom:8px}
  .tf-pitch{margin:15px 0}
  .tf-lobby-fan{top:10%;right:7%;bottom:auto}
  .tf-lobby-footer{margin-inline:13px}
  .tf-rival,.tf-own{grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);padding-inline:4px;gap:4px}
  .tf-castle{gap:5px;padding:3px 5px}
  .tf-fort{scale:.8;margin-inline:-3px}
  .tf-end{padding:7px 5px}
  .tf-hidden-hand .tf-card-back{width:20px;height:29px}
  .tf-field{padding-inline:4px}
  .tf-arena{padding-inline:8px}
  .tf-stage{perspective:510px;padding-inline:11px;padding-bottom:19px}
  .tf-arena-clearing{--table-angle:14deg;border-width:8px;border-radius:19px}
  .tf-table-row{gap:3px;padding:3px;min-height:111px}
  .tf-slot .tf-card-stats{font-size:.62rem}
  .tf-slot .tf-card-name{font-size:.60rem}
  .tf-catalog{grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}
  .tf-dialog{padding:12px;width:min(475px,94vw)}
  .tf-catalog-entry .tf-card-name{font-size:.93rem}
  .tf-catalog-entry .tf-card-text{font-size:.65rem}
}
@media(max-width:350px){.tf-catalog{grid-template-columns:repeat(2,minmax(0,1fr))}.tf-hand .tf-card{flex-basis:80px}}
.light-theme .fronts :is(.tf-lobby h1,.tf-castle-label strong,.tf-catalog-entry b,.tf-searchbox strong),.light-theme .fronts .tf-card strong{color:var(--ink)}
.light-theme .fronts :is(.tf-card-stats b,.tf-hp b,.tf-deck b){color:inherit}
.light-theme .fronts :is(.tf-dialog-header h2,.tf-result h2){color:var(--gold)}
.light-theme .fronts .tf-wordmark{color:#172033}
.light-theme .fronts :is(.tf-turn,.tf-filters b){color:#735119}
.light-theme .fronts .tf-command{background:#eef4ff;color:#334155}
.light-theme .fronts .tf-energy-text{color:#086950}
@media(prefers-reduced-motion:reduce){.fronts *,.fronts *::before,.fronts *::after,.tf-fx-layer *{animation-duration:.01ms!important;animation-iteration-count:1!important;animation-delay:0ms!important;scroll-behavior:auto!important}}


/* source: markerFix.css */
.marker-zoomed-sheet{width:min(100%,360px);text-align:center}
.marker-zoomed-sheet .marker-sheet{width:100%;box-sizing:border-box;background-image:none;border:2px dashed #d8bf8d;touch-action:none;user-select:none}
.marker-drawing-actions{display:flex;gap:10px;justify-content:center;margin-top:14px}
.marker-drawing-actions button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;flex:1}
.marker-status{display:grid;gap:8px}.marker-status span{font-size:13px;color:var(--muted,#9da7bb)}
.marker-zoomed-sheet [role=status]{min-height:20px;font-size:12px;color:#e7be78}
.marker-race-scores{display:flex;justify-content:center;gap:12px;flex-wrap:wrap}
.marker-race-scores span{padding:8px 14px;border:1px solid var(--line);border-radius:12px;font-size:13px}
.marker-race-scores b{color:#67e8f9;margin-left:8px}
.marker-target{font-size:18px;color:#61e6d2}.marker-target b{font-size:28px}
.marker-page .marker-panel{gap:12px;padding:20px}.marker-page h1{font-size:clamp(24px,4vw,38px);margin:0}
.marker-page .marker-board,.marker-page .marker-sheet-wrap{width:min(100%,570px)}
.marker-page .marker-race-sheet{width:100%;background-image:none;touch-action:none}
.marker-race-sheet+ [role=status]{min-height:18px;font-size:12px;color:#e7be78;margin:4px 0}
@media(max-width:560px){.marker-page .marker-panel{padding:12px;gap:8px}.marker-race-scores{gap:6px}.marker-race-scores span{padding:6px 9px}.marker-page .marker-board,.marker-page .marker-sheet-wrap{width:100%}}


/* source: room.css */
.room-page.compact-room { max-width:1140px; }
.compact-room .room-header {
  display:flex;
  align-items:center;
  justify-content:space-between;
  flex-wrap:wrap;
  gap:10px 16px;
  overflow:visible;
  z-index:2;
  margin:0;
  padding:14px 18px;
  border-radius:18px;
  animation:none;
}
.compact-room .room-header::after { content:none; }
.compact-room .room-heading { min-width:0; }
.compact-room .room-heading h1 {
  margin:2px 0 0;
  font-size:clamp(20px,3vw,30px);
  line-height:1.15;
  overflow-wrap:anywhere;
}
.compact-room .room-heading .eyebrow { margin:0; }
.compact-room .room-heading .eyebrow img { width:20px; height:20px; vertical-align:middle; }
.compact-room .room-heading .room-type-badge { margin-top:6px; }
.compact-room .room-header-actions {
  display:flex;
  flex-wrap:wrap;
  justify-content:flex-start;
  gap:6px;
  width:auto;
}
.compact-room-code {
  padding:8px 13px;
  border:1px solid #67e8f980;
  border-radius:12px;
  color:#c2f8ff;
  background:#143240;
  font-size:clamp(32px,4vw,40px);
  font-weight:900;
  line-height:1;
  letter-spacing:.1em;
  font-variant-numeric:tabular-nums;
  text-align:center;
  white-space:nowrap;
  box-shadow:0 0 12px #22d3ee26;
}
@media (prefers-reduced-motion:no-preference) {
  .compact-room-code { animation:room-code-pulse 3.2s ease-in-out 3; }
}
@keyframes room-code-pulse {
  50% { box-shadow:0 0 21px #22d3ee64; }
}
.compact-room .room-icon-action,.compact-room .compact-room-leave {
  display:inline-flex;
  align-items:center;
  justify-content:center;
  flex:none;
  gap:4px;
  width:auto;
  min-width:40px;
  min-height:40px;
  padding:6px 8px;
  border-radius:10px;
}
.compact-room .room-icon-action svg,.compact-room .compact-room-leave svg { flex:none; }
.compact-room .lobby-layout {
  grid-template-columns:minmax(285px,340px) minmax(0,1fr);
  align-items:start;
  gap:12px;
  margin:12px 0 0;
}
.compact-room .compact-room-roster,.compact-room .lobby-settings {
  min-width:0;
  min-height:0;
  margin:0;
  padding:14px;
  border-radius:16px;
}
.room-roster-head,.room-roster-tools,.room-player-identity,.room-player-tools,.compact-room-start {
  display:flex;
  align-items:center;
  gap:7px;
}
.room-roster-tools { margin-inline-start:auto; }
/* The lobby entrance animation and the roster panel create separate stacking contexts. */
.compact-room .lobby-layout:has(.compact-add-bot:is(:hover,:focus-visible)) {
  position:relative;
  z-index:3;
}
.compact-room .compact-room-roster:has(.compact-add-bot:is(:hover,:focus-visible)) { z-index:2; }
.compact-room h2 { margin:0; font-size:1.12rem; }
.compact-room .lobby-settings > h2 { margin-bottom:10px; }
.room-player-list {
  display:grid;
  grid-template-columns:minmax(0,1fr);
  gap:7px;
  margin:10px 0;
  padding:0;
  list-style:none;
}
.room-player-row {
  display:grid;
  grid-template-columns:minmax(0,1fr) auto;
  align-items:center;
  gap:4px 6px;
  min-height:56px;
  padding:7px 12px;
  border:1px solid #94a3b826;
  border-radius:12px;
  background:#94a3b80c;
}
.room-player-identity { min-width:0; gap:5px; }
.room-player-identity .mini-player { justify-content:flex-start; flex-wrap:nowrap; gap:5px; }
.room-player-identity .mini-player > .avatar { flex:none; width:28px; height:28px; }
.room-player-identity :is(.age-badge,.level-badge,.bot-player-mark,.room-host-mark,.friend-lobby-mark) { flex:none; white-space:nowrap; }
.room-player-tools { justify-self:end; gap:3px; }
.compact-room .room-player-tools .room-icon-action { min-width:34px; min-height:34px; padding:3px 5px; }
.room-host-mark { display:inline-flex; color:#facc15; }
.room-bot-difficulty { grid-column:1/-1; justify-self:end; min-height:34px; padding:4px 8px; font-size:.78rem; }
.compact-room-start { flex-wrap:wrap; justify-content:space-between; }
.compact-room-start small { color:#a6b4c9; }
.compact-room-start button { min-height:40px; padding:7px 11px; }
.compact-room .compact-room-activity { margin:10px 0 0; padding:8px 14px; }
.compact-room [data-host-announcement-anchor][hidden],.compact-room .compact-room-activity[hidden] { display:none; }
.compact-room-activity summary { cursor:pointer; font-size:.9rem; }
.compact-room-activity .room-activity-list { margin-top:8px; }
.compact-room > .adsense-lobby:empty { min-height:0; margin:0; }
.light-theme .compact-room-code { color:#104860; background:#e3f5ff; border-color:#78b9ce; }
.light-theme .compact-room-start small { color:#32516c; }
.light-theme .room-host-mark { color:#9c6600; }

@media (max-width:900px) {
  .compact-room .room-header { padding:11px 12px; }
  .room-page.compact-room .lobby-layout { grid-template-columns:minmax(0,1fr); }
  .compact-add-bot[data-bot-tooltip]::after {
    inset-inline: auto 0;
    box-sizing:border-box;
    max-width:min(300px,calc(100vw - 90px));
    transform:translateY(4px);
  }
  .compact-add-bot[data-bot-tooltip]:is(:hover,:focus-visible)::after { transform:none; }
}
@media (max-width:520px) {
  .compact-room .room-header-actions { gap:4px; }
  .compact-room .room-header-actions .room-icon-action,.compact-room .compact-room-leave { min-width:36px; }
  .compact-room .compact-room-leave span { display:none; }
  .compact-room .room-heading { flex-basis:100%; }
  .compact-room .compact-room-roster,.compact-room .lobby-settings { padding:10px; }
}
@media (max-width:420px) {
  .compact-room .room-header-actions { width:100%; }
  .compact-room-code { flex-basis:100%; }
}


/* source: connect.css */
.connect-page .connect-word-panel {
  max-width:650px;
  margin:0 auto 12px;
  padding:clamp(16px,4vw,30px);
  border-color:#85d6eb38;
  background:radial-gradient(ellipse at 50% 0,#233459,#101625 72%);
}
.connect-round-head { display:flex; justify-content:space-between; align-items:center; gap:8px; text-align:left; }
.connect-round-head .eyebrow { margin:0; }
.connect-clock {
  flex:none;
  border:1px solid #9debf53d;
  border-radius:9px;
  padding:5px 9px;
  color:#9debf5;
  font-variant-numeric:tabular-nums;
}
.connect-word-panel h1 { margin:15px 0; font-size:clamp(24px,6vw,40px); }
.connect-word-pair {
  display:grid;
  grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);
  align-items:center;
  gap:clamp(6px,2vw,14px);
  margin:18px 0;
}
.connect-word {
  min-width:0;
  border:1px solid #88b6f33b;
  border-radius:14px;
  padding:clamp(9px,2vw,17px);
  background:#88b6f315;
}
.connect-word small { display:block; overflow:hidden; text-overflow:ellipsis; white-space:nowrap; color:#adbeda; }
.connect-word strong { display:block; margin-top:5px; font-size:clamp(16px,4vw,27px); overflow-wrap:anywhere; }
.connect-word-pair.is-match .connect-word { color:#a7ffd0; border-color:#a7ffd076; background:#a7ffd01c; }
.connect-word-form { display:flex; gap:7px; margin:14px auto 0; max-width:410px; }
.connect-word-form input { min-width:0; flex:1; font-size:16px; }
.connect-word-form button { flex:none; }
.connect-wait { min-height:42px; margin:14px 0 0; color:#a7dae9; overflow-wrap:anywhere; }
.connect-word-error { display:block; margin-top:6px; color:#ffbdac; }
.connect-word-error:empty { display:none; }
.connect-word-history { margin:18px 0 0; text-align:start; color:#adbeda; }
.connect-word-history summary { cursor:pointer; }
.connect-word-history li { overflow-wrap:anywhere; }
.light-theme .connect-page .connect-word-panel { background:#f6f8ff; color:#17233c; }
.light-theme .connect-word small,.light-theme .connect-clock,.light-theme .connect-wait,.light-theme .connect-word-history { color:#315579; }
.light-theme .connect-word-pair.is-match .connect-word { color:#087547; }
