/* source: chess.css */
.chess-page {
  --chess-ink: #f8eddd;
  --chess-muted: #c0b4ab;
  --chess-edge: #57434a;
  --chess-panel: #201b2a;
  --chess-accent: #f9cf8c;
  max-width: 940px;
  margin-inline: auto;
  color: var(--chess-ink);
}

.chess-heading {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 14px;
}
.chess-heading h1 { margin: 0; font-size: clamp(26px, 4vw, 42px); }
.chess-heading [role="status"] {
  overflow-wrap: anywhere;
  text-align: right;
  color: var(--chess-accent);
  font-size: 14px;
}
.chess-heading small { display: block; color: var(--chess-muted); font-size: 11px; }
.chess-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(220px, 300px);
  gap: clamp(12px, 3vw, 30px);
  align-items: start;
}
.chess-play {
  position: relative;
  display: grid;
  gap: 7px;
  min-width: 0;
}
.chess-player, .chess-history {
  background: var(--chess-panel);
  border: 1px solid var(--chess-edge);
  border-radius: 12px;
}
.chess-player {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  min-height: 47px;
  padding: 5px 10px;
  gap: 0 8px;
}
.chess-player.is-active { border-color: #b48d62; background: linear-gradient(90deg, #342733, #231e2b); }
.chess-player-name { display: flex; min-width: 0; align-items: center; gap: 5px; font-size: 14px; }
.chess-player-name b { overflow: hidden; white-space: nowrap; text-overflow: ellipsis; }
.chess-player-name .chess-piece { font-size: 21px; }
.chess-captured { display: flex; grid-row: 2; min-width: 0; flex-wrap: wrap; }
.chess-captured:empty { display: none; }
.chess-captured .chess-piece { font-size: 14px; }
.chess-clock {
  grid-column: 2;
  grid-row: 1 / span 2;
  padding: 3px 8px;
  border-radius: 6px;
  background: #393341;
  font-size: clamp(16px, 4vw, 26px);
  font-weight: 800;
  font-variant-numeric: tabular-nums;
}
.chess-player.is-active .chess-clock { color: #201b2a; background: var(--chess-accent); }
.chess-player.is-active .chess-clock.is-low { background: #ff9ba7; }
.chess-board {
  display: grid;
  grid-template-columns: repeat(8, minmax(0, 1fr));
  aspect-ratio: 1;
  overflow: hidden;
  border: 3px solid #805d55;
  border-radius: 9px;
  box-shadow: 0 12px 32px #08061166;
  container-type: inline-size;
}
.chess-board .chess-cell {
  display: grid;
  position: relative;
  place-items: center;
  aspect-ratio: 1;
  min-width: 0;
  min-height: 0;
  padding: 0;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  line-height: 1;
  touch-action: manipulation;
}
.chess-cell.light { background: #e5c3a3; color: #633f46; }
.chess-cell.dark { background: #89595b; color: #ffe6c5; }
.chess-board button.chess-cell:hover { filter: brightness(1.1); transform: none; }
.chess-board .chess-cell.is-last { background: #ce9d5e; color: #2e1f2d; }
.chess-board .chess-cell.is-selected { background: #edd687; color: #2e1f2d; }
.chess-board .chess-cell.is-check { background: radial-gradient(#da575f 0 37%, #a54d55 84%); color: white; }
.chess-cell::after { position: absolute; content: ""; pointer-events: none; }
.chess-cell.can-move::after { inset: 36%; border-radius: 50%; background: #174c43b0; outline: 1px solid #def7d688; }
.chess-cell.can-capture::after { inset: 3%; border: 4px solid #295c51; border-radius: 9px; }
.chess-board button.chess-cell:focus-visible { z-index: 2; outline: 3px solid #1957a0; outline-offset: -3px; }
.chess-piece, .game-visual-board-chess > span {
  font-family: "DejaVu Sans", "Segoe UI Symbol", "Apple Symbols", serif;
  font-variant-emoji: text;
  font-weight: 400;
  line-height: 1;
}
.chess-cell .chess-piece { font-size: clamp(24px, 10.5cqw, 64px); }
.chess-w { color: #fff5df; text-shadow: 0 2px 1px #35252e; -webkit-text-stroke: 1px #5f4248; }
.chess-b { color: #252039; text-shadow: 0 2px 1px #1e122778; -webkit-text-stroke: .6px #d1ab98; }
.chess-file, .chess-rank { position: absolute; font: 700 clamp(8px, 2.1cqw, 12px)/1 system-ui; }
.chess-rank { top: 3px; left: 3px; }
.chess-file { bottom: 3px; right: 3px; }
.chess-side { display: grid; gap: 9px; align-self: start; }
.chess-history { min-width: 0; padding: 13px; }
.chess-history h2 { margin: 0 0 8px; font-size: 16px; }
.chess-history-list {
  max-height: clamp(125px, 44vh, 365px);
  min-height: 66px;
  margin: 0;
  padding: 0;
  overflow-y: auto;
  list-style: none;
  scrollbar-color: #876572 transparent;
}
.chess-history-list li { display: grid; grid-template-columns: 30px repeat(2,minmax(0, 1fr)); align-items: center; }
.chess-history-list li:nth-child(odd) { background: #302736; border-radius: 6px; }
.chess-history-list li > span { color: var(--chess-muted); padding-left: 7px; font-size: 12px; }
.chess-history-list button { min-height: 34px; padding: 2px 6px; border-radius: 5px; border: 1px solid transparent; color: var(--chess-ink); background: transparent; font: 600 13px ui-monospace, monospace; }
.chess-history-list button:hover, .chess-history-list button[aria-current] { background: #59414a; border-color: #ad836b; }
.chess-history-list li.chess-history-empty { display: block; padding: 10px; color: var(--chess-muted); font-size: 13px; }
.chess-history-controls, .chess-commands, .chess-footer { display: flex; flex-wrap: wrap; align-items: center; gap: 6px; }
.chess-history-controls { margin-top: 8px; }
.chess-page :is(.ghost, .primary) { min-height: 36px; padding: 5px 9px; font-size: 12px; }
.chess-footer { margin-top: 9px; align-items: start; justify-content: space-between; color: var(--chess-muted); font-size: 13px; }
.chess-footer details { flex: 1; }
.chess-footer summary { cursor: pointer; min-height: 36px; line-height: 36px; }
.chess-promotion {
  position: absolute;
  z-index: 3;
  inset: 50% 6% auto;
  translate: 0 -50%;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 5px;
  padding: 12px;
  border: 1px solid #d3a074;
  border-radius: 12px;
  background: var(--chess-panel);
  box-shadow: 0 0 0 80px #1d162b80;
}
.chess-promotion b { flex: 1 0 100%; text-align: center; }
.chess-promotion .chess-piece { font-size: 34px; }
.game-visual-board-chess {
  background:
    radial-gradient(ellipse at 50% 30%, #ebad7870, transparent 68%),
    repeating-conic-gradient(#634457 0% 25%, #463148 0% 50%) center / 44px 44px;
}
.game-visual-board-chess > span { color: #fff0d9; text-shadow: 0 4px 0 #4b303e, 0 8px 16px #291929aa; }
.light-theme .chess-page { --chess-panel: #3d2d3d; --chess-edge: #8d6e77; }
.light-theme .chess-heading h1, .light-theme .chess-heading [role="status"], .light-theme .chess-heading small, .light-theme .chess-footer { color: #3d2d3d; }

@media (max-width: 690px) {
  .chess-layout { grid-template-columns: minmax(0, 1fr); }
  .chess-history-list { max-height: 144px; min-height: 0; }
  .chess-heading { margin-bottom: 8px; }
  .chess-footer { padding-inline-end: 48px; }
}


/* source: letterTable.css */
.lt-page {
  --lt-ink:#f8f2e7;
  --lt-muted:#b9b8b2;
  --lt-panel:#15252a;
  --lt-rim:#48605d;
  --lt-cell:#30494a;
  --lt-rail:#523123;
  --lt-wood:#322823;
  --lt-board-size:min(100%, 570px, max(340px, 100dvh - 395px));
  max-width:1010px;
  color:var(--lt-ink);
  margin-inline:auto;
}
.lt-heading { display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:14px; }
.lt-heading h1 { margin:0; font-size:clamp(1.5rem,4vw,2.55rem); line-height:1; }
.lt-heading .eyebrow { margin:0 0 6px; color:#eabe83; }
.lt-turn { display:flex; flex-wrap:wrap; gap:4px 9px; justify-content:flex-end; align-items:center; font-size:.84rem; text-align:right; }
.lt-turn.is-yours { color:#a5ead1; }
.lt-turn time { min-width:42px; padding:5px 8px; border:1px solid var(--lt-rim); border-radius:8px; background:var(--lt-panel); font-variant-numeric:tabular-nums; text-align:center; }
.lt-layout { display:grid; grid-template-columns:minmax(0,1fr) 235px; gap:16px; align-items:start; }
.lt-play {
  display:grid; justify-items:center; min-width:0; padding:clamp(8px,1.7vw,18px);
  border:1px solid #745b46; border-radius:20px;
  background:repeating-linear-gradient(3deg,#ffbe8110 0 1px,transparent 2px 9px),linear-gradient(150deg,#4a352c,#281f20 80%);
  box-shadow:inset 0 1px 1px #fff1cf33,0 14px 28px #0005;
}
.lt-board {
  display:grid; grid-template-columns:repeat(13,minmax(0,1fr)); width:var(--lt-board-size);
  aspect-ratio:1; gap:clamp(1px,.28vw,3px); padding:clamp(3px,.7vw,7px);
  border-radius:9px; background:#162b2e; border:1px solid #73978c70; box-shadow:0 4px 0 #1c2321,0 8px 16px #0006;
}
.lt-cell {
  display:grid; place-items:center; padding:0; min-width:0; min-height:0; aspect-ratio:1;
  border:0; border-radius:3px; background:var(--lt-cell); color:#d7efd9;
  font:800 clamp(8px,1.1vw,13px)/1 system-ui,sans-serif; cursor:pointer; touch-action:manipulation;
}
.lt-cell[data-premium="l2"] { background:#355c68; color:#c7f8ff; }
.lt-cell[data-premium="l3"] { background:#3f4976; color:#e3e0ff; }
.lt-cell[data-premium="w2"] { background:#6f5634; color:#ffe4af; }
.lt-cell[data-premium="w3"] { background:#7e4544; color:#ffe0d6; }
.lt-cell:not(.has-tile):hover,.lt-cell:focus-visible { outline:2px solid #f6df88; outline-offset:-2px; z-index:1; }
.lt-cell.has-tile { background:#24221d; }
.lt-tile {
  width:100%; height:100%; aspect-ratio:1; position:relative; display:grid; place-items:center; border-radius:12%;
  color:#3d2518; border:1px solid #e0a770;
  background:repeating-linear-gradient(170deg,#fff1be21 0 1px,transparent 2px 6px),linear-gradient(145deg,#ffedbd,#e2aa6e);
  box-shadow:inset 0 1px 1px #fffbd8,inset 0 -2px 0 #965b35,0 1px 2px #160d0b66;
}
.lt-tile b { font:850 1.18em/1 system-ui,sans-serif; }
.lt-tile small { position:absolute; right:8%; bottom:7%; font:700 .53em/1 system-ui,sans-serif; }
.lt-tile.is-blank { background:linear-gradient(145deg,#faf1d7,#d9caab); }
.lt-cell.has-tile .lt-tile { font-size:clamp(11px,2vw,25px); }
.lt-cell.is-draft .lt-tile { outline:2px solid #95f5d0; outline-offset:-2px; animation:lt-tile-settle .19s ease-out both; }
.lt-cell.is-new .lt-tile { box-shadow:inset 0 0 0 2px #d2ffae,inset 0 -2px 0 #965b35,0 0 8px #b6ffd461; }
@keyframes lt-tile-settle { from { transform:translateY(-5px) scale(1.08); } 70% { transform:translateY(1px) scale(.98); } to { transform:none; } }
.lt-workbench { display:grid; grid-template-columns:minmax(0,1fr) 102px; gap:14px; align-items:end; width:min(100%,590px); margin-top:10px; }
.lt-dock { min-width:0; }
.lt-dock-title { display:flex; justify-content:space-between; align-items:end; gap:8px; margin:0 0 5px; font-size:.82rem; }
.lt-dock-title small { color:#f0d3af; text-align:right; font-size:.68rem; }
.lt-rack { display:grid; grid-template-columns:repeat(7,minmax(0,1fr)); gap:4px; width:min(100%,444px); padding:5px 5px 8px; border-radius:10px; border:1px solid #a67a4d; background:linear-gradient(#754a32,var(--lt-rail)); box-shadow:inset 0 -4px 0 #2e1d18,0 5px 9px #0005; }
.lt-rack-slot { display:grid; min-width:0; min-height:0; aspect-ratio:1; padding:0; border:0; background:#291c1699; border-radius:11%; font-size:clamp(13px,2.1vw,30px); touch-action:manipulation; }
button.lt-rack-slot { cursor:pointer; }
button.lt-rack-slot[aria-pressed="true"] .lt-tile { outline:2px solid #bbffd7; outline-offset:-2px; transform:translateY(-4px); box-shadow:0 4px 7px #1b1621bb,inset 0 -2px #aa7146; }
.lt-rack-slot[data-flying] .lt-tile { visibility:hidden; }
.lt-bag-scene { display:grid; justify-items:center; position:relative; isolation:isolate; padding:0; color:#ffedc6; }
.lt-bag-scene::before { content:""; position:absolute; z-index:-1; width:83%; height:24%; border-radius:50%; bottom:5px; background:#190f0dbb; filter:blur(5px); }
.lt-bag-scene > strong { position:absolute; right:0; bottom:0; padding:3px 6px; border-radius:10px; background:#18343d; border:1px solid #8bccc358; font-size:.75rem; font-variant-numeric:tabular-nums; }
.lt-bag { width:82px; height:78px; position:relative; transform-origin:50% 91%; }
.lt-bag i { display:block; position:absolute; }
.lt-bag-body {
  inset:11px 5px 1px 2px; border-radius:39% 39% 31% 33% / 32% 31% 32% 34%;
  border:1px solid #4aa297; background:
    repeating-linear-gradient(115deg,#defad812 0 1px,transparent 2px 4px),
    radial-gradient(ellipse at 35% 39%,#50bbaa,#297b76 49%,#17444f 92%);
  box-shadow:inset -7px -5px 10px #12323c,inset 4px 1px 9px #b5ffcc36,0 5px 7px #1a171a66;
}
.lt-bag-body::after { content:""; position:absolute; inset:11px 5px 5px; border-radius:inherit; border:1px dashed #c5f8c372; }
.lt-bag-mouth { z-index:1; inset:5px 15px auto 11px; height:19px; border:4px solid #45998b; border-radius:50% 45% 48% 42%; background:#152f3b; box-shadow:0 3px 0 #1e555c,inset 0 2px 2px #0c2328; }
.lt-bag-cord { z-index:2; right:4px; top:19px; width:16px; height:23px; border:3px solid #e9bd7e; border-left:0; border-radius:0 50% 55% 0; transform:rotate(-19deg); }
.lt-bag-patch { z-index:1; top:35px; left:27px; width:25px; height:22px; border:1px dashed #f9c894; border-radius:5px; background:#b57b52; color:#fff0bd; text-align:center; font-style:normal; line-height:19px; transform:rotate(-9deg); }
.lt-flight { position:fixed; top:0; left:0; z-index:10030; display:block; width:52px; height:52px; opacity:0; pointer-events:none; will-change:transform,opacity; font-size:31px; filter:drop-shadow(0 8px 9px #0c161cab); }
.lt-controls { display:flex; flex-wrap:wrap; justify-content:center; gap:6px; width:100%; margin-top:10px; }
.lt-controls button,.lt-exit button { min-height:36px; padding:6px 10px; font-size:.78rem; }
.lt-sidebar { display:grid; gap:10px; min-width:0; }
.lt-scores,.lt-history,.lt-rules { background:var(--lt-panel); border:1px solid var(--lt-rim); border-radius:12px; padding:10px; }
.lt-scores { display:grid; gap:5px; }
.lt-scores > div { display:flex; align-items:center; justify-content:space-between; gap:7px; min-width:0; border:1px solid transparent; padding:4px 6px; border-radius:7px; }
.lt-scores .is-current { border-color:#629987; background:#6ffbc514; }
.lt-scores b { font-variant-numeric:tabular-nums; color:#ffe3a0; }
.lt-history h2 { margin:0 0 5px; font-size:.96rem; }
.lt-history ol { display:grid; gap:5px; list-style:none; padding:0; margin:0; }
.lt-history li { display:flex; justify-content:space-between; align-items:center; gap:6px; padding:5px 0; border-bottom:1px solid var(--lt-rim); overflow-wrap:anywhere; }
.lt-history li:last-child { border:0; }
.lt-history small,.lt-history b { display:block; font-size:.75rem; }
.lt-history small,.lt-history p,.lt-rules { color:var(--lt-muted); font-size:.73rem; }
.lt-history p,.lt-rules p { margin:5px 0 0; }
.lt-history strong { color:#9ae6c3; }
.lt-rules summary { cursor:pointer; color:var(--lt-ink); font-weight:700; }
.lt-rules ul { padding-inline-start:1.2rem; }
.lt-rules li + li { margin-top:.35rem; }
.lt-exit { display:flex; flex-wrap:wrap; gap:6px; }
.lt-blank-panel { padding:8px; margin-top:6px; background:var(--lt-panel); border:1px solid var(--lt-rim); border-radius:8px; }
.lt-blank-panel > div { display:grid; grid-template-columns:repeat(auto-fit,minmax(32px,1fr)); gap:3px; margin:6px 0; }
.lt-blank-panel button { padding:4px; min-height:32px; }
.light-theme .lt-page { --lt-ink:#f9f4ec; --lt-panel:#263d40; --lt-muted:#d6e0d8; }
.light-theme .lt-heading h1,.light-theme .lt-turn:not(.is-yours) b { color:#173339; }
.light-theme .lt-heading .eyebrow { color:#7d4e1e; }
.light-theme .lt-turn.is-yours b { color:#135741; }
@media (max-width:760px) {
  .lt-page { --lt-board-size:min(100%,490px); }
  .lt-layout { grid-template-columns:minmax(0,1fr); gap:10px; }
  .lt-workbench { grid-template-columns:minmax(0,1fr) 63px; gap:7px; }
  .lt-bag { transform-origin:50% 97%; width:62px; height:61px; }
  .lt-bag-mouth { inset-inline:8px 12px; height:15px; }
  .lt-bag-patch { top:28px; left:19px; width:21px; height:18px; line-height:15px; }
  .lt-bag-cord { width:12px; height:19px; top:16px; }
  .lt-rack { gap:2px; padding:4px 4px 7px; }
  .lt-cell.has-tile .lt-tile { font-size:clamp(11px,3.1vw,20px); }
  .lt-rack-slot { font-size:clamp(12px,4.1vw,25px); }
}
@media (prefers-reduced-motion:reduce) { .lt-cell.is-draft .lt-tile { animation:none; } }


/* source: chartForecast.css */
.chart-forecast-page {
  --chart-fill: #131d30;
  --chart-hidden: #21334b;
  --chart-grid: #7285a63a;
  --chart-label: #b2c0d5;
  --chart-divider: #83a0c4;
  --chart-text: #f4f7ff;
  --chart-actual: #f2f7fd;
  --chart-own: #49c5d9;
  --chart-edge: #7490ba47;
  color: var(--chart-text);
  max-width: 1010px;
  margin-inline: auto;
  scroll-margin-top: 90px;
}
.chart-heading { display: flex; justify-content: space-between; align-items: end; gap: 16px; margin-bottom: 13px; }
.chart-heading p { margin: 0 0 5px; }
.chart-heading h1 { margin: 0; max-width: 24ch; font-size: clamp(26px, 4.2vw, 47px); line-height: 1.08; text-wrap: balance; }
.chart-progress { flex: none; display: grid; justify-items: end; gap: 5px; color: var(--chart-label); font-size: 12px; }
.chart-steps { display: flex; gap: 4px; }
.chart-steps span { width: 12px; height: 4px; border-radius: 6px; background: var(--chart-edge); }
.chart-steps .is-past { background: #4898b6; }
.chart-steps .is-current { background: #78e4da; }
.chart-progress time { min-width: 52px; padding: 4px 7px; border-radius: 6px; text-align: center; color: var(--chart-text); background: var(--chart-fill); font: 750 14px/1.3 system-ui; font-variant-numeric: tabular-nums; }
.chart-progress time.is-low { color: #ff93ac; }
.chart-stage, .chart-final, .chart-review {
  min-width: 0;
  padding: clamp(10px,2vw,22px);
  border: 1px solid var(--chart-edge);
  border-radius: 17px;
  background: var(--chart-fill);
}
.chart-stage h2, .chart-review h2 { margin: 0 0 8px; font-size: clamp(17px,2vw,22px); }
.chart-unit { margin: 0 0 2px 6px; color: var(--chart-label); font-size: 13px; }
.chart-canvas {
  display: block;
  width: 100%;
  height: clamp(300px, 53vh, 510px);
  user-select: none;
}
.chart-canvas[tabindex] { cursor: crosshair; touch-action: none; }
.chart-canvas:focus-visible { border-radius: 5px; outline: 2px solid #59cddd; }
.chart-drawing-footer, .chart-actions, .chart-legend, .chart-footer, .chart-stats {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px 12px;
}
.chart-drawing-footer { justify-content: space-between; margin-top: 11px; }
.chart-drawing-footer > div { display: grid; gap: 4px; color: var(--chart-label); font-size: 12px; }
.chart-drawing-footer [data-chart-status] { color: var(--chart-text); }
.chart-actions .primary { min-width: 112px; }
.chart-legend { margin-top: 12px; }
.chart-legend button { display: inline-flex; align-items: center; gap: 6px; min-height: 35px; padding: 5px 8px; }
.chart-legend button[aria-pressed="true"], .chart-review-tabs button[aria-pressed="true"] { border-color: #49b3cf; }
.chart-legend button::before, .chart-actual-label::before {
  content: "";
  width: 12px;
  height: 3px;
  border-radius: 7px;
  background: var(--series-color,var(--chart-actual));
}
.chart-actual-label { display: inline-flex; align-items: center; gap: 6px; font-size: 12px; color: var(--chart-label); }
.chart-stats { margin: 10px 0; }
