  --country-tile:#172742;--country-accent:#94f6e4;--country-alert:#ffb3aa;
  display:grid;gap:12px;padding:clamp(13px,3vw,25px);border:1px solid var(--country-line);
  border-radius:22px;color:var(--country-text);
  background:radial-gradient(ellipse at 5% 0,#28496d,transparent 62%),var(--country-bg);
}
.country-heading { display:flex;justify-content:space-between;align-items:center;gap:8px;min-height:30px; }
.country-heading .eyebrow { color:var(--country-accent);margin:0; }
.country-panel h1 { color:var(--country-text);font-size:clamp(1.4rem,4.2vw,2.35rem);line-height:1.12;margin:0;overflow-wrap:anywhere; }
.country-timer {
  min-width:56px;border:1px solid var(--country-line);border-radius:9px;text-align:center;
  padding:4px 7px;color:var(--country-accent);background:var(--country-tile);
  font-weight:800;font-size:.86rem;font-variant-numeric:tabular-nums;white-space:nowrap;
}
.country-timer[data-urgent="true"] { color:var(--country-alert); }
.country-stage {
  height:clamp(176px,46vw,342px);display:grid;grid-template: minmax(0,1fr) / minmax(0,1fr);
  place-items:center;padding:clamp(11px,3vw,26px);
  border:1px solid var(--country-line);border-radius:15px;
  background:radial-gradient(ellipse at center,#fff,#dce6f0);
