.country-form input,.country-form button { min-height:44px; }
.country-form input { min-width:0;width:100%; }
.country-reveal { color:var(--country-accent);font-weight:850;margin:0;animation:countryAppear .2s ease-out both; }
.country-scores { display:grid;grid-template-columns:repeat(auto-fit,minmax(min(145px,100%),1fr));gap:6px;margin:0;padding:0;list-style:none; }
.country-scores li {
  display:flex;align-items:center;justify-content:space-between;gap:6px;min-width:0;padding:6px 9px;
  background:var(--country-tile);border:1px solid var(--country-line);border-radius:9px;
}
.country-scores b { flex:none;color:var(--country-accent);font-size:.83rem; }
.country-scores .mini-player { flex:1;min-width:0; }
.country-scores .nick { min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap; }
.country-scores .level-badge:not(.bot-level-badge) { display:none; }
.country-panel>.primary { justify-self:start; }
.country-game .leave-game { margin-top:10px; }
.light-theme .country-panel {
  --country-bg:#fafcff;--country-text:#162c48;--country-line:#afc3d8;
  --country-tile:#eaf3fa;--country-accent:#065950;--country-alert:#a02b1a;
  background:radial-gradient(ellipse at 5% 0,#dfecf9,transparent 75%),var(--country-bg);
